                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className="px-2 py-1 bg-slate-100 text-slate-600 text-[11px] font-bold rounded uppercase">
                    {categoryLabels[doc.category as keyof typeof categoryLabels]}
