                <div className={`w-2 h-2 rounded-full animate-pulse ${currentUser.role === UserRole.ADMIN ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
                <span className="text-xs font-bold text-slate-700 uppercase tracking-tight">
                  Sessão {currentUser.role === UserRole.ADMIN ? 'Administrativa' : 'do Cliente'}
