import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import InvoiceIssuance from './components/InvoiceIssuance';
import RevenueTaxTracker from './components/RevenueTaxTracker';
import Login from './components/Login';
import { View, UserRole, User } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  // No mobile, iniciamos colapsado para maximizar área de dados
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);

  // Listener para redimensionamento
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role
    });
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
  };

  const renderContent = () => {
    if (!currentUser) return null;
    if (currentUser.role === UserRole.CLIENT) {
      if (currentView === View.CLIENTS || currentView === View.TAXES) {
        return <Dashboard />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard />;
      case View.CLIENTS: return <ClientManagement />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker />;
      case View.REVENUE: return <RevenueSchedule />;
      case View.REVENUE_TAXES: return <RevenueTaxTracker />;
      case View.INVOICE_ISSUE: return <InvoiceIssuance />;
      case View.AI_CHAT: return <AIChat />;
      default: return <Dashboard />;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden selection:bg-blue-100 selection:text-blue-700">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout}
      />

      <main 
        className={`flex-1 transition-all duration-300 ease-in-out ${
          isSidebarCollapsed ? 'ml-[68px]' : 'ml-64'
        }`}
      >
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
            <div className="flex items-center space-x-3">
              <div className="md:hidden">
                 {/* Placeholder for future mobile specific header element */}
              </div>
              <div className="space-y-0.5">
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Portal Axis</p>
                <h1 className="text-xl font-bold text-slate-800 capitalize tracking-tight">
                   {currentView.replace(/_/g, ' ')}
                </h1>
              </div>
            </div>

            <div className="flex items-center space-x-3 self-end md:self-auto">
              <div className="flex items-center space-x-2 px-3 py-1.5 bg-white rounded-xl shadow-sm border border-slate-100">
                <div className={`w-2 h-2 rounded-full animate-pulse ${currentUser.role === UserRole.ADMIN ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-emerald-500 shadow-[0_0_8px_#10b981]'}`}></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">
                  {currentUser.role === UserRole.ADMIN ? 'Administrador' : 'Cliente Premium'}
                </span>
              </div>

              <button className="p-2 text-slate-400 hover:text-blue-600 bg-white rounded-xl shadow-sm border border-slate-100 transition-all hover:scale-105 active:scale-95">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 17h5l-1.405-1.405A2.032 2.032 0 0118 14.158V11a6.002 6.002 0 00-4-5.659V5a2 2 0 10-4 0v.341C7.67 6.165 6 8.388 6 11v3.159c0 .538-.214 1.055-.595 1.436L4 17h5m6 0v1a3 3 0 11-6 0v-1m6 0H9" /></svg>
              </button>
            </div>
          </header>

          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
            {renderContent()}
          </div>
        </div>
      </main>

      {currentView !== View.AI_CHAT && (
        <button 
          onClick={() => setCurrentView(View.AI_CHAT)}
          className="fixed bottom-6 right-6 bg-slate-900 text-white p-4 rounded-2xl shadow-2xl hover:bg-blue-600 hover:scale-110 transition-all z-40 group flex items-center space-x-2 border border-white/10"
        >
          <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-300 whitespace-nowrap font-bold text-sm">
            Falar com Axis AI
          </span>
          <svg className="w-6 h-6 text-blue-400 group-hover:text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
        </button>
      )}
    </div>
  );
};

