import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import InvoiceIssuance from './components/InvoiceIssuance';
import RevenueTaxTracker from './components/RevenueTaxTracker';
import Login from './components/Login';
import { View, UserRole, User, Client } from './types';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);

  // Novo estado para o administrador focar em um cliente específico
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role
    });
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const renderContent = () => {
    if (!currentUser) return null;

    // Se o admin estiver focando em um cliente, ele vê as views como se fosse o cliente
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || isImpersonating) {
      // Views permitidas para Cliente (ou Admin focando em um)
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        // Caso tente acessar view admin em modo de foco, volta pro dashboard
        case View.CLIENTS: return <ClientManagement onSelectClient={handleSelectClient} />;
        default: return <Dashboard focusedClient={focusedClient} />;
      }
    }

    // Views puras de Admin
    switch (currentView) {
      case View.DASHBOARD: return <Dashboard />;
      case View.CLIENTS: return <ClientManagement onSelectClient={handleSelectClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker />;
      case View.AI_CHAT: return <AIChat />;
      default: return <Dashboard />;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout}
        hasActiveFocus={!!focusedClient}
      />

      <main 
        className={`flex-1 transition-all duration-300 ease-in-out ${
          isSidebarCollapsed ? 'ml-[68px]' : 'ml-64'
        }`}
      >
        {/* Banner de Modo de Foco para Admin */}
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-6 py-2 flex items-center justify-between shadow-md animate-in slide-in-from-top duration-300">
            <div className="flex items-center space-x-2">
              <span className="text-lg">👁️</span>
              <p className="text-xs font-bold uppercase tracking-tight">
                Modo de Foco: <span className="underline">{focusedClient.name}</span>
              </p>
            </div>
            <div className="flex items-center space-x-3">
              <button 
                onClick={() => setCurrentView(View.CLIENTS)}
                className="text-[10px] font-black uppercase bg-amber-600/20 hover:bg-amber-600/40 px-3 py-1 rounded-lg transition-all"
              >
                Trocar Cliente
              </button>
              <button 
                onClick={() => setFocusedClient(null)}
                className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg transition-all border border-amber-600/30"
              >
                Sair do Foco
              </button>
            </div>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">
                {focusedClient ? 'Gestão de Cliente' : 'Painel Administrativo'}
              </p>
              <h1 className="text-xl font-bold text-slate-800 capitalize tracking-tight">
                 {currentView.replace(/_/g, ' ')}
              </h1>
            </div>

            <div className="flex items-center space-x-3 self-end md:self-auto">
              <div className="flex items-center space-x-2 px-3 py-1.5 bg-white rounded-xl shadow-sm border border-slate-100">
                <div className={`w-2 h-2 rounded-full animate-pulse ${currentUser.role === UserRole.ADMIN ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-emerald-500 shadow-[0_0_8px_#10b981]'}`}></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">
                  {currentUser.role === UserRole.ADMIN ? 'Administrador Axis' : 'Cliente Premium'}
                </span>
              </div>

              <button className="p-2 text-slate-400 hover:text-blue-600 bg-white rounded-xl shadow-sm border border-slate-100 transition-all">
