          <p className="text-2xl font-black text-slate-800 mt-1">{clients.length} Ativos</p>
          <div className="mt-2 flex items-center text-emerald-500 text-xs font-bold">
            <span>Gestão Ativa 2024</span>
          </div>
        </div>
        <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm border-l-4 border-l-red-500">
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Atenção Sublimite</p>
          <p className="text-2xl font-black text-red-600 mt-1">{clientsWithSublimitIssues} Empresa(s)</p>
          <div className="mt-2 flex items-center text-red-500 text-xs font-bold">
            <span>Pagam ISS/ICMS por fora</span>
