                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <p className={`text-sm font-black ${isOverLimit ? 'text-red-600' : isNearLimit ? 'text-amber-600' : 'text-slate-700'}`}>
                        {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(annualRev)}
