                        </button>
                        <button 
                          onClick={() => onDeleteClient(client.id)}
                          title="Remover Cliente"
                          className="p-2.5 bg-red-50 text-red-600 rounded-xl hover:bg-red-600 hover:text-white transition-all border border-red-100 active:scale-90"
                        >
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              }) : (
                <tr>
                  <td colSpan={4} className="px-6 py-12 text-center text-slate-400 font-medium italic">
                    Nenhuma empresa encontrada com estes critérios.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default ClientManagement;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import InvoiceIssuance from './components/InvoiceIssuance';
import RevenueTaxTracker from './components/RevenueTaxTracker';
import Login from './components/Login';
import { View, UserRole, User, Client } from './types';

const initialClients: Client[] = [
  { id: '1', name: 'Tecnologia Avançada LTDA', identifier: '12.345.678/0001-90', email: 'contato@techavancada.com', status: 'active', type: 'PJ', createdAt: '2024-01-10', annualRevenue: 1450000 },
  { id: '2', name: 'Ana Maria Ferreira', identifier: '123.456.789-00', email: 'ana.ferreira@email.com', status: 'active', type: 'PF', createdAt: '2024-03-22', annualRevenue: 85000 },
  { id: '3', name: 'Logística Express S.A.', identifier: '98.765.432/0001-21', email: 'financeiro@logexpress.com.br', status: 'active', type: 'PJ', createdAt: '2023-11-05', annualRevenue: 3850000 },
  { id: '4', name: 'Padaria do Bairro', identifier: '44.333.222/0001-11', email: 'contato@padaria.com', status: 'active', type: 'PJ', createdAt: '2024-05-15', annualRevenue: 2950000 },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);

  // Lista de clientes global para permitir adição e deleção
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role
    });
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const handleAddClient = (client: Client) => {
    setClients(prev => [client, ...prev]);
  };

  const handleDeleteClient = (clientId: string) => {
    const clientToDelete = clients.find(c => c.id === clientId);
    if (!clientToDelete) return;

    if (confirm(`⚠️ EXCLUSÃO CRÍTICA: Deseja remover permanentemente o cliente "${clientToDelete.name}"? Todos os documentos e históricos serão apagados.`)) {
      setClients(prev => prev.filter(c => c.id !== clientId));
      // Se o cliente deletado era o focado, limpa o foco imediatamente
      if (focusedClient?.id === clientId) {
        setFocusedClient(null);
        setCurrentView(View.CLIENTS);
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;

    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} />;
        default: return <Dashboard focusedClient={focusedClient} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker />;
      case View.AI_CHAT: return <AIChat />;
      default: return <Dashboard />;
    }
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed}
        setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout}
        hasActiveFocus={!!focusedClient}
      />

      <main 
        className={`flex-1 transition-all duration-300 ease-in-out ${
          isSidebarCollapsed ? 'ml-[68px]' : 'ml-64'
        }`}
      >
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-6 py-2 flex items-center justify-between shadow-md animate-in slide-in-from-top duration-300">
            <div className="flex items-center space-x-2">
              <span className="text-lg">👁️</span>
              <p className="text-xs font-bold uppercase tracking-tight">
                Modo de Foco: <span className="underline">{focusedClient.name}</span>
              </p>
            </div>
            <div className="flex items-center space-x-2">
              <button 
                onClick={() => handleDeleteClient(focusedClient.id)}
                className="text-[10px] font-black uppercase bg-red-600/20 hover:bg-red-600 text-red-900 hover:text-white px-3 py-1 rounded-lg transition-all border border-red-600/30 mr-2"
              >
                Excluir Empresa
              </button>
              <button 
                onClick={() => setCurrentView(View.CLIENTS)}
                className="text-[10px] font-black uppercase bg-amber-600/20 hover:bg-amber-600/40 px-3 py-1 rounded-lg transition-all"
              >
                Trocar Cliente
              </button>
              <button 
                onClick={() => setFocusedClient(null)}
                className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg transition-all border border-amber-600/30"
              >
                Sair do Foco
              </button>
            </div>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">
                {focusedClient ? 'Gestão de Cliente' : 'Painel Administrativo'}
              </p>
              <h1 className="text-xl font-bold text-slate-800 capitalize tracking-tight">
                 {currentView.replace(/_/g, ' ')}
              </h1>
            </div>

            <div className="flex items-center space-x-3 self-end md:self-auto">
              <div className="flex items-center space-x-2 px-3 py-1.5 bg-white rounded-xl shadow-sm border border-slate-100">
                <div className={`w-2 h-2 rounded-full animate-pulse ${currentUser.role === UserRole.ADMIN ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : 'bg-emerald-500 shadow-[0_0_8px_#10b981]'}`}></div>
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">
                  {currentUser.role === UserRole.ADMIN ? 'Administrador Axis' : 'Cliente Premium'}
                </span>
              </div>
            </div>
          </header>

          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">
            {renderContent()}
          </div>
        </div>
      </main>

      {currentView !== View.AI_CHAT && (
        <button 
          onClick={() => setCurrentView(View.AI_CHAT)}
          className="fixed bottom-6 right-6 bg-slate-900 text-white p-4 rounded-2xl shadow-2xl hover:bg-blue-600 hover:scale-110 transition-all z-40 group flex items-center space-x-2 border border-white/10"
        >
          <span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-300 whitespace-nowrap font-bold text-sm">
            Falar com Axis AI
          </span>
          <svg className="w-6 h-6 text-blue-400 group-hover:text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
        </button>
      )}
    </div>
  );
};

export default App;

