import { Client, PortalIntegration } from '../types';

interface ClientManagementProps {
  clients: Client[];
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [showConnectorModal, setShowConnectorModal] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [newClient, setNewClient] = useState({ 
    name: '', 
    identifier: '', 
    email: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '' 
  });

  // Estado para o formulário de integração
  const [connectorForm, setConnectorForm] = useState({
    city: 'São Paulo' as 'São Paulo' | 'Salvador',
    certPassword: '',
    isUploading: false
  });

  const handleAddClient = (e: React.FormEvent) => {
    e.preventDefault();
    const client: Client = {
      id: Math.random().toString(36).substr(2, 9),
      name: newClient.name,
      identifier: newClient.identifier,
      email: newClient.email,
      type: newClient.type,
      status: 'active',
      createdAt: new Date().toISOString().split('T')[0],
      annualRevenue: parseFloat(newClient.annualRevenue) || 0,
      integrations: []
    };
    onAddClient(client);
    setShowForm(false);
    setNewClient({ name: '', identifier: '', email: '', type: 'PJ', annualRevenue: '' });
  };

  const handleConnectPortal = () => {
    if (!showConnectorModal) return;

    setConnectorForm(prev => ({ ...prev, isUploading: true }));

    // Simulação de handshake com a API da prefeitura e validação de certificado
    setTimeout(() => {
      const newIntegration: PortalIntegration = {
        city: connectorForm.city,
        status: 'connected',
        lastSync: new Date().toISOString()
      };

      const updatedClient: Client = {
        ...showConnectorModal,
        hasCertificate: true,
        integrations: [...(showConnectorModal.integrations || []), newIntegration]
      };

      onUpdateClient?.(updatedClient);
      setConnectorForm(prev => ({ ...prev, isUploading: false, certPassword: '' }));
      setShowConnectorModal(null);
      alert(`Conectado com sucesso à Prefeitura de ${connectorForm.city}! As notas serão sincronizadas em tempo real.`);
    }, 2000);
  };

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.identifier.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      {/* Modal de Conectores Fiscais */}
      {showConnectorModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-lg rounded-[2rem] shadow-2xl overflow-hidden border border-slate-200">
            <header className="bg-slate-900 p-8 text-white relative">
              <button onClick={() => setShowConnectorModal(null)} className="absolute top-6 right-6 text-slate-400 hover:text-white transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
              <div className="flex items-center space-x-4 mb-2">
                <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-2xl">🔌</div>
                <div>
                  <h3 className="text-xl font-black tracking-tight">Conector Prefeitura API</h3>
                  <p className="text-blue-300 text-xs font-bold uppercase tracking-widest">Integração via Certificado Digital</p>
                </div>
              </div>
            </header>

            <div className="p-8 space-y-6">
              <div className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">Selecione o Portal</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button 
                      onClick={() => setConnectorForm({...connectorForm, city: 'São Paulo'})}
                      className={`p-4 rounded-xl border-2 transition-all flex flex-col items-center text-center space-y-2 ${connectorForm.city === 'São Paulo' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 hover:border-slate-200'}`}
