                      onClick={() => setConnectorForm({...connectorForm, city: 'Salvador'})}
                      className={`p-4 rounded-xl border-2 transition-all flex flex-col items-center text-center space-y-2 ${connectorForm.city === 'Salvador' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 hover:border-slate-200'}`}
                    >
                      <span className="text-2xl">🏖️</span>
                      <span className="text-xs font-black text-slate-800">SALVADOR</span>
