import { TaxAnexo } from '../types';

interface TaxBracket {
  limit: number;
  nominalRate: number;
  deduction: number;
}

const TABLES: Record<TaxAnexo, TaxBracket[]> = {
  'I': [
    { limit: 180000, nominalRate: 0.04, deduction: 0 },
    { limit: 360000, nominalRate: 0.073, deduction: 5940 },
    { limit: 720000, nominalRate: 0.095, deduction: 13860 },
    { limit: 1800000, nominalRate: 0.107, deduction: 22500 },
    { limit: 3600000, nominalRate: 0.143, deduction: 87300 },
    { limit: 4800000, nominalRate: 0.19, deduction: 378000 },
  ],
  'III': [
    { limit: 180000, nominalRate: 0.06, deduction: 0 },
    { limit: 360000, nominalRate: 0.112, deduction: 9360 },
    { limit: 720000, nominalRate: 0.135, deduction: 17640 },
    { limit: 1800000, nominalRate: 0.16, deduction: 35640 },
    { limit: 3600000, nominalRate: 0.21, deduction: 125640 },
    { limit: 4800000, nominalRate: 0.33, deduction: 648000 },
  ],
  // Outros anexos simplificados para o exemplo
  'II': [{ limit: 4800000, nominalRate: 0.045, deduction: 0 }],
  'IV': [{ limit: 4800000, nominalRate: 0.045, deduction: 0 }],
  'V': [{ limit: 4800000, nominalRate: 0.155, deduction: 0 }],
};

export const calculateSimplesNacional = (rbt12: number, monthlyRevenue: number, anexo: TaxAnexo = 'III') => {
  const table = TABLES[anexo];
  const bracket = table.find(b => rbt12 <= b.limit) || table[table.length - 1];

  // Fórmula: ((RBT12 * Alíquota Nominal) - Parcela a Deduzir) / RBT12
  // Se RBT12 for 0 (empresa nova), usa a alíquota da primeira faixa
  let effectiveRate = 0;
  if (rbt12 === 0) {
    effectiveRate = table[0].nominalRate;
  } else {
    effectiveRate = ((rbt12 * bracket.nominalRate) - bracket.deduction) / rbt12;
  }

  // O Simples Nacional tem travas de alíquota efetiva mínima e máxima dependendo do anexo, 
  // mas aqui simplificamos para a fórmula base.

  const taxAmount = monthlyRevenue * effectiveRate;

  return {
    effectiveRate,
    nominalRate: bracket.nominalRate,
    deduction: bracket.deduction,
    taxAmount,
    bracketLimit: bracket.limit
  };
};

