              <h3 className="text-xl font-black mb-4">Configurar Integração: {showConnectorModal.name}</h3>
              <div className="space-y-4">
                 <select 
                    value={connectorForm.city}
                    onChange={(e) => setConnectorForm({...connectorForm, city: e.target.value as any})}
                    className="w-full p-3 border rounded-xl"
                 >
                    <option value="São Paulo">São Paulo (Nota do Milhão)</option>
                    <option value="Salvador">Salvador (Nota Salvador)</option>
                 </select>
                 <input type="password" placeholder="Senha do Certificado" className="w-full p-3 border rounded-xl" />
                 <button onClick={handleConnectPortal} className="w-full py-4 bg-blue-600 text-white rounded-xl font-bold">
                    {connectorForm.isUploading ? 'Conectando...' : 'Ativar API'}
                 </button>
                 <button onClick={() => setShowConnectorModal(null)} className="w-full py-2 text-slate-400">Cancelar</button>
              </div>
           </div>
        </div>
      )}

      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
        <div className="relative flex-1 max-w-md">
          <input 
            type="text" 
            placeholder="Buscar empresa..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`px-6 py-2.5 rounded-xl font-black text-xs uppercase tracking-widest ${
            showForm ? 'bg-red-50 text-red-600' : 'bg-slate-900 text-white'
          }`}
        >
          {showForm ? 'Fechar' : 'Nova Empresa'}
        </button>
      </header>

      {showForm && (
        <div className="bg-white p-8 rounded-2xl shadow-xl border-2 border-blue-500/10 animate-in slide-in-from-top">
          <h3 className="font-black text-slate-800 mb-6 uppercase text-sm">Cadastro de Cliente e Enquadramento</h3>
          <form onSubmit={handleAddClient} className="grid grid-cols-1 md:grid-cols-3 gap-6">
