import React, { useState, useMemo } from 'react';
import { Revenue, Client } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
}

const months = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

// Dados simulados expandidos para o ano todo
const generateYearlyData = (baseAmount: number): Revenue[] => {
  const data: Revenue[] = [];
  const clients = ['Banco Itaú S.A.', 'Starbucks Brasil', 'Consultoria Global', 'Projeto Alpha X', 'Licenciamento Software', 'Posto Ipiranga', 'Magazine Luiza', 'Airbnb Inc'];

  for (let m = 0; m < 12; m++) {
    const monthStr = (m + 1).toString().padStart(2, '0');
    // Simula 4 a 8 entradas por mês para o escritório global
    const entriesCount = 4 + Math.floor(Math.random() * 4);
    for (let i = 0; i < entriesCount; i++) {
      const isPast = m < 5; // Simula que até Maio já foi recebido
      data.push({
        id: `rev-${m}-${i}`,
        client: clients[Math.floor(Math.random() * clients.length)],
        amount: baseAmount + (Math.random() * 8000),
        date: `2024-${monthStr}-${(5 + i * 3).toString().padStart(2, '0')}`,
        status: isPast ? 'received' : (Math.random() > 0.3 ? 'expected' : 'received'),
        description: `Serviços contábeis ref. ciclo ${monthStr}/24`
      });
    }
  }
  return data;
};

const SUB_LIMIT = 3600000;

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient }) => {
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'expected'>('all');

  const allRevenues = useMemo(() => {
    // Se tiver cliente focado, usamos uma base menor, senão a base do escritório
    return generateYearlyData(focusedClient ? 4000 : 45000);
  }, [focusedClient]);

  // Agrupamento por mês (Totalizadores fixos do ano)
  const monthlyTotals = useMemo(() => {
    const totals = new Array(12).fill(0);
    allRevenues.forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [allRevenues]);

  const annualTotal = monthlyTotals.reduce((a, b) => a + b, 0);

  // Filtragem complexa para a listagem
  const filteredRevenues = useMemo(() => {
    return allRevenues.filter(rev => {
      const matchesMonth = parseInt(rev.date.split('-')[1]) - 1 === selectedMonthIdx;
      const matchesSearch = rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            rev.description?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || rev.status === statusFilter;

      return matchesMonth && matchesSearch && matchesStatus;
    });
  }, [allRevenues, selectedMonthIdx, searchTerm, statusFilter]);

  // Cálculo de quando o sublimite é atingido
  let accumulated = 0;
  const sublimitMonthIdx = monthlyTotals.findIndex(total => {
    accumulated += total;
    return accumulated >= SUB_LIMIT;
  });

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4 bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
        <div>
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] mb-1">Planejamento Financeiro</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">
            {focusedClient ? `Cronograma Anual: ${focusedClient.name}` : 'Fluxo de Receitas do Escritório'}
          </h2>
          <p className="text-slate-500 text-sm">Acompanhamento completo de entradas e projeção de faturamento 2024.</p>
        </div>
        <div className="text-left md:text-right bg-slate-50 p-4 rounded-xl border border-slate-100 min-w-[200px]">
          <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest mb-1">Total Acumulado (YTD)</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">
            {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(annualTotal)}
          </p>
          {annualTotal >= SUB_LIMIT && (
            <span className="text-[9px] font-black text-red-600 bg-red-50 px-2 py-0.5 rounded-full uppercase border border-red-100 mt-1 block w-fit ml-auto">Sublimite Excedido</span>
          )}
        </div>
      </header>

      {/* Grid Anual de 12 Meses */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
        {months.map((month, idx) => {
          const isSelected = selectedMonthIdx === idx;
          const isSublimitMonth = idx === sublimitMonthIdx;
          const isPastSublimit = sublimitMonthIdx !== -1 && idx > sublimitMonthIdx;

          return (
            <button
              key={month}
              onClick={() => setSelectedMonthIdx(idx)}
              className={`p-4 rounded-2xl border transition-all text-left relative overflow-hidden group ${
                isSelected 
                  ? 'bg-slate-900 border-slate-900 text-white shadow-xl scale-[1.02] z-10' 
                  : 'bg-white border-slate-100 text-slate-600 hover:border-blue-200 hover:shadow-md'
              }`}
            >
              <p className={`text-[10px] font-black uppercase tracking-tighter ${isSelected ? 'text-blue-400' : 'text-slate-400'}`}>
                {month.substring(0, 3)}
              </p>
              <p className="text-sm font-black mt-1">
                {new Intl.NumberFormat('pt-BR', { notation: 'compact' }).format(monthlyTotals[idx])}
              </p>

              <div className="mt-2 w-full h-1 bg-slate-100 rounded-full overflow-hidden">
                <div 
                  className={`h-full ${isSelected ? 'bg-blue-400' : isSublimitMonth || isPastSublimit ? 'bg-red-400' : 'bg-emerald-400'}`} 
                  style={{ width: `${Math.min((monthlyTotals[idx] / (annualTotal / 12)) * 100, 100)}%` }}
                ></div>
              </div>

              {isSublimitMonth && (
                <div className="absolute top-1 right-1">
                  <span className="flex h-2 w-2 rounded-full bg-red-500 animate-ping"></span>
                </div>
              )}
            </button>
          );
        })}
      </div>

      {/* TOOLBAR DE FILTROS */}
      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 w-full">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Filtrar por cliente ou serviço..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/20 outline-none transition-all placeholder:text-slate-400"
          />
        </div>

        <div className="flex bg-slate-100 p-1 rounded-xl w-full md:w-auto">
          {[
            { id: 'all', label: 'Todos', icon: '📋' },
            { id: 'received', label: 'Liquidados', icon: '✅' },
            { id: 'expected', label: 'Previstos', icon: '⏳' }
          ].map(filter => (
            <button
              key={filter.id}
              onClick={() => setStatusFilter(filter.id as any)}
              className={`flex-1 md:flex-none px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all flex items-center justify-center space-x-2 ${
                statusFilter === filter.id 
                  ? 'bg-white text-blue-600 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <span>{filter.icon}</span>
              <span>{filter.label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Detalhamento do Mês Selecionado */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-6 border-b border-slate-50 flex items-center justify-between bg-slate-50/50">
          <div className="flex items-center space-x-3">
            <h3 className="font-black text-slate-800 uppercase tracking-tight">
              Listagem: {months[selectedMonthIdx]}
            </h3>
            <span className="bg-blue-600 text-white px-2.5 py-1 rounded-full text-[9px] font-black uppercase tracking-wider shadow-lg shadow-blue-500/20">
              {filteredRevenues.length} encontrados
            </span>
          </div>
          <div className="flex items-center space-x-2">
            {(searchTerm || statusFilter !== 'all') && (
              <button 
                onClick={() => {setSearchTerm(''); setStatusFilter('all')}}
                className="text-[10px] font-black text-red-500 hover:underline uppercase tracking-widest mr-4"
              >
                Limpar Filtros
              </button>
            )}
            <button className="p-2 hover:bg-white rounded-lg transition-all text-slate-400 hover:text-blue-600 group">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
            </button>
          </div>
        </div>

        <div className="divide-y divide-slate-50 max-h-[600px] overflow-y-auto no-scrollbar">
          {filteredRevenues.length > 0 ? filteredRevenues.map((item) => (
            <div key={item.id} className="p-6 flex items-center justify-between hover:bg-slate-50/50 transition-colors group">
              <div className="flex items-center space-x-4">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-lg shadow-sm transition-transform group-hover:scale-110 ${
                  item.status === 'received' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-blue-50 text-blue-600 border border-blue-100'
                }`}>
                  {item.date.split('-')[2]}
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-sm group-hover:text-blue-600 transition-colors">{item.client}</h4>
                  <p className="text-[10px] text-slate-400 font-medium uppercase tracking-tighter">
                    {item.status === 'received' ? 'Recebido em' : 'Previsão para'} {item.date.split('-').reverse().join('/')}
                  </p>
                  <p className="text-[10px] text-slate-300 italic truncate max-w-[200px] md:max-w-md mt-0.5">{item.description}</p>
                </div>
              </div>

              <div className="text-right">
                <p className="font-black text-slate-800">
                  {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(item.amount)}
                </p>
                <div className="flex items-center justify-end space-x-1 mt-1">
                   <div className={`w-1.5 h-1.5 rounded-full ${item.status === 'received' ? 'bg-emerald-500 animate-pulse' : 'bg-blue-500'}`}></div>
                   <span className={`text-[9px] font-black uppercase tracking-widest ${
                    item.status === 'received' ? 'text-emerald-500' : 'text-blue-500'
                  }`}>
                    {item.status === 'received' ? 'Liquidado' : 'Aguardando'}
                  </span>
                </div>
              </div>
            </div>
          )) : (
            <div className="p-20 text-center flex flex-col items-center">
              <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center text-3xl mb-4">🔍</div>
              <p className="text-slate-400 font-black uppercase tracking-widest text-[10px]">Nenhum lançamento corresponde aos filtros</p>
              <button 
                onClick={() => {setSearchTerm(''); setStatusFilter('all')}}
                className="mt-4 text-blue-600 text-xs font-bold hover:underline"
              >
                Remover todos os filtros
              </button>
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-50/80 border-t border-slate-100 flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center space-x-6">
            <div className="flex items-center space-x-2">
              <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
              <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Liquidado</span>
