                    <button onClick={() => onSelectClient?.(client)} className="p-2.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-all" title="Ver Dashboard"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg></button>
                    <button onClick={() => onDeleteClient(client.id)} className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" title="Excluir"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ClientManagement;

import React, { useState, useEffect } from 'react';
import { Client, PortalIntegration, TaxAnexo } from '../types';

interface ClientManagementProps {
  clients: Client[];
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [showConnectorModal, setShowConnectorModal] = useState<Client | null>(null);
  const [editingClient, setEditingClient] = useState<Client | null>(null); // Estado para o cliente em edição
  const [searchTerm, setSearchTerm] = useState('');

  // Estado para o formulário de novo cliente
  const [newClient, setNewClient] = useState({ 
    name: '', 
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '',
    taxAnexo: 'III' as TaxAnexo,
    cnae: ''
  });

  // Estado para o formulário de edição (espelha a estrutura do Client)
  const [editFormData, setEditFormData] = useState<Partial<Client>>({});

  const [connectorForm, setConnectorForm] = useState({
    city: 'São Paulo' as 'São Paulo' | 'Salvador',
    certPassword: '',
    isUploading: false
  });

  // Sincroniza o formulário de edição quando um cliente é selecionado para editar
  useEffect(() => {
    if (editingClient) {
      setEditFormData({ ...editingClient });
    }
  }, [editingClient]);

  const handleAddClient = (e: React.FormEvent) => {
    e.preventDefault();
    const client: Client = {
      id: Math.random().toString(36).substr(2, 9),
      name: newClient.name,
      identifier: newClient.identifier,
      email: newClient.email,
      phone: newClient.phone,
      type: newClient.type,
      status: 'active',
      createdAt: new Date().toISOString().split('T')[0],
      annualRevenue: parseFloat(newClient.annualRevenue) || 0,
      taxAnexo: newClient.taxAnexo,
      cnae: newClient.cnae,
      integrations: []
    };
    onAddClient(client);
    setShowForm(false);
    setNewClient({ name: '', identifier: '', email: '', phone: '', type: 'PJ', annualRevenue: '', taxAnexo: 'III', cnae: '' });
  };

  const handleUpdateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingClient && onUpdateClient && editFormData) {
      onUpdateClient(editFormData as Client);
      setEditingClient(null);
    }
  };

  const handleConnectPortal = () => {
    if (!showConnectorModal) return;
    setConnectorForm(prev => ({ ...prev, isUploading: true }));
    setTimeout(() => {
      const newIntegration: PortalIntegration = {
        city: connectorForm.city,
        status: 'connected',
        lastSync: new Date().toISOString()
      };
      const updatedClient: Client = {
        ...showConnectorModal,
        hasCertificate: true,
        integrations: [...(showConnectorModal.integrations || []), newIntegration]
      };
      onUpdateClient?.(updatedClient);
      setConnectorForm(prev => ({ ...prev, isUploading: false, certPassword: '' }));
      setShowConnectorModal(null);
      alert(`Conectado à Prefeitura de ${connectorForm.city}!`);
    }, 1500);
  };

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.identifier.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      {/* MODAL DE EDIÇÃO DE CLIENTE */}
      {editingClient && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl p-8 md:p-12 animate-in zoom-in slide-in-from-bottom-4 duration-300 my-8">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center space-x-4">
                <div className="w-14 h-14 bg-slate-900 text-white rounded-2xl flex items-center justify-center text-2xl shadow-xl">📝</div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Editar Dados da Empresa</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-0.5">ID: {editingClient.id}</p>
                </div>
              </div>
              <button onClick={() => setEditingClient(null)} className="p-3 hover:bg-slate-100 rounded-full transition-all">
                <svg className="w-6 h-6 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleUpdateSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social / Nome</label>
                <input required value={editFormData.name || ''} onChange={(e) => setEditFormData({...editFormData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNPJ / CPF</label>
                <input required value={editFormData.identifier || ''} onChange={(e) => setEditFormData({...editFormData, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">WhatsApp</label>
                <input required value={editFormData.phone || ''} onChange={(e) => setEditFormData({...editFormData, phone: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-emerald-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail Financeiro</label>
                <input required type="email" value={editFormData.email || ''} onChange={(e) => setEditFormData({...editFormData, email: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Faturamento (RBT12)</label>
                <input required type="number" value={editFormData.annualRevenue || 0} onChange={(e) => setEditFormData({...editFormData, annualRevenue: parseFloat(e.target.value)})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Anexo Simples</label>
                <select value={editFormData.taxAnexo || 'III'} onChange={(e) => setEditFormData({...editFormData, taxAnexo: e.target.value as TaxAnexo})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20">
                  <option value="I">Anexo I (Comércio)</option>
                  <option value="II">Anexo II (Indústria)</option>
                  <option value="III">Anexo III (Serviços)</option>
                  <option value="IV">Anexo IV (Serviços Esp.)</option>
                  <option value="V">Anexo V (Fator R)</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAE Principal</label>
                <input value={editFormData.cnae || ''} onChange={(e) => setEditFormData({...editFormData, cnae: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="md:col-span-2 pt-6 flex flex-col md:flex-row gap-4">
                <button type="submit" className="flex-1 bg-slate-900 hover:bg-slate-800 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-slate-900/20 transition-all active:scale-95">
                  Salvar Alterações
                </button>
                <button type="button" onClick={() => setEditingClient(null)} className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 transition-all">
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE INTEGRAÇÃO */}
      {showConnectorModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
           <div className="bg-white w-full max-w-lg rounded-[2rem] shadow-2xl p-8 animate-in zoom-in duration-300">
              <h3 className="text-xl font-black mb-4">Configurar Integração: {showConnectorModal.name}</h3>
              <div className="space-y-4">
                 <select 
                    value={connectorForm.city}
                    onChange={(e) => setConnectorForm({...connectorForm, city: e.target.value as any})}
                    className="w-full p-4 border rounded-xl bg-slate-50 focus:ring-2 focus:ring-blue-500/20 outline-none"
                 >
                    <option value="São Paulo">São Paulo (Nota do Milhão)</option>
                    <option value="Salvador">Salvador (Nota Salvador)</option>
                 </select>
                 <input type="password" placeholder="Senha do Certificado Digital" className="w-full p-4 border rounded-xl bg-slate-50 focus:ring-2 focus:ring-blue-500/20 outline-none" />
                 <button onClick={handleConnectPortal} className="w-full py-4 bg-blue-600 text-white rounded-xl font-black uppercase tracking-widest shadow-lg shadow-blue-500/20">
                    {connectorForm.isUploading ? 'Validando Certificado...' : 'Ativar Integração API'}
                 </button>
                 <button onClick={() => setShowConnectorModal(null)} className="w-full py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-red-500">Cancelar</button>
              </div>
           </div>
        </div>
      )}

      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
        <div className="relative flex-1 max-w-md">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Buscar empresa por nome ou CNPJ..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500/20 transition-all"
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${
            showForm ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-slate-900 text-white shadow-lg shadow-slate-900/10'
          }`}
        >
          {showForm ? 'Cancelar' : 'Nova Empresa'}
        </button>
      </header>

      {showForm && (
        <div className="bg-white p-8 rounded-3xl shadow-2xl border-2 border-blue-500/5 animate-in slide-in-from-top duration-500">
          <div className="flex items-center space-x-3 mb-8">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-lg">🏢</div>
            <h3 className="font-black text-slate-800 uppercase text-sm tracking-tight">Cadastro e Enquadramento Tributário</h3>
          </div>
          <form onSubmit={handleAddClient} className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-1 md:col-span-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social / Nome Completo</label>
              <input required value={newClient.name} onChange={(e) => setNewClient({...newClient, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNPJ / CPF</label>
              <input required value={newClient.identifier} onChange={(e) => setNewClient({...newClient, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail Financeiro</label>
              <input required type="email" value={newClient.email} onChange={(e) => setNewClient({...newClient, email: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">WhatsApp (com DDD)</label>
              <input required placeholder="5511999999999" value={newClient.phone} onChange={(e) => setNewClient({...newClient, phone: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-emerald-500/20" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">RBT12 (Faturamento 12m)</label>
              <input required type="number" value={newClient.annualRevenue} onChange={(e) => setNewClient({...newClient, annualRevenue: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" placeholder="R$ 0,00" />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Anexo Principal</label>
              <select value={newClient.taxAnexo} onChange={(e) => setNewClient({...newClient, taxAnexo: e.target.value as TaxAnexo})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20">
                <option value="I">Anexo I (Comércio)</option>
                <option value="II">Anexo II (Indústria)</option>
                <option value="III">Anexo III (Serviços)</option>
                <option value="IV">Anexo IV (Serviços Esp.)</option>
                <option value="V">Anexo V (Fator R)</option>
              </select>
            </div>
            <div className="space-y-1 md:col-span-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAE Principal</label>
              <input placeholder="Ex: 6201-5/01 - Desenvolvimento de Software" value={newClient.cnae} onChange={(e) => setNewClient({...newClient, cnae: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
            </div>

            <div className="md:col-span-3 pt-4">
              <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20 transition-all active:scale-95">
                Salvar Empresa e Iniciar Monitoramento
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50/50 text-slate-400 text-[10px] font-black uppercase tracking-widest border-b">
              <th className="px-6 py-5">Empresa / Contato</th>
              <th className="px-6 py-5">Enquadramento</th>
              <th className="px-6 py-5">Faturamento (RBT12)</th>
              <th className="px-6 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {filteredClients.map((client) => (
              <tr key={client.id} className="hover:bg-slate-50/50 group transition-colors">
                <td className="px-6 py-5">
                  <div className="flex items-center space-x-4">
                    <div className="w-12 h-12 rounded-2xl bg-slate-900 text-white flex items-center justify-center font-black text-lg shadow-sm group-hover:bg-blue-600 transition-colors">{client.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-sm text-slate-800 leading-none mb-1">{client.name}</p>
                      <div className="flex items-center space-x-2">
                        <span className="text-[10px] text-slate-400 font-bold">{client.identifier}</span>
                        <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                        <span className="text-[10px] text-emerald-600 font-black">{client.phone || 'Sem Telefone'}</span>
                      </div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <div className="flex flex-col">
                    <span className="w-fit px-2 py-1 bg-blue-50 text-blue-700 rounded-lg text-[9px] font-black uppercase tracking-widest mb-1 border border-blue-100">ANEXO {client.taxAnexo}</span>
                    <span className="text-[9px] text-slate-300 font-bold truncate max-w-[120px]">{client.cnae || 'CNAE não informado'}</span>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <p className="font-black text-sm text-slate-700 tracking-tighter">
                    {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(client.annualRevenue || 0)}
                  </p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Ano Base 2024</p>
                </td>
                <td className="px-6 py-5 text-right">
                  <div className="flex items-center justify-end space-x-1 opacity-40 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => setEditingClient(client)} className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="Editar Dados">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                    </button>
                    <button onClick={() => setShowConnectorModal(client)} className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="Integração API"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" /></svg></button>
                    <button onClick={() => onSelectClient?.(client)} className="p-2.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-all" title="Ver Dashboard"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg></button>
                    <button onClick={() => onDeleteClient(client.id)} className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" title="Excluir"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ClientManagement;

export enum UserRole {
  ADMIN = 'admin',
  CLIENT = 'client'
}

export enum View {
  DASHBOARD = 'dashboard',
  CLIENTS = 'clients',
  DOCUMENTS = 'documents',
  TAXES = 'taxes',
  REVENUE = 'revenue',
  REVENUE_TAXES = 'revenue_taxes',
  INVOICE_ISSUE = 'invoice_issue',
  AI_CHAT = 'ai_chat',
  SETTINGS = 'settings'
}

export type TaxAnexo = 'I' | 'II' | 'III' | 'IV' | 'V';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  companyId?: string;
}

export interface PortalIntegration {
  city: 'Salvador' | 'São Paulo';
  status: 'connected' | 'error' | 'disconnected';
  lastSync?: string;
}

export interface Client {
  id: string;
  name: string;
  identifier: string;
  email: string;
  phone?: string;
  status: 'active' | 'inactive';
  type: 'PF' | 'PJ';
  createdAt: string;
  annualRevenue?: number;
  hasCertificate?: boolean;
  integrations?: PortalIntegration[];
  taxAnexo?: TaxAnexo;
  cnaePrimary?: string; // Alterado de cnae
  cnaeSecondary?: string; // Novo campo
}

export interface FinancialMetric {
  label: string;
  value: number;
  change: number;
  trend: 'up' | 'down' | 'neutral';
}

export interface Tax {
  id: string;
  name: string;
  amount: number;
  dueDate: string;
  status: 'paid' | 'pending' | 'overdue';
  reminderSent?: boolean;
  clientId?: string;
}

export interface Document {
  id: string;
  name: string;
  type: string;
  uploadDate: string;
  size: string;
  category: 'invoice' | 'contract' | 'tax_report' | 'other';
  ownerId?: string;
}

export interface Revenue {
  id: string;
  client: string;
  amount: number;
  date: string;
  status: 'received' | 'expected';
  description?: string;
  source?: 'manual' | 'api_cityhall';
}

import React, { useState, useEffect } from 'react';
import { Client, PortalIntegration, TaxAnexo } from '../types';

interface ClientManagementProps {
  clients: Client[];
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [showConnectorModal, setShowConnectorModal] = useState<Client | null>(null);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [newClient, setNewClient] = useState({ 
    name: '', 
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '',
    taxAnexo: 'III' as TaxAnexo,
    cnaePrimary: '',
    cnaeSecondary: ''
  });

  const [editFormData, setEditFormData] = useState<Partial<Client>>({});

  const [connectorForm, setConnectorForm] = useState({
    city: 'São Paulo' as 'São Paulo' | 'Salvador',
    certPassword: '',
    isUploading: false
  });

  useEffect(() => {
    if (editingClient) {
      setEditFormData({ ...editingClient });
    }
  }, [editingClient]);

  const handleAddClient = (e: React.FormEvent) => {
    e.preventDefault();
    const client: Client = {
      id: Math.random().toString(36).substr(2, 9),
      name: newClient.name,
      identifier: newClient.identifier,
      email: newClient.email,
      phone: newClient.phone,
      type: newClient.type,
      status: 'active',
      createdAt: new Date().toISOString().split('T')[0],
      annualRevenue: parseFloat(newClient.annualRevenue) || 0,
      taxAnexo: newClient.taxAnexo,
      cnaePrimary: newClient.cnaePrimary,
      cnaeSecondary: newClient.cnaeSecondary,
      integrations: []
    };
    onAddClient(client);
    setShowForm(false);
    setNewClient({ name: '', identifier: '', email: '', phone: '', type: 'PJ', annualRevenue: '', taxAnexo: 'III', cnaePrimary: '', cnaeSecondary: '' });
  };

  const handleUpdateSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingClient && onUpdateClient && editFormData) {
      onUpdateClient(editFormData as Client);
      setEditingClient(null);
    }
  };

  const handleConnectPortal = () => {
    if (!showConnectorModal) return;
    setConnectorForm(prev => ({ ...prev, isUploading: true }));
    setTimeout(() => {
      const newIntegration: PortalIntegration = {
        city: connectorForm.city,
        status: 'connected',
        lastSync: new Date().toISOString()
      };
      const updatedClient: Client = {
        ...showConnectorModal,
        hasCertificate: true,
        integrations: [...(showConnectorModal.integrations || []), newIntegration]
      };
      onUpdateClient?.(updatedClient);
      setConnectorForm(prev => ({ ...prev, isUploading: false, certPassword: '' }));
      setShowConnectorModal(null);
      alert(`Conectado à Prefeitura de ${connectorForm.city}!`);
    }, 1500);
  };

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.identifier.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      {/* MODAL DE EDIÇÃO DE CLIENTE */}
      {editingClient && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-4xl rounded-[2.5rem] shadow-2xl p-8 md:p-12 animate-in zoom-in slide-in-from-bottom-4 duration-300 my-8">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center space-x-4">
                <div className="w-14 h-14 bg-slate-900 text-white rounded-2xl flex items-center justify-center text-2xl shadow-xl">📝</div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Editar Dados da Empresa</h3>
                  <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-0.5">ID: {editingClient.id}</p>
                </div>
              </div>
              <button onClick={() => setEditingClient(null)} className="p-3 hover:bg-slate-100 rounded-full transition-all">
                <svg className="w-6 h-6 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleUpdateSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social / Nome</label>
                <input required value={editFormData.name || ''} onChange={(e) => setEditFormData({...editFormData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNPJ / CPF</label>
                <input required value={editFormData.identifier || ''} onChange={(e) => setEditFormData({...editFormData, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">WhatsApp</label>
                <input required value={editFormData.phone || ''} onChange={(e) => setEditFormData({...editFormData, phone: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-emerald-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail Financeiro</label>
                <input required type="email" value={editFormData.email || ''} onChange={(e) => setEditFormData({...editFormData, email: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Faturamento (RBT12)</label>
                <input required type="number" value={editFormData.annualRevenue || 0} onChange={(e) => setEditFormData({...editFormData, annualRevenue: parseFloat(e.target.value)})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Anexo Simples</label>
                <select value={editFormData.taxAnexo || 'III'} onChange={(e) => setEditFormData({...editFormData, taxAnexo: e.target.value as TaxAnexo})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20">
                  <option value="I">Anexo I (Comércio)</option>
                  <option value="II">Anexo II (Indústria)</option>
                  <option value="III">Anexo III (Serviços)</option>
                  <option value="IV">Anexo IV (Serviços Esp.)</option>
                  <option value="V">Anexo V (Fator R)</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAE Principal</label>
                <input placeholder="Ex: 6201-5/01" value={editFormData.cnaePrimary || ''} onChange={(e) => setEditFormData({...editFormData, cnaePrimary: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
              </div>

              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAEs Secundários (separados por vírgula)</label>
                <textarea 
                  rows={2}
                  placeholder="Ex: 6202-3/00, 6203-1/00, 6209-1/00"
                  value={editFormData.cnaeSecondary || ''} 
                  onChange={(e) => setEditFormData({...editFormData, cnaeSecondary: e.target.value})} 
                  className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 text-sm"
                />
              </div>

              <div className="md:col-span-2 pt-6 flex flex-col md:flex-row gap-4">
                <button type="submit" className="flex-1 bg-slate-900 hover:bg-slate-800 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-slate-900/20 transition-all active:scale-95">
                  Salvar Alterações
                </button>
                <button type="button" onClick={() => setEditingClient(null)} className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 transition-all">
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE INTEGRAÇÃO */}
      {showConnectorModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
           <div className="bg-white w-full max-lg rounded-[2rem] shadow-2xl p-8 animate-in zoom-in duration-300">
              <h3 className="text-xl font-black mb-4">Configurar Integração: {showConnectorModal.name}</h3>
              <div className="space-y-4">
                 <select 
                    value={connectorForm.city}
                    onChange={(e) => setConnectorForm({...connectorForm, city: e.target.value as any})}
                    className="w-full p-4 border rounded-xl bg-slate-50 focus:ring-2 focus:ring-blue-500/20 outline-none"
                 >
                    <option value="São Paulo">São Paulo (Nota do Milhão)</option>
                    <option value="Salvador">Salvador (Nota Salvador)</option>
                 </select>
                 <input type="password" placeholder="Senha do Certificado Digital" className="w-full p-4 border rounded-xl bg-slate-50 focus:ring-2 focus:ring-blue-500/20 outline-none" />
                 <button onClick={handleConnectPortal} className="w-full py-4 bg-blue-600 text-white rounded-xl font-black uppercase tracking-widest shadow-lg shadow-blue-500/20">
                    {connectorForm.isUploading ? 'Validando Certificado...' : 'Ativar Integração API'}
                 </button>
                 <button onClick={() => setShowConnectorModal(null)} className="w-full py-2 text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-red-500">Cancelar</button>
              </div>
           </div>
        </div>
      )}

      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
        <div className="relative flex-1 max-w-md">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Buscar empresa por nome ou CNPJ..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500/20 transition-all"
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${
            showForm ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-slate-900 text-white shadow-lg shadow-slate-900/10'
          }`}
        >
          {showForm ? 'Cancelar' : 'Nova Empresa'}
        </button>
      </header>

      {showForm && (
        <div className="bg-white p-8 rounded-3xl shadow-2xl border-2 border-blue-500/5 animate-in slide-in-from-top duration-500">
          <div className="flex items-center space-x-3 mb-8">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-lg">🏢</div>
            <h3 className="font-black text-slate-800 uppercase text-sm tracking-tight">Cadastro e Enquadramento Tributário</h3>
          </div>
          <form onSubmit={handleAddClient} className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-1 md:col-span-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social / Nome Completo</label>
              <input required value={newClient.name} onChange={(e) => setNewClient({...newClient, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20" />
