  { id: '2', name: 'NF-e Maio 2024.pdf', type: 'PDF', uploadDate: '2024-06-01', size: '1.1 MB', category: 'invoice' },
  { id: '3', name: 'Balancete_Q1.xlsx', type: 'Excel', uploadDate: '2024-04-10', size: '850 KB', category: 'tax_report' },
  { id: '4', name: 'Comprovante DAS.png', type: 'Imagem', uploadDate: '2024-06-20', size: '400 KB', category: 'tax_report' },
];

interface DocumentManagerProps {
  focusedClient?: Client | null;
}

const DocumentManager: React.FC<DocumentManagerProps> = ({ focusedClient }) => {
  const [documents, setDocuments] = useState<Document[]>(initialDocs);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [transferRate, setTransferRate] = useState('');
  const [uploadingFileName, setUploadingFileName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const fileSizeMB = file.size / (1024 * 1024);

      setIsUploading(true);
      setUploadProgress(0);
      setUploadingFileName(file.name);

      // Simulação de velocidade entre 0.8 e 3.5 MB/s
      const mockSpeed = (0.8 + Math.random() * 2.7).toFixed(1);
      setTransferRate(`${mockSpeed} MB/s`);

      let progress = 0;
      const interval = setInterval(() => {
        // Incremento randômico para parecer mais "real"
        progress += Math.random() * 15;

        if (progress >= 100) {
          progress = 100;
          setUploadProgress(100);
          clearInterval(interval);

          // Pequeno delay após 100% para simular processamento final
          setTimeout(() => {
            const newDoc: Document = {
              id: Math.random().toString(36).substr(2, 9),
              name: file.name,
              type: file.name.split('.').pop()?.toUpperCase() || 'FILE',
              uploadDate: new Date().toISOString().split('T')[0],
              size: fileSizeMB < 1 ? `${(file.size / 1024).toFixed(0)} KB` : `${fileSizeMB.toFixed(1)} MB`,
              category: 'other'
            };
            setDocuments([newDoc, ...documents]);
            setIsUploading(false);
            setUploadProgress(0);
            setUploadingFileName('');
          }, 600);
        } else {
          setUploadProgress(Math.floor(progress));
        }
      }, 150);
    }
  };

  const categoryLabels = {
    invoice: 'Nota Fiscal',
    contract: 'Contrato',
    tax_report: 'Relatório',
    other: 'Outros'
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Gerenciador de Arquivos</h2>
          <p className="text-slate-500 text-sm">
            {focusedClient ? `Armazenamento seguro para ${focusedClient.name}` : 'Documentação centralizada e criptografada.'}
          </p>
        </div>

        <button 
          onClick={() => fileInputRef.current?.click()}
          disabled={isUploading}
          className={`px-8 py-3 rounded-xl transition-all flex items-center justify-center space-x-3 font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 ${
            isUploading 
              ? 'bg-slate-100 text-slate-400 cursor-not-allowed border border-slate-200' 
              : 'bg-blue-600 hover:bg-blue-700 text-white shadow-blue-500/20'
          }`}
        >
          {isUploading ? (
            <>
              <div className="w-4 h-4 border-2 border-slate-300 border-t-slate-500 rounded-full animate-spin"></div>
              <span>Processando Envio...</span>
            </>
          ) : (
            <>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
              <span>Upload de Documento</span>
            </>
          )}
          <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
        </button>
      </header>

      {/* PAINEL DE PROGRESSO DE UPLOAD */}
      {isUploading && (
        <div className="bg-white border-2 border-blue-500/10 rounded-3xl p-6 shadow-2xl shadow-blue-500/5 animate-in slide-in-from-top-4 duration-500">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-4">
              <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center animate-pulse">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <div>
                <h4 className="font-black text-slate-800 text-sm truncate max-w-[200px] md:max-w-md">{uploadingFileName}</h4>
                <p className="text-[10px] font-black text-blue-500 uppercase tracking-widest">{transferRate} • Enviando para nuvem Axis</p>
              </div>
            </div>
            <div className="text-right">
              <span className="text-xl font-black text-slate-900 tracking-tighter">{uploadProgress}%</span>
            </div>
          </div>

          <div className="relative w-full h-3 bg-slate-100 rounded-full overflow-hidden shadow-inner">
            <div 
              className="absolute top-0 left-0 h-full bg-gradient-to-r from-blue-600 to-indigo-500 transition-all duration-300 ease-out"
              style={{ width: `${uploadProgress}%` }}
            >
              <div className="absolute top-0 left-0 right-0 bottom-0 bg-[linear-gradient(45deg,rgba(255,255,255,0.15)_25%,transparent_25%,transparent_50%,rgba(255,255,255,0.15)_50%,rgba(255,255,255,0.15)_75%,transparent_75%,transparent)] bg-[length:20px_20px] animate-[progress-bar-stripes_1s_linear_infinite]"></div>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <div className="p-4 border-b border-slate-50 bg-slate-50/50 flex flex-wrap gap-2">
