import { GoogleGenAI } from "@google/genai";

// Standard initialization for Google GenAI SDK
const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const analyzeFinances = async (data: any) => {
  const ai = getAIClient();
  const prompt = `
    Analise os seguintes dados financeiros de uma empresa de contabilidade e forneça um resumo executivo:
    ${JSON.stringify(data)}

    Por favor, inclua:
    1. Saúde financeira geral.
    2. Alertas sobre impostos próximos ao vencimento.
    3. Sugestões de otimização de fluxo de caixa.
    Responda em Português do Brasil, de forma profissional e concisa.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro na análise da IA:", error);
    return "Desculpe, não foi possível processar a análise financeira no momento.";
  }
};

export const chatWithAccountingAI = async (message: string, context: any) => {
  const ai = getAIClient();
  const chat = ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `Você é o Axis AI, assistente contábil sênior da Axis Accounting. 
      Sua principal função é ajudar o cliente com base em seus dados reais.

      REGRAS DE RESPOSTA:
      1. Use SEMPRE os dados do "Perfil Fiscal do Cliente" fornecidos no contexto (CNAE, RBT12, Alíquota Efetiva, Anexo).
      2. Ao falar de impostos ou precificação, cite os números específicos do cliente para demonstrar precisão.
      3. Se o cliente perguntar sobre "quanto pagar", use a Alíquota Efetiva informada no contexto para o cálculo.
      4. Seja educado, use termos contábeis brasileiros e evite respostas genéricas.
      5. Caso não tenha um dado específico, peça educadamente para o cliente completar o cadastro no painel de Clientes.`,
    }
  });

  try {
    const response = await chat.sendMessage({ 
      message: `[CONTEÚDO FISCAL DO CLIENTE]: ${JSON.stringify(context)}. 
      [PERGUNTA DO USUÁRIO]: ${message}` 
    });
    return response.text;
  } catch (error) {
    console.error("Erro no chat da IA:", error);
    return "Tive um problema técnico. Pode repetir a pergunta?";
  }
};

