  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setInput('');
    setIsLoading(true);

    // Contexto enriquecido com dados reais e calculados
    let fiscalContext = {};

    if (focusedClient) {
      const rbt12 = focusedClient.annualRevenue || 0;
      const anexo = focusedClient.taxAnexo || 'III';
      // Pegamos uma receita mensal média ou base zero apenas para extrair a alíquota efetiva do perfil
      const taxProfile = calculateSimplesNacional(rbt12, 1000, anexo);

      fiscalContext = {
        empresa: focusedClient.name,
        cnpj_cpf: focusedClient.identifier,
        regime: 'Simples Nacional',
        anexo: anexo,
        rbt12_acumulado: rbt12,
        cnae_principal: focusedClient.cnaePrimary || 'Não informado',
        cnae_secundario: focusedClient.cnaeSecondary || 'Nenhum',
        aliquota_nominal: `${(taxProfile.nominalRate * 100).toFixed(2)}%`,
        aliquota_efetiva_atual: `${(taxProfile.effectiveRate * 100).toFixed(2)}%`,
        parcela_deducao: taxProfile.deduction,
        limite_faixa: taxProfile.bracketLimit,
        email_contato: focusedClient.email
      };
    } else {
      fiscalContext = {
        empresa: 'Axis Accounting (Geral)',
        info: 'Nenhum cliente específico focado. Respostas baseadas em regras gerais do Simples Nacional 2024.'
      };
    }

    const response = await chatWithAccountingAI(userMsg, fiscalContext);

    setMessages(prev => [...prev, { role: 'assistant', content: response || "Erro ao responder." }]);
    setIsLoading(false);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <header className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-900 text-white">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center text-xl shadow-lg">🤖</div>
          <div>
            <h3 className="font-bold">Axis AI</h3>
            <p className="text-[10px] text-blue-300 font-black uppercase tracking-widest">
              {focusedClient ? `Consultoria: ${focusedClient.name}` : 'Inteligência Contábil'}
            </p>
          </div>
        </div>
        {focusedClient && (
          <div className="hidden md:block px-3 py-1 bg-white/10 rounded-lg">
             <span className="text-[9px] font-black text-blue-400 uppercase tracking-tighter">Contexto Fiscal Ativo</span>
          </div>
        )}
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/30 no-scrollbar">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
              msg.role === 'user' 
                ? 'bg-blue-600 text-white rounded-tr-none' 
                : 'bg-white text-slate-700 rounded-tl-none border border-slate-100'
            }`}>
              <div className="text-sm leading-relaxed whitespace-pre-wrap prose prose-sm max-w-none">
                {msg.content}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 rounded-tl-none flex space-x-1">
              <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-white border-t border-slate-100">
        <div className="flex items-center space-x-2 bg-slate-50 p-2 rounded-xl border border-slate-200 focus-within:ring-2 focus-within:ring-blue-500/20 focus-within:border-blue-500 transition-all">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder={focusedClient ? `Dúvidas sobre o Anexo ${focusedClient.taxAnexo} ou CNAE?` : "Pergunte sobre impostos ou documentos..."}
            className="flex-1 bg-transparent border-none focus:outline-none px-2 text-sm text-slate-700 h-10"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="bg-blue-600 text-white p-2.5 rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 shadow-md shadow-blue-500/20"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </div>
        <p className="text-[9px] text-center text-slate-400 mt-3 font-bold uppercase tracking-widest">
          A Axis AI utiliza os dados cadastrais da empresa para cálculos tributários.
        </p>
      </div>
    </div>
  );
};

