  };

  const handleAddClient = (client: Client) => setClients(prev => [client, ...prev]);

  const handleUpdateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    if (focusedClient?.id === updatedClient.id) setFocusedClient(updatedClient);
  };

  const handleDeleteClient = (clientId: string) => {
    if (confirm(`⚠️ EXCLUSÃO: Remover permanentemente este cliente?`)) {
      setClients(prev => prev.filter(c => c.id !== clientId));
      if (focusedClient?.id === clientId) {
        setFocusedClient(null);
        setCurrentView(View.CLIENTS);
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
        case View.TAX_CONSULTANCY: return <TaxConsultancy focusedClient={focusedClient} />;
        case View.PAYROLL: return <PayrollManager focusedClient={focusedClient} />;
        default: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard userRole={currentUser.role} />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker userRole={currentUser.role} />;
      case View.AI_CHAT: return <AIChat />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy />;
      case View.PAYROLL: return <PayrollManager />;
      default: return <Dashboard userRole={currentUser.role} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />

      <main className={`flex-1 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'ml-[68px]' : 'ml-64'}`}>
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-6 py-2 flex items-center justify-between shadow-md animate-in slide-in-from-top duration-300">
            <div className="flex items-center space-x-2 text-xs font-bold uppercase">
              <span className="text-lg">👁️</span>
              <span>Modo de Foco: <span className="underline">{focusedClient.name}</span></span>
            </div>
            <div className="flex items-center space-x-2">
              <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg transition-all border border-amber-600/30">Sair</button>
            </div>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão de Cliente' : 'Painel Administrativo'}</p>
              <h1 className="text-xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
            </div>
          </header>
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Tax, Client, UserRole } from '../types';
import { sendTaxReminderWhatsApp, isDueInTwoDays } from '../services/notificationService';

const generateMockTaxes = (): Tax[] => {
  const today = new Date();
  const twoDaysFromNow = new Date(today);
  twoDaysFromNow.setDate(today.getDate() + 2);
  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  return [
    { id: '1', name: 'DAS - Simples Nacional', amount: 4520.50, dueDate: formatDate(twoDaysFromNow), status: 'pending', clientId: '1' },
    { id: '2', name: 'FGTS Mensal', amount: 2100.00, dueDate: '2024-06-07', status: 'paid', clientId: '1' },
    { id: '3', name: 'IRRF Prolabore', amount: 550.20, dueDate: formatDate(twoDaysFromNow), status: 'pending', clientId: '1' },
    { id: '4', name: 'ISSQN Retido', amount: 1250.00, dueDate: '2024-05-15', status: 'overdue', clientId: '1' },
  ];
};

interface TaxTrackerProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
  clients?: Client[]; // Adicionado para permitir seleção de cliente no modal
}

const TaxTracker: React.FC<TaxTrackerProps> = ({ focusedClient, userRole, clients = [] }) => {
  const [taxList, setTaxList] = useState<Tax[]>(generateMockTaxes());
  const [activeTab, setActiveTab] = useState<'all' | 'pending' | 'paid'>('all');
  const [showAddModal, setShowAddModal] = useState(false);

  // Estado do formulário de nova guia
  const [newTax, setNewTax] = useState({
    name: 'DAS - Simples Nacional',
    amount: '',
    dueDate: '',
    clientId: focusedClient?.id || ''
  });

  const isAdmin = userRole === UserRole.ADMIN;

  const filteredTaxes = useMemo(() => {
    return taxList.filter(tax => {
      const matchesClient = focusedClient ? tax.clientId === focusedClient.id : true;
      const matchesTab = 
        activeTab === 'all' ? true :
        activeTab === 'pending' ? (tax.status === 'pending' || tax.status === 'overdue') :
        tax.status === 'paid';

      return matchesClient && matchesTab;
    });
  }, [taxList, activeTab, focusedClient]);

  const handleAddTax = (e: React.FormEvent) => {
    e.preventDefault();
    const tax: Tax = {
      id: Math.random().toString(36).substr(2, 9),
      name: newTax.name,
      amount: parseFloat(newTax.amount),
      dueDate: newTax.dueDate,
      status: 'pending',
      clientId: focusedClient?.id || newTax.clientId
    };

    setTaxList(prev => [tax, ...prev]);
    setShowAddModal(false);
    setNewTax({ name: 'DAS - Simples Nacional', amount: '', dueDate: '', clientId: focusedClient?.id || '' });
  };

  const handleNotify = (tax: Tax) => {
    const client = clients.find(c => c.id === tax.clientId) || focusedClient;
    if (client) {
      sendTaxReminderWhatsApp(tax, client);
      setTaxList(prev => prev.map(t => t.id === tax.id ? { ...t, reminderSent: true } : t));
    } else {
      alert("Cliente não identificado para envio.");
    }
  };

  const handleDownload = (tax: Tax) => {
    alert(`Iniciando download da guia: ${tax.name}\nValor: R$ ${tax.amount.toFixed(2)}`);
  };

  const criticalTaxesCount = taxList.filter(t => t.status !== 'paid' && isDueInTwoDays(t.dueDate)).length;

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">
            {isAdmin ? 'Fila de Impostos' : 'Meus Impostos'}
          </h2>
          <p className="text-slate-500 text-sm">
            {isAdmin 
              ? 'Gestão, criação e disparo de guias para clientes.' 
              : 'Visualize e baixe suas guias de impostos enviadas pela contabilidade.'}
          </p>
        </div>

        <div className="flex items-center space-x-3">
          {isAdmin && (
            <button 
              onClick={() => setShowAddModal(true)}
              className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all flex items-center space-x-2"
            >
              <span>+ Nova Guia</span>
            </button>
          )}

          {isAdmin && criticalTaxesCount > 0 && (
            <div className="flex items-center space-x-3 bg-red-50 border border-red-100 px-4 py-3 rounded-2xl animate-pulse">
              <span className="text-xl">🚨</span>
              <div className="hidden sm:block">
                <p className="text-[10px] font-black text-red-600 uppercase tracking-widest leading-none">Vencimentos Próximos</p>
                <p className="text-xs font-bold text-red-900">{criticalTaxesCount} pendentes</p>
              </div>
            </div>
          )}
        </div>
      </header>

      {/* MODAL DE CRIAÇÃO DE GUIA (ADMIN) */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-8 md:p-10 animate-in zoom-in duration-300">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-xl font-black text-slate-900 tracking-tight">Gerar Nova Guia</h3>
              <button onClick={() => setShowAddModal(false)} className="text-slate-400 hover:text-slate-600">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleAddTax} className="space-y-5">
              {!focusedClient && (
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Selecionar Cliente</label>
                  <select 
                    required
                    value={newTax.clientId}
                    onChange={(e) => setNewTax({...newTax, clientId: e.target.value})}
                    className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white outline-none focus:ring-2 focus:ring-blue-500/20 font-bold"
                  >
                    <option value="">Selecione um cliente...</option>
                    {clients.map(c => (
                      <option key={c.id} value={c.id}>{c.name}</option>
                    ))}
                  </select>
                </div>
              )}

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tipo de Imposto</label>
                <select 
                  value={newTax.name}
                  onChange={(e) => setNewTax({...newTax, name: e.target.value})}
                  className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white outline-none focus:ring-2 focus:ring-blue-500/20 font-bold"
                >
                  <option>DAS - Simples Nacional</option>
                  <option>FGTS Mensal</option>
                  <option>INSS Patronal</option>
                  <option>IRRF Prolabore</option>
                  <option>ISSQN Retido</option>
                  <option>ICMS Estuário</option>
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Valor (R$)</label>
                  <input 
