                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vencimento</label>
                  <input 
                    type="date" 
                    required
                    value={newTax.dueDate}
                    onChange={(e) => setNewTax({...newTax, dueDate: e.target.value})}
                    className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white outline-none focus:ring-2 focus:ring-blue-500/20 font-bold"
                  />
                </div>
              </div>

              <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all active:scale-[0.98] mt-4">
                Disponibilizar Guia
              </button>
            </form>
          </div>
        </div>
      )}

      {/* SISTEMA DE ABAS */}
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm w-fit">
        {[
          { id: 'all', label: 'Todos', icon: '📋' },
          { id: 'pending', label: 'Pendentes', icon: '⏳' },
          { id: 'paid', label: 'Pagos', icon: '✅' }
        ].map(tab => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center space-x-2 transition-all ${
              activeTab === tab.id 
                ? 'bg-slate-900 text-white shadow-lg' 
                : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'
            }`}
          >
            <span>{tab.icon}</span>
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredTaxes.map((tax) => {
          const isCritical = isDueInTwoDays(tax.dueDate) && tax.status !== 'paid';

          return (
            <div key={tax.id} className={`bg-white rounded-3xl shadow-sm border transition-all duration-300 relative overflow-hidden group hover:shadow-xl ${
              isCritical ? 'border-amber-400 ring-2 ring-amber-400/10 scale-[1.02]' : 'border-slate-100 hover:border-blue-200'
            }`}>

              {isCritical && (
                <div className="absolute top-0 left-0 right-0 h-1.5 bg-gradient-to-r from-amber-400 to-red-500"></div>
              )}

              <div className="p-6">
                <div className="flex justify-between items-start mb-6">
                  <div className={`p-3 rounded-2xl shadow-inner ${
                    tax.status === 'paid' ? 'bg-emerald-50 text-emerald-600' : 
                    isCritical ? 'bg-amber-50 text-amber-600' : 'bg-slate-50 text-slate-400'
                  }`}>
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
                  </div>
                  <div className="flex flex-col items-end">
                    <span className={`text-[9px] font-black uppercase tracking-[0.15em] px-3 py-1 rounded-full shadow-sm border ${
                      tax.status === 'paid' ? 'bg-emerald-500 text-white border-emerald-400' :
                      tax.status === 'pending' ? 'bg-amber-500 text-white border-amber-400' :
                      'bg-red-500 text-white border-red-400'
                    }`}>
                      {tax.status === 'paid' ? 'Liquidado' : tax.status === 'pending' ? 'Pendente' : 'Em Atraso'}
                    </span>
                  </div>
                </div>

                <div className="space-y-4">
                  <div>
                    <h3 className="font-black text-slate-800 text-lg leading-tight group-hover:text-blue-600 transition-colors">{tax.name}</h3>
                    <p className={`text-xs font-bold mt-1 ${isCritical ? 'text-amber-600' : 'text-slate-400'}`}>
                      {isCritical ? '⏱️ VENCIMENTO EM 48H' : `Vencimento: ${tax.dueDate.split('-').reverse().join('/')}`}
                    </p>
                    {isAdmin && !focusedClient && (
                      <p className="text-[9px] text-blue-600 font-black mt-2 uppercase tracking-widest">
                        Cliente ID: {tax.clientId}
                      </p>
                    )}
                  </div>

                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100/50">
                    <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mb-1">Valor a Pagar</p>
                    <p className="text-2xl font-black text-slate-900 tracking-tighter">
                      {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(tax.amount)}
                    </p>
                  </div>
                </div>

                <div className="mt-6 pt-6 border-t border-slate-50 flex items-center gap-2">
                  {isAdmin ? (
                    <>
                      <button 
                        onClick={() => handleNotify(tax)}
                        className={`flex-1 ${isCritical ? 'bg-emerald-500 hover:bg-emerald-600' : 'bg-slate-900 hover:bg-slate-800'} text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg transition-all flex items-center justify-center space-x-2`}
                      >
                        <span>{tax.reminderSent ? 'Enviado ✓' : 'Lembrar WhatsApp'}</span>
                      </button>
                      <button 
                        onClick={() => setTaxList(prev => prev.map(t => t.id === tax.id ? { ...t, status: t.status === 'paid' ? 'pending' : 'paid' } : t))}
                        className="px-4 py-3 bg-slate-100 text-slate-600 rounded-xl hover:bg-slate-200 transition-all"
                        title="Alternar Status de Pagamento"
                      >
                         <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" /></svg>
                      </button>
                    </>
                  ) : (
                    <>
                      <button 
                        onClick={() => handleDownload(tax)}
                        className="flex-1 bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-500/20 transition-all flex items-center justify-center space-x-2"
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                        <span>Baixar Guia (PDF)</span>
                      </button>
                      <button 
                        onClick={() => alert('Código de barras copiado!')}
                        className="px-4 py-3 bg-slate-100 text-slate-600 rounded-xl hover:bg-slate-200 transition-all"
                        title="Copiar Linha Digitável"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" /></svg>
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {filteredTaxes.length === 0 && (
          <div className="col-span-full py-20 text-center flex flex-col items-center border-2 border-dashed border-slate-200 rounded-[2.5rem] bg-slate-50/50">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center text-3xl mb-4 shadow-sm">🍃</div>
            <p className="text-slate-400 font-black uppercase tracking-widest text-[10px]">Nenhum imposto encontrado para este filtro</p>
          </div>
        )}
      </div>
    </div>
  );
};

