interface TaxTrackerProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
  clients?: Client[];
}

const TaxTracker: React.FC<TaxTrackerProps> = ({ focusedClient, userRole, clients = [] }) => {
  const [taxList, setTaxList] = useState<Tax[]>(generateMockTaxes());
  const [activeTab, setActiveTab] = useState<'all' | 'pending' | 'paid'>('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [newTax, setNewTax] = useState({
    name: 'DAS - Simples Nacional',
    amount: '',
    dueDate: '',
    clientId: focusedClient?.id || '',
    file: null as File | null
  });

  const isAdmin = userRole === UserRole.ADMIN;

  const filteredTaxes = useMemo(() => {
    return taxList.filter(tax => {
      const matchesClient = focusedClient ? tax.clientId === focusedClient.id : true;
      const matchesTab = 
        activeTab === 'all' ? true :
        activeTab === 'pending' ? (tax.status === 'pending' || tax.status === 'overdue') :
        tax.status === 'paid';

      return matchesClient && matchesTab;
    });
