    e.preventDefault();

    if (newTax.file) {
      setIsUploading(true);
      setUploadProgress(0);

      // Simulação de upload
      for (let i = 0; i <= 100; i += 10) {
        setUploadProgress(i);
        await new Promise(r => setTimeout(r, 100));
      }
