                {isUploading ? (
                  <div className="flex items-center space-x-3">
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    <span>Enviando {uploadProgress}%</span>
                  </div>
                ) : (
                  'Disponibilizar para o Cliente'
