               </div>
               <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${
                 tax.status === 'paid' ? 'bg-emerald-500 text-white' : 'bg-amber-500 text-white'
               }`}>{tax.status}</span>
            </div>

            <div className="space-y-4">
              <div>
                <h3 className="font-black text-slate-800 text-lg">{tax.name}</h3>
                <p className="text-xs font-bold text-slate-400">Vence: {tax.dueDate.split('-').reverse().join('/')}</p>
                {tax.attachment && (
                   <div className="mt-2 flex items-center space-x-1 text-[10px] text-blue-600 font-black uppercase tracking-tighter">
                     <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M4 4a2 2 0 012-2h4.586A2 2 0 0112 2.586L15.414 6A2 2 0 0116 7.414V16a2 2 0 01-2 2H6a2 2 0 01-2-2V4z" /></svg>
                     <span>{tax.attachment.name} ({tax.attachment.size})</span>
                   </div>
                )}
              </div>

              <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100">
                <p className="text-[10px] text-slate-400 font-black uppercase mb-1">Valor</p>
                <p className="text-2xl font-black text-slate-900 tracking-tighter">
                  {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(tax.amount)}
                </p>
              </div>

              <div className="flex gap-2">
                <button 
                  onClick={() => handleDownload(tax)}
                  className="flex-1 bg-blue-600 text-white py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-blue-700 transition-all flex items-center justify-center space-x-2 shadow-lg shadow-blue-500/10"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  <span>{tax.attachment ? 'Baixar Guia' : 'Gerar PDF'}</span>
                </button>
                {isAdmin && (
                   <button 
                     onClick={() => handleNotify(tax)}
                     className="px-4 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all"
                     title="Lembrar Cliente via WhatsApp"
                   >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" /></svg>
                   </button>
                )}
