                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Anexo Simples</label>
                <select 
                  value={editFormData.taxAnexo || 'III'} 
                  onChange={(e) => setEditFormData({...editFormData, taxAnexo: e.target.value as TaxAnexo})} 
