                >
                  <option value="I">Anexo I (Comércio)</option>
                  <option value="II">Anexo II (Indústria)</option>
                  <option value="III">Anexo III (Serviços)</option>
                  <option value="IV">Anexo IV (Serviços Esp.)</option>
                  <option value="V">Anexo V (Fator R)</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAE Principal</label>
                <input 
                  placeholder="Ex: 6201-5/01" 
                  value={editFormData.cnaePrimary || ''} 
                  onChange={(e) => setEditFormData({...editFormData, cnaePrimary: e.target.value})} 
                  className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" 
                />
              </div>

              <div className="space-y-1 md:col-span-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAEs Secundários (separados por vírgula)</label>
                <textarea 
                  rows={2}
                  placeholder="Ex: 6202-3/00, 6203-1/00, 6209-1/00"
                  value={editFormData.cnaeSecondary || ''} 
                  onChange={(e) => setEditFormData({...editFormData, cnaeSecondary: e.target.value})} 
                  className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 text-sm font-medium"
                />
              </div>

              <div className="md:col-span-2 pt-6 flex flex-col md:flex-row gap-4">
                <button 
                  type="submit" 
                  disabled={isUpdating}
                  className="flex-1 bg-slate-900 hover:bg-slate-800 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-slate-900/20 transition-all active:scale-95 flex items-center justify-center space-x-3"
                >
                  {isUpdating ? (
                    <>
                      <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                      <span>Salvando Alterações...</span>
                    </>
                  ) : (
                    <span>Confirmar Atualização</span>
                  )}
                </button>
                <button 
                  type="button" 
                  disabled={isUpdating}
                  onClick={() => setEditingClient(null)} 
                  className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black uppercase tracking-widest text-slate-400 hover:bg-slate-50 transition-all disabled:opacity-50"
                >
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE INTEGRAÇÃO */}
