      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
        <div className="relative flex-1 max-w-md">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Buscar empresa por nome ou CNPJ..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500/20 transition-all font-medium"
          />
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`px-8 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${
            showForm ? 'bg-red-50 text-red-600 border border-red-100' : 'bg-slate-900 text-white shadow-lg shadow-slate-900/10'
          }`}
        >
          {showForm ? 'Cancelar' : 'Nova Empresa'}
        </button>
      </header>

      {showForm && (
        <div className="bg-white p-8 rounded-3xl shadow-2xl border-2 border-blue-500/5 animate-in slide-in-from-top duration-500">
          <div className="flex items-center space-x-3 mb-8">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white text-lg">🏢</div>
            <h3 className="font-black text-slate-800 uppercase text-sm tracking-tight">Cadastro e Enquadramento Tributário</h3>
          </div>
          <form onSubmit={handleAddClient} className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-1 md:col-span-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social / Nome Completo</label>
              <input required value={newClient.name} onChange={(e) => setNewClient({...newClient, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNPJ / CPF</label>
              <input required value={newClient.identifier} onChange={(e) => setNewClient({...newClient, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail Financeiro</label>
              <input required type="email" value={newClient.email} onChange={(e) => setNewClient({...newClient, email: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">WhatsApp (com DDD)</label>
              <input required placeholder="5511999999999" value={newClient.phone} onChange={(e) => setNewClient({...newClient, phone: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-emerald-500/20 font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">RBT12 (Faturamento 12m)</label>
              <input required type="number" value={newClient.annualRevenue} onChange={(e) => setNewClient({...newClient, annualRevenue: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" placeholder="R$ 0,00" />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Anexo Principal</label>
              <select value={newClient.taxAnexo} onChange={(e) => setNewClient({...newClient, taxAnexo: e.target.value as TaxAnexo})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold">
                <option value="I">Anexo I (Comércio)</option>
                <option value="II">Anexo II (Indústria)</option>
                <option value="III">Anexo III (Serviços)</option>
                <option value="IV">Anexo IV (Serviços Esp.)</option>
                <option value="V">Anexo V (Fator R)</option>
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAE Principal</label>
              <input placeholder="Ex: 6201-5/01" value={newClient.cnaePrimary} onChange={(e) => setNewClient({...newClient, cnaePrimary: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
            </div>
            <div className="space-y-1 md:col-span-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Outros CNAEs (Secundários)</label>
              <input placeholder="6202-3/00, 6203-1/00..." value={newClient.cnaeSecondary} onChange={(e) => setNewClient({...newClient, cnaeSecondary: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none focus:ring-2 focus:ring-blue-500/20 font-bold" />
            </div>

            <div className="md:col-span-3 pt-4">
              <button type="submit" className="w-full bg-blue-600 hover:bg-blue-700 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20 transition-all active:scale-95">
                Salvar Empresa e Iniciar Monitoramento
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50/50 text-slate-400 text-[10px] font-black uppercase tracking-widest border-b">
              <th className="px-6 py-5">Empresa / Contato</th>
              <th className="px-6 py-5">Enquadramento</th>
              <th className="px-6 py-5">Faturamento (RBT12)</th>
              <th className="px-6 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredClients.map((client) => (
              <tr key={client.id} className="hover:bg-slate-50/50 group transition-colors">
                <td className="px-6 py-5">
                  <div className="flex items-center space-x-4">
                    <div className="w-12 h-12 rounded-2xl bg-slate-900 text-white flex items-center justify-center font-black text-lg shadow-sm group-hover:bg-blue-600 transition-colors">{client.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-sm text-slate-800 leading-none mb-1 group-hover:text-blue-600 transition-colors">{client.name}</p>
                      <div className="flex items-center space-x-2">
                        <span className="text-[10px] text-slate-400 font-bold">{client.identifier}</span>
                        <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
                        <span className="text-[10px] text-emerald-600 font-black">{client.phone || 'Sem Telefone'}</span>
                      </div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <div className="flex flex-col">
                    <span className="w-fit px-2 py-1 bg-blue-50 text-blue-700 rounded-lg text-[9px] font-black uppercase tracking-widest mb-1 border border-blue-100">ANEXO {client.taxAnexo}</span>
                    <div className="flex items-center space-x-1">
                      <span className="text-[9px] text-slate-400 font-bold truncate max-w-[100px]">{client.cnaePrimary || 'P: Não inf.'}</span>
                      {client.cnaeSecondary && (
                        <span className="text-[8px] bg-slate-100 text-slate-500 px-1 rounded font-bold" title={client.cnaeSecondary}>+{client.cnaeSecondary.split(',').length}</span>
                      )}
                    </div>
                  </div>
                </td>
                <td className="px-6 py-5">
                  <p className="font-black text-sm text-slate-700 tracking-tighter">
                    {new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(client.annualRevenue || 0)}
                  </p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Ano Base 2024</p>
                </td>
                <td className="px-6 py-5 text-right">
                  <div className="flex items-center justify-end space-x-1 opacity-20 group-hover:opacity-100 transition-all">
                    <button 
                      onClick={() => setEditingClient(client)} 
                      className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" 
                      title="Editar Dados da Empresa"
                    >
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                    </button>
                    <button onClick={() => setShowConnectorModal(client)} className="p-2.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="Integrar com Prefeitura"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1" /></svg></button>
                    <button onClick={() => onSelectClient?.(client)} className="p-2.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-all" title="Ver Detalhes do Cliente"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg></button>
                    <button onClick={() => onDeleteClient(client.id)} className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" title="Excluir Cliente"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ClientManagement;

import React, { useState, useMemo, useRef } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Client, TaxAnexo, UserRole } from '../types';
import { calculateSimplesNacional, calculateLucroPresumido } from '../services/taxCalculator';

interface PlanningDoc {
  id: string;
  name: string;
  date: string;
  size: string;
  url: string;
}

interface TaxConsultancyProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
}

const TaxConsultancy: React.FC<TaxConsultancyProps> = ({ focusedClient, userRole }) => {
  const [revenue, setRevenue] = useState<number>(focusedClient?.annualRevenue ? focusedClient.annualRevenue / 12 : 50000);
  const [rbt12, setRbt12] = useState<number>(focusedClient?.annualRevenue || 600000);
  const [payroll, setPayroll] = useState<number>(revenue * 0.3);
  const [activity, setActivity] = useState<'service' | 'commerce'>(focusedClient?.taxAnexo === 'I' ? 'commerce' : 'service');
  const [anexo, setAnexo] = useState<TaxAnexo>(focusedClient?.taxAnexo || 'III');

  // Estado para os documentos de planejamento
  const [planningDocs, setPlanningDocs] = useState<PlanningDoc[]>([
    { id: '1', name: 'Estudo de Viabilidade Simples vs Presumido 2024.pdf', date: '2024-02-10', size: '1.4 MB', url: '#' },
    { id: '2', name: 'Análise de Fator R - Planejamento Semestral.pdf', date: '2024-05-15', size: '850 KB', url: '#' }
  ]);

  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isAdmin = userRole === UserRole.ADMIN;

  const comparisonData = useMemo(() => {
    const simples = calculateSimplesNacional(rbt12, revenue, anexo);
    const presumido = calculateLucroPresumido(revenue, payroll, activity);

    const winner = simples.taxAmount < presumido.total ? 'Simples Nacional' : 'Lucro Presumido';
    const difference = Math.abs(simples.taxAmount - presumido.total);

    return {
      simples,
      presumido,
      winner,
      difference,
      chartData: [
        { name: 'Simples Nacional', total: simples.taxAmount, fill: '#3b82f6' },
        { name: 'Lucro Presumido', total: presumido.total, fill: '#64748b' }
      ]
    };
  }, [revenue, rbt12, payroll, activity, anexo]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsUploading(true);
      setUploadProgress(0);

      // Simulação de upload premium
      for (let i = 0; i <= 100; i += 10) {
        setUploadProgress(i);
        await new Promise(r => setTimeout(r, 150));
      }

      const newDoc: PlanningDoc = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        date: new Date().toISOString().split('T')[0],
        size: `${(file.size / (1024 * 1024)).toFixed(1)} MB`,
        url: URL.createObjectURL(file)
      };

      setPlanningDocs(prev => [newDoc, ...prev]);
      setIsUploading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4 bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Consultoria & Planejamento</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Análise de Carga Tributária</h2>
          <p className="text-slate-500 text-sm">Considerando impostos federais, municipais e <b>encargos patronais</b>.</p>
        </div>
        <div className="bg-emerald-50 border border-emerald-100 p-4 rounded-2xl flex items-center space-x-4">
           <div className="w-10 h-10 bg-emerald-500 text-white rounded-xl flex items-center justify-center text-xl shadow-lg">🏆</div>
           <div>
             <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Melhor Regime</p>
             <h4 className="text-sm font-black text-emerald-900">{comparisonData.winner}</h4>
             <p className="text-[10px] text-emerald-700 font-bold">Economia: {fmt(comparisonData.difference)} /mês</p>
           </div>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* CONFIGURAÇÃO DO CENÁRIO E ANEXOS */}
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-5">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">Variáveis de Cálculo</h3>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Faturamento Mensal (Bruto)</label>
              <input 
                type="number" 
                value={revenue} 
                onChange={(e) => setRevenue(Number(e.target.value))}
                className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none font-bold text-slate-800"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 flex justify-between">
                <span>Folha de Pagamento</span>
                <span className="text-blue-600">{((payroll / revenue) * 100).toFixed(0)}% da receita</span>
              </label>
              <input 
                type="number" 
                value={payroll} 
                onChange={(e) => setPayroll(Number(e.target.value))}
                className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none font-bold text-slate-800"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Atividade Econômica</label>
              <div className="grid grid-cols-2 gap-2 p-1 bg-slate-100 rounded-xl">
                <button 
                  onClick={() => setActivity('service')}
                  className={`py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activity === 'service' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >Serviços</button>
                <button 
                  onClick={() => setActivity('commerce')}
                  className={`py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${activity === 'commerce' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}
                >Comércio</button>
              </div>
            </div>
          </div>

          {/* SEÇÃO DE ANEXOS DE ESTRATÉGIA */}
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">Documentos de Estratégia</h3>
              {isAdmin && (
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="text-blue-600 text-[10px] font-black uppercase tracking-widest hover:bg-blue-50 px-3 py-1.5 rounded-lg border border-blue-100 transition-all"
                >
                  Anexar PDF
                </button>
              )}
              <input type="file" ref={fileInputRef} className="hidden" accept=".pdf" onChange={handleFileUpload} />
            </div>

            {isUploading && (
              <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100 animate-in fade-in zoom-in">
                <div className="flex justify-between items-center mb-2">
                  <span className="text-[9px] font-black text-blue-600 uppercase">Enviando Estudo...</span>
                  <span className="text-[10px] font-black text-blue-900">{uploadProgress}%</span>
                </div>
                <div className="w-full h-1.5 bg-blue-200 rounded-full overflow-hidden">
                  <div className="h-full bg-blue-600 transition-all duration-300" style={{ width: `${uploadProgress}%` }}></div>
                </div>
              </div>
            )}

            <div className="space-y-2">
              {planningDocs.map(doc => (
                <div key={doc.id} className="group p-3 border border-slate-50 bg-slate-50/30 rounded-2xl flex items-center justify-between hover:bg-white hover:border-blue-100 hover:shadow-md transition-all">
                  <div className="flex items-center space-x-3 overflow-hidden">
                    <div className="w-9 h-9 bg-white border border-slate-100 text-slate-400 rounded-xl flex items-center justify-center group-hover:text-blue-500 group-hover:border-blue-200 transition-all shrink-0">
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                    </div>
                    <div className="overflow-hidden">
                      <p className="text-[11px] font-black text-slate-800 leading-tight truncate">{doc.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{doc.date} • {doc.size}</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => window.open(doc.url, '_blank')}
                    className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all shrink-0"
                    title="Baixar Documento"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  </button>
                </div>
              ))}
              {planningDocs.length === 0 && !isUploading && (
                <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-2xl">
                  <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Nenhum estudo técnico disponível</p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* GRÁFICO E RESULTADOS */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm h-[350px]">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] mb-6">Projeção de Carga Tributária Anual</h3>
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={comparisonData.chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#64748b'}} />
                <YAxis hide />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                  formatter={(value: number) => [fmt(value), 'Total de Encargos']}
                />
                <Bar dataKey="total" radius={[10, 10, 0, 0]} barSize={60}>
                  {comparisonData.chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="bg-blue-50/50 p-6 rounded-3xl border border-blue-100">
              <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-4">Simples Nacional (Anexo {anexo})</h4>
              <div className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-xs text-slate-500 font-bold">Alíquota Efetiva:</span>
                  <span className="text-sm font-black text-slate-800">{(comparisonData.simples.effectiveRate * 100).toFixed(2)}%</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-xs text-slate-500 font-bold">DAS Mensal:</span>
                  <span className="text-sm font-black text-blue-600">{fmt(comparisonData.simples.taxAmount)}</span>
                </div>
              </div>
            </div>

