import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import InvoiceIssuance from './components/InvoiceIssuance';
import RevenueTaxTracker from './components/RevenueTaxTracker';
import TaxConsultancy from './components/TaxConsultancy';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import Login from './components/Login';
import { View, UserRole, User, Client } from './types';

const initialClients: Client[] = [
  { id: '1', name: 'Tecnologia Avançada LTDA', identifier: '12.345.678/0001-90', email: 'contato@techavancada.com', status: 'active', type: 'PJ', createdAt: '2024-01-10', annualRevenue: 1450000, integrations: [{ city: 'São Paulo', status: 'connected' }], taxAnexo: 'III' },
  { id: '2', name: 'Ana Maria Ferreira', identifier: '123.456.789-00', email: 'ana.ferreira@email.com', status: 'active', type: 'PF', createdAt: '2024-03-22', annualRevenue: 85000 },
  { id: '3', name: 'Logística Express S.A.', identifier: '98.765.432/0001-21', email: 'financeiro@logexpress.com.br', status: 'active', type: 'PJ', createdAt: '2023-11-05', annualRevenue: 3850000, integrations: [{ city: 'Salvador', status: 'connected' }], taxAnexo: 'I' },
  { id: '4', name: 'Padaria do Bairro', identifier: '44.333.222/0001-11', email: 'contato@padaria.com', status: 'active', type: 'PJ', createdAt: '2024-05-15', annualRevenue: 2950000, taxAnexo: 'I' },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) setIsSidebarCollapsed(true);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role
    });
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const handleAddClient = (client: Client) => setClients(prev => [client, ...prev]);

  const handleUpdateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    if (focusedClient?.id === updatedClient.id) setFocusedClient(updatedClient);
  };

  const handleDeleteClient = (clientId: string) => {
    if (confirm(`⚠️ EXCLUSÃO: Remover permanentemente este cliente?`)) {
      setClients(prev => prev.filter(c => c.id !== clientId));
      if (focusedClient?.id === clientId) {
        setFocusedClient(null);
        setCurrentView(View.CLIENTS);
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} userRole={currentUser.role} clients={clients} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
        case View.TAX_CONSULTANCY: return <TaxConsultancy focusedClient={focusedClient} />;
        case View.PAYROLL: return <PayrollManager focusedClient={focusedClient} />;
        case View.PRICING_CALCULATOR: return <PricingCalculator focusedClient={focusedClient} />;
        default: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard userRole={currentUser.role} />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker userRole={currentUser.role} clients={clients} />;
      case View.AI_CHAT: return <AIChat />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy />;
      case View.PAYROLL: return <PayrollManager />;
      default: return <Dashboard userRole={currentUser.role} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />

      <main className={`flex-1 transition-all duration-300 ease-in-out ${isSidebarCollapsed ? 'ml-[68px]' : 'ml-64'}`}>
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-6 py-2 flex items-center justify-between shadow-md animate-in slide-in-from-top duration-300">
            <div className="flex items-center space-x-2 text-xs font-bold uppercase">
              <span className="text-lg">👁️</span>
              <span>Modo de Foco: <span className="underline">{focusedClient.name}</span></span>
            </div>
            <div className="flex items-center space-x-2">
              <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg transition-all border border-amber-600/30">Sair</button>
            </div>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão de Cliente' : 'Painel Administrativo'}</p>
              <h1 className="text-xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
            </div>
          </header>
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Client } from '../types';
import { calculateSimplesNacional } from '../services/taxCalculator';

interface PricingCalculatorProps {
  focusedClient?: Client | null;
}

const PricingCalculator: React.FC<PricingCalculatorProps> = ({ focusedClient }) => {
  const [cost, setCost] = useState<string>('');
  const [profit, setProfit] = useState<string>('');
  const [machineFee, setMachineFee] = useState<string>('3.5');

  // Puxar imposto real do cliente focado
  const taxInfo = useMemo(() => {
    if (!focusedClient) return { effectiveRate: 0.06 }; // Default 6% para Anexo III inicial se sem cliente
    const rbt12 = focusedClient.annualRevenue || 180000;
    const anexo = focusedClient.taxAnexo || 'III';
    // Simulamos um faturamento para pegar a alíquota de equilíbrio
    return calculateSimplesNacional(rbt12, 1000, anexo);
  }, [focusedClient]);

  const results = useMemo(() => {
    const vCost = parseFloat(cost);
    const vProfit = parseFloat(profit);
    const vMachine = parseFloat(machineFee) / 100;
    const vTax = taxInfo.effectiveRate;

    if (isNaN(vCost) || isNaN(vProfit) || vCost < 0 || vProfit < 0) return null;

    // Alvo líquido que o cliente quer receber: Custo + Lucro Desejado
    const targetLiquid = vCost + vProfit;

    // Soma das taxas que incidem sobre o bruto
    const totalFees = vMachine + vTax;

    if (totalFees >= 1) return { error: "As taxas são maiores que 100%. Impossível calcular." };

    // Fórmula: Preço Final = Valor Líquido Alvo / (1 - Taxas Totais)
    const finalSalePrice = targetLiquid / (1 - totalFees);
    const machineAmount = finalSalePrice * vMachine;
    const taxAmount = finalSalePrice * vTax;
    const actualLiquid = finalSalePrice - machineAmount - taxAmount;

    return {
      finalSalePrice,
      machineAmount,
      taxAmount,
      actualLiquid,
      profitReached: actualLiquid - vCost,
      targetLiquid
    };
  }, [cost, profit, machineFee, taxInfo]);

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-3 mb-6">
          <div className="w-10 h-10 bg-blue-600 text-white rounded-xl flex items-center justify-center text-xl shadow-lg">🏷️</div>
          <div>
            <h2 className="text-lg font-black text-slate-800 uppercase tracking-tight">Calculadora de Venda Inteligente</h2>
            <p className="text-slate-500 text-xs">Calcule o preço ideal para garantir seu lucro líquido.</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {/* INPUTS */}
          <div className="space-y-4 md:col-span-1">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Custo do Produto (R$)</label>
              <input 
                type="number" 
                value={cost} 
                onChange={(e) => setCost(e.target.value)}
                placeholder="0,00"
                className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none font-bold text-slate-800"
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Lucro Desejado (R$)</label>
              <input 
                type="number" 
                value={profit} 
                onChange={(e) => setProfit(e.target.value)}
                placeholder="0,00"
                className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none font-bold text-emerald-600"
              />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Taxa Maquininha (%)</label>
              <input 
                type="number" 
                value={machineFee} 
                onChange={(e) => setMachineFee(e.target.value)}
                className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white transition-all outline-none font-bold text-slate-800"
              />
            </div>

            {/* INFO FISCAL AUTOMÁTICA */}
            <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100">
               <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest mb-1">Imposto Axis (Automático)</p>
               <div className="flex justify-between items-center">
                 <span className="text-xs font-bold text-slate-600">{focusedClient ? `Anexo ${focusedClient.taxAnexo}` : 'Default (Anexo III)'}</span>
                 <span className="text-sm font-black text-blue-700">{(taxInfo.effectiveRate * 100).toFixed(2)}%</span>
               </div>
               <p className="text-[9px] text-blue-400 mt-2 leading-tight">Calculado com base no seu RBT12 real de {fmt(focusedClient?.annualRevenue || 180000)}/ano.</p>
            </div>
          </div>

          {/* RESULTADOS */}
          <div className="md:col-span-2">
            {results && !('error' in results) ? (
              <div className="h-full flex flex-col space-y-4 animate-in fade-in slide-in-from-right-4 duration-500">
                <div className="bg-slate-900 rounded-[2rem] p-8 text-white relative overflow-hidden flex-1 shadow-2xl shadow-slate-900/20">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/10 blur-[60px] rounded-full"></div>

                  <p className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-2">Preço de Venda Sugerido</p>
                  <h3 className="text-5xl font-black tracking-tighter mb-8">{fmt(results.finalSalePrice)}</h3>

                  <div className="grid grid-cols-2 gap-8">
                    <div>
                      <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Total Descontos</p>
