          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Gestão Financeira Estratégica</h2>
          <p className="text-slate-500 text-xs">Análise visual completa do seu fluxo de caixa e impostos.</p>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-auto">
          {(['monthly', 'quarterly', 'annual'] as const).map(p => (
            <button 
              key={p}
              onClick={() => setPeriod(p)}
              className={`flex-1 md:px-6 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
            >
              {p === 'monthly' ? 'Mensal' : p === 'quarterly' ? 'Trimestral' : 'Anual'}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* ENTRADAS DE DADOS */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-5">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center">
              <span className="w-1.5 h-1.5 bg-blue-500 rounded-full mr-2"></span> Projeção de Receita
            </h3>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Faturamento Base (Mês)</label>
              <input 
                type="number" 
                value={projectedRevenue}
                onChange={(e) => setProjectedRevenue(Number(e.target.value))}
                className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white outline-none font-bold text-slate-800"
              />
            </div>

            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center pt-2">
              <span className="w-1.5 h-1.5 bg-red-500 rounded-full mr-2"></span> Estrutura de Custos
