import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import InvoiceIssuance from './components/InvoiceIssuance';
import RevenueTaxTracker from './components/RevenueTaxTracker';
import TaxConsultancy from './components/TaxConsultancy';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import FinancialPlanner from './components/FinancialPlanner';
import Login from './components/Login';
import { View, UserRole, User, Client } from './types';

const initialClients: Client[] = [
  { id: '1', name: 'Tecnologia Avançada LTDA', identifier: '12.345.678/0001-90', email: 'contato@techavancada.com', status: 'active', type: 'PJ', createdAt: '2024-01-10', annualRevenue: 1450000, integrations: [{ city: 'São Paulo', status: 'connected' }], taxAnexo: 'III' },
  { id: '2', name: 'Ana Maria Ferreira', identifier: '123.456.789-00', email: 'ana.ferreira@email.com', status: 'active', type: 'PF', createdAt: '2024-03-22', annualRevenue: 85000 },
  { id: '3', name: 'Logística Express S.A.', identifier: '98.765.432/0001-21', email: 'financeiro@logexpress.com.br', status: 'active', type: 'PJ', createdAt: '2023-11-05', annualRevenue: 3850000, integrations: [{ city: 'Salvador', status: 'connected' }], taxAnexo: 'I' },
  { id: '4', name: 'Padaria do Bairro', identifier: '44.333.222/0001-11', email: 'contato@padaria.com', status: 'active', type: 'PJ', createdAt: '2024-05-15', annualRevenue: 2950000, taxAnexo: 'I' },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role
    });
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const handleAddClient = (client: Client) => setClients(prev => [client, ...prev]);

  const handleUpdateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    if (focusedClient?.id === updatedClient.id) setFocusedClient(updatedClient);
  };

  const handleDeleteClient = (clientId: string) => {
    if (confirm(`⚠️ EXCLUSÃO: Remover permanentemente este cliente?`)) {
      setClients(prev => prev.filter(c => c.id !== clientId));
      if (focusedClient?.id === clientId) {
        setFocusedClient(null);
        setCurrentView(View.CLIENTS);
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} userRole={currentUser.role} clients={clients} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
        case View.TAX_CONSULTANCY: return <TaxConsultancy focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.PAYROLL: return <PayrollManager focusedClient={focusedClient} />;
        case View.PRICING_CALCULATOR: return <PricingCalculator focusedClient={focusedClient} />;
        case View.FINANCIAL_PLANNER: return <FinancialPlanner focusedClient={focusedClient} />;
        default: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard userRole={currentUser.role} />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker userRole={currentUser.role} clients={clients} />;
      case View.AI_CHAT: return <AIChat />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy userRole={currentUser.role} />;
      case View.PAYROLL: return <PayrollManager />;
      default: return <Dashboard userRole={currentUser.role} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />

      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {/* Botão Mobile para Abrir Sidebar */}
        <button 
          onClick={() => setIsSidebarCollapsed(false)}
          className={`fixed bottom-6 right-6 z-[60] p-4 bg-blue-600 text-white rounded-full shadow-2xl md:hidden transition-transform active:scale-95 ${!isSidebarCollapsed ? 'scale-0' : 'scale-100'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" /></svg>
        </button>

        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md animate-in slide-in-from-top duration-300">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate pr-4">
              <span className="text-lg">👁️</span>
              <span className="truncate">Modo: <span className="underline">{focusedClient.name}</span></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg transition-all border border-amber-600/30 whitespace-nowrap">Sair</button>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-2">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão de Cliente' : 'Painel Administrativo'}</p>
              <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
            </div>
          </header>
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Client, PortalIntegration, TaxAnexo } from '../types';

interface ClientManagementProps {
  clients: Client[];
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [showConnectorModal, setShowConnectorModal] = useState<Client | null>(null);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [isUpdating, setIsUpdating] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const [newClient, setNewClient] = useState({ 
    name: '', 
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '',
    taxAnexo: 'III' as TaxAnexo,
    cnaePrimary: '',
    cnaeSecondary: ''
  });

  const [editFormData, setEditFormData] = useState<Partial<Client>>({});

  const [connectorForm, setConnectorForm] = useState({
    city: 'São Paulo' as 'São Paulo' | 'Salvador',
    certPassword: '',
    isUploading: false
  });

  useEffect(() => {
    if (editingClient) {
      setEditFormData({ ...editingClient });
    }
  }, [editingClient]);

  const handleAddClient = (e: React.FormEvent) => {
    e.preventDefault();
    const client: Client = {
      id: Math.random().toString(36).substr(2, 9),
      name: newClient.name,
      identifier: newClient.identifier,
      email: newClient.email,
      phone: newClient.phone,
      type: newClient.type,
      status: 'active',
      createdAt: new Date().toISOString().split('T')[0],
      annualRevenue: parseFloat(newClient.annualRevenue) || 0,
      taxAnexo: newClient.taxAnexo,
      cnaePrimary: newClient.cnaePrimary,
      cnaeSecondary: newClient.cnaeSecondary,
      integrations: []
    };
    onAddClient(client);
    setShowForm(false);
    setNewClient({ name: '', identifier: '', email: '', phone: '', type: 'PJ', annualRevenue: '', taxAnexo: 'III', cnaePrimary: '', cnaeSecondary: '' });
  };

  const handleUpdateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingClient && onUpdateClient && editFormData) {
      setIsUpdating(true);
      await new Promise(r => setTimeout(r, 600));
      onUpdateClient(editFormData as Client);
      setIsUpdating(false);
      setEditingClient(null);
    }
  };

  const handleConnectPortal = () => {
    if (!showConnectorModal) return;
    setConnectorForm(prev => ({ ...prev, isUploading: true }));
    setTimeout(() => {
      const newIntegration: PortalIntegration = {
        city: connectorForm.city,
        status: 'connected',
        lastSync: new Date().toISOString()
      };
      const updatedClient: Client = {
        ...showConnectorModal,
        hasCertificate: true,
        integrations: [...(showConnectorModal.integrations || []), newIntegration]
      };
      onUpdateClient?.(updatedClient);
      setConnectorForm(prev => ({ ...prev, isUploading: false, certPassword: '' }));
      setShowConnectorModal(null);
    }, 1500);
  };

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.identifier.includes(searchTerm)
  );

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      {/* MODAL DE EDIÇÃO - Responsivo */}
      {editingClient && (
        <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-4xl rounded-[2rem] shadow-2xl p-6 md:p-12 animate-in zoom-in duration-300 my-4">
