export default FinancialPlanner;

import React, { useState, useMemo } from 'react';
import { Client, TaxAnexo } from '../types';
import { calculateSimplesNacional } from '../services/taxCalculator';
import { GoogleGenAI } from "@google/genai";
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell, Legend, BarChart, Bar 
} from 'recharts';

interface FinancialPlannerProps {
  focusedClient?: Client | null;
}

const FinancialPlanner: React.FC<FinancialPlannerProps> = ({ focusedClient }) => {
  // Estados do Planejamento
  const [projectedRevenue, setProjectedRevenue] = useState<number>(50000);
  const [fixedCosts, setFixedCosts] = useState<number>(focusedClient?.annualRevenue ? (focusedClient.annualRevenue / 12) * 0.2 : 10000);
  const [variableCosts, setVariableCosts] = useState<number>(15000);
  const [period, setPeriod] = useState<'monthly' | 'quarterly' | 'annual'>('monthly');

  // Estados da IA
  const [aiInsight, setAiInsight] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const multiplier = period === 'monthly' ? 1 : period === 'quarterly' ? 3 : 12;

  // Cálculo Fiscal Real baseado no perfil do cliente
  const taxResults = useMemo(() => {
    const rbt12 = focusedClient?.annualRevenue || 180000;
    const anexo = focusedClient?.taxAnexo || 'III';

    const calculation = calculateSimplesNacional(rbt12, projectedRevenue, anexo);

    return {
      ...calculation,
      totalTax: calculation.taxAmount * multiplier
    };
  }, [focusedClient, projectedRevenue, multiplier]);

  const financialSummary = useMemo(() => {
    const totalRev = projectedRevenue * multiplier;
    const totalFixed = fixedCosts * multiplier;
    const totalVar = variableCosts * multiplier;
    const totalTaxes = taxResults.totalTax;

    const totalCosts = totalFixed + totalVar + totalTaxes;
    const netProfit = totalRev - totalCosts;
    const margin = (netProfit / totalRev) * 100;

    return {
      totalRev,
      totalFixed,
      totalVar,
      totalTaxes,
      totalCosts,
      netProfit,
      margin
    };
  }, [projectedRevenue, fixedCosts, variableCosts, taxResults, multiplier]);

  // Dados para o Gráfico de Pizza (Composição do Faturamento)
  const pieData = useMemo(() => [
    { name: 'Lucro Líquido', value: Math.max(0, financialSummary.netProfit), color: '#10b981' },
    { name: 'Impostos (DAS)', value: financialSummary.totalTaxes, color: '#3b82f6' },
    { name: 'Custos Fixos', value: financialSummary.totalFixed, color: '#f59e0b' },
    { name: 'Custos Variáveis', value: financialSummary.totalVar, color: '#94a3b8' },
  ], [financialSummary]);

  // Dados para o Gráfico de Barras (Sensibilidade de Faturamento)
  const sensitivityData = useMemo(() => {
    const steps = [-0.2, -0.1, 0, 0.1, 0.2]; // -20% a +20%
    return steps.map(step => {
      const rev = projectedRevenue * (1 + step);
      const rbt12 = focusedClient?.annualRevenue || 180000;
      const anexo = focusedClient?.taxAnexo || 'III';
      const tax = calculateSimplesNacional(rbt12, rev, anexo).taxAmount;
      const profit = rev - fixedCosts - (variableCosts * (1 + step)) - tax;

      return {
        label: `${(step * 100).toFixed(0)}%`,
        faturamento: rev,
        lucro: profit,
        impostos: tax
      };
    });
  }, [projectedRevenue, fixedCosts, variableCosts, focusedClient]);

  const handleAskAI = async () => {
    setIsAiLoading(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const context = {
      cliente: focusedClient?.name || 'Empresário',
      regime: 'Simples Nacional',
      anexo: focusedClient?.taxAnexo || 'III',
      rbt12: focusedClient?.annualRevenue || 180000,
      projeção: {
        faturamento: financialSummary.totalRev,
        custosFixos: financialSummary.totalFixed,
        custosVariaveis: financialSummary.totalVar,
        impostos: financialSummary.totalTaxes,
        lucroLiquido: financialSummary.netProfit,
        margem: financialSummary.margin
      }
    };

    const prompt = `
      Você é um consultor financeiro sênior da Axis Accounting. 
      Analise o seguinte cenário financeiro para o período ${period === 'monthly' ? 'Mensal' : period === 'quarterly' ? 'Trimestral' : 'Anual'}:

      DADOS DO CLIENTE:
      Empresa: ${context.cliente}
      Anexo Simples: ${context.anexo}
      Faturamento Acumulado (RBT12): R$ ${context.rbt12}

      PROJEÇÃO ATUAL:
      Receita: R$ ${context.projeção.faturamento}
      Custos Totais: R$ ${context.projeção.custosFixos + context.projeção.custosVariaveis}
      Impostos Estimados: R$ ${context.projeção.impostos}
      Lucro Líquido: R$ ${context.projeção.lucroLiquido}
      Margem: ${context.projeção.margem.toFixed(2)}%

      TAREFAS:
      1. Avalie a saúde financeira do cenário.
      2. Identifique riscos fiscais.
      3. Dê 3 recomendações práticas de otimização tributária e de fluxo de caixa.

      Responda em Português do Brasil, de forma profissional, visualmente organizada e focada em resultados. Use markdown.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setAiInsight(response.text || '');
    } catch (error) {
      setAiInsight('Não foi possível processar a análise estratégica no momento. Verifique sua conexão e tente novamente.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-6 md:p-8 rounded-[2rem] border border-slate-100 shadow-sm gap-4">
        <div className="space-y-1">
          <h2 className="text-xl md:text-2xl font-black text-slate-800 uppercase tracking-tight">Gestão Financeira Estratégica</h2>
          <p className="text-slate-500 text-xs font-medium">Análise visual completa do seu fluxo de caixa e impostos reais.</p>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-auto">
          {(['monthly', 'quarterly', 'annual'] as const).map(p => (
            <button 
              key={p}
              onClick={() => setPeriod(p)}
              className={`flex-1 md:px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              {p === 'monthly' ? 'Mensal' : p === 'quarterly' ? 'Trimestral' : 'Anual'}
            </button>
          ))}
        </div>
      </header>

      {/* FOOTER - RESUMO NUMÉRICO PADRONIZADO (ELEMENTO PRINCIPAL AGORA NO TOPO PARA LEITURA RÁPIDA) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Receita Total Projeta', value: financialSummary.totalRev, color: 'text-slate-900', accent: 'bg-slate-900' },
          { label: 'Lucro Líquido Estimado', value: financialSummary.netProfit, color: 'text-emerald-600', accent: 'bg-emerald-500' },
          { label: 'Imposto DAS Estimado', value: financialSummary.totalTaxes, color: 'text-blue-600', accent: 'bg-blue-600' },
          { label: 'Custos Totais Operacionais', value: financialSummary.totalFixed + financialSummary.totalVar, color: 'text-amber-600', accent: 'bg-amber-500' },
        ].map((item, i) => (
          <div key={i} className="bg-white p-6 md:p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col justify-between transition-all hover:shadow-lg group relative overflow-hidden">
            <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${item.accent} opacity-20`}></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] mb-4 group-hover:text-slate-500 transition-colors">
              {item.label}
            </p>
            <div className="flex flex-col">
              <span className={`text-2xl md:text-3xl lg:text-4xl font-black ${item.color} tracking-tighter leading-none mb-2`}>
                {fmt(item.value)}
              </span>
              <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">
                Competência {period === 'monthly' ? 'Mês' : period === 'quarterly' ? 'Trimestre' : 'Ano'}
              </span>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* ENTRADAS DE DADOS */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-6 md:p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
            <div>
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center mb-4">
                <span className="w-2 h-2 bg-blue-500 rounded-full mr-2"></span> Projeção de Receita
              </h3>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Faturamento Base (Mês)</label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold text-sm">R$</span>
                  <input 
                    type="number" 
                    value={projectedRevenue}
                    onChange={(e) => setProjectedRevenue(Number(e.target.value))}
                    className="w-full pl-12 pr-4 py-4 border rounded-2xl bg-slate-50 focus:bg-white focus:ring-4 focus:ring-blue-500/5 transition-all outline-none font-black text-slate-800 text-lg"
                  />
                </div>
              </div>
            </div>

            <div className="pt-4 border-t border-slate-50">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center mb-4">
                <span className="w-2 h-2 bg-red-500 rounded-full mr-2"></span> Estrutura de Custos
              </h3>
              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Custos Fixos (Mês)</label>
                  <input 
                    type="number" 
                    value={fixedCosts}
                    onChange={(e) => setFixedCosts(Number(e.target.value))}
                    className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white outline-none font-bold text-slate-800"
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Custos Variáveis (Mês)</label>
                  <input 
                    type="number" 
                    value={variableCosts}
                    onChange={(e) => setVariableCosts(Number(e.target.value))}
                    className="w-full p-4 border rounded-2xl bg-slate-50 focus:bg-white outline-none font-bold text-slate-800"
                  />
                </div>
              </div>
            </div>
          </div>

          {/* INDICADORES RÁPIDOS */}
          <div className="bg-slate-900 rounded-[2rem] p-8 text-white space-y-6 shadow-xl">
             <div className="flex justify-between items-center">
               <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Ponto de Equilíbrio</span>
               <span className="text-lg font-black text-blue-400">{fmt( (fixedCosts * projectedRevenue) / (projectedRevenue - variableCosts) )}</span>
             </div>
             <div className="w-full h-2 bg-white/10 rounded-full overflow-hidden">
                <div className="h-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)] transition-all duration-1000" style={{ width: `${Math.min((projectedRevenue / ((fixedCosts * projectedRevenue) / (projectedRevenue - variableCosts))) * 100, 100)}%` }}></div>
             </div>
             <p className="text-[10px] text-slate-400 leading-relaxed font-medium">
               Este é o faturamento mínimo mensal necessário para cobrir todos os custos operacionais projetados.
             </p>
          </div>
        </div>

        {/* RESULTADOS E ANÁLISE GRÁFICA */}
        <div className="lg:col-span-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* GRÁFICO DE PIZZA - COMPOSIÇÃO */}
            <div className="bg-white p-6 md:p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[400px]">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Distribuição da Receita</h3>
               <div className="flex-1">
