                        verticalAlign="bottom" 
                        height={40}
                        content={({ payload }) => (
                          <div className="flex flex-wrap justify-center gap-x-6 gap-y-2 mt-4">
                            {payload?.map((entry: any, index: number) => (
                              <div key={index} className="flex items-center space-x-2">
                                <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: entry.color }}></div>
                                <span className="text-[9px] font-black text-slate-500 uppercase tracking-wider">{entry.value}</span>
                              </div>
                            ))}
                          </div>
                        )}
                      />
                    </PieChart>
                  </ResponsiveContainer>
               </div>
            </div>

            {/* GRÁFICO DE BARRAS - SENSIBILIDADE */}
            <div className="bg-white p-6 md:p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[400px]">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Análise de Sensibilidade</h3>
               <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={sensitivityData} margin={{ top: 20, right: 0, left: -25, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="label" axisLine={false} tickLine={false} tick={{fontSize: 9, fontWeight: 900, fill: '#94a3b8'}} />
                      <YAxis hide />
