    { id: View.DOCUMENTS, label: 'Documentos', icon: '📁' },
    { id: View.AI_CHAT, label: 'Axis AI', icon: '🤖' },
  ];

  const navItems = (userRole === UserRole.ADMIN && !hasActiveFocus) ? adminItems : clientItems;

  return (
