      )}

      <aside 
        className={`bg-slate-900 text-white flex flex-col h-[100dvh] fixed left-0 top-0 z-50 shadow-2xl transition-all duration-300 ease-in-out border-r ${
          hasActiveFocus ? 'border-amber-500/50' : 'border-slate-800'
