export const calculateSimplesNacional = (rbt12: number, monthlyRevenue: number, anexo: TaxAnexo = 'III', folha12?: number) => {
  // Regra do Fator R: Se Serviço e tiver folha informada
  let appliedAnexo = anexo;
  if ((anexo === 'III' || anexo === 'V') && folha12 !== undefined && rbt12 > 0) {
    const fatorR = folha12 / rbt12;
    appliedAnexo = fatorR >= 0.28 ? 'III' : 'V';
  }

  const table = TABLES[appliedAnexo];
  const bracketIndex = table.findIndex(b => rbt12 <= b.limit);
  const bracket = bracketIndex !== -1 ? table[bracketIndex] : table[table.length - 1];

  let effectiveRate = 0;
  if (rbt12 === 0) {
    effectiveRate = table[0].nominalRate;
  } else {
    effectiveRate = ((rbt12 * bracket.nominalRate) - bracket.deduction) / rbt12;
  }

  const taxAmount = monthlyRevenue * effectiveRate;

  return {
    effectiveRate,
    nominalRate: bracket.nominalRate,
    deduction: bracket.deduction,
    taxAmount,
    bracketLimit: bracket.limit,
    bracketIndex: (bracketIndex !== -1 ? bracketIndex : table.length - 1) + 1,
    appliedAnexo
  };
};

export const calculateLucroPresumido = (monthlyRevenue: number, monthlyPayroll: number, activity: 'service' | 'commerce') => {
  const presumptionIRPJ = activity === 'service' ? 0.32 : 0.08;
  const presumptionCSLL = activity === 'service' ? 0.32 : 0.12;

  const baseIRPJ = monthlyRevenue * presumptionIRPJ;
  const standardIRPJ = baseIRPJ * 0.15;
  const additionalIRPJ = baseIRPJ > 20000 ? (baseIRPJ - 20000) * 0.10 : 0;
  const totalIRPJ = standardIRPJ + additionalIRPJ;

  const baseCSLL = monthlyRevenue * presumptionCSLL;
  const totalCSLL = baseCSLL * 0.09;

  const totalPIS = monthlyRevenue * 0.0065;
  const totalCOFINS = monthlyRevenue * 0.03;

  const localTaxRate = activity === 'service' ? 0.05 : 0.04; 
  const totalLocalTax = monthlyRevenue * localTaxRate;

  const inssPatronal = monthlyPayroll * 0.20;

  const totalTax = totalIRPJ + totalCSLL + totalPIS + totalCOFINS + totalLocalTax + inssPatronal;

  return {
    irpj: totalIRPJ,
    csll: totalCSLL,
    pis: totalPIS,
    cofins: totalCOFINS,
    localTax: totalLocalTax,
    inssPatronal: inssPatronal,
    total: totalTax,
    effectiveRate: totalTax / monthlyRevenue
  };
};

