    name: '',
    email: '',
    password: '',
    phone: '',
    role: UserRole.CLIENT,
    status: 'active' as 'active' | 'blocked',
    cnpjVinculado: ''
  });

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    u.cnpjVinculado?.includes(searchTerm)
  );

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();

    if (users.some(u => u.email.toLowerCase() === formData.email.toLowerCase())) {
      alert('Erro: Este e-mail já está cadastrado no sistema.');
      return;
    }

    if (formData.role !== UserRole.ADMIN && !formData.cnpjVinculado) {
      alert('Erro: Clientes e Operadores devem estar vinculados a um CNPJ.');
      return;
    }

    const newUser: UserAccount = {
      id: `USR_${Math.floor(Math.random() * 9000) + 1000}`,
      name: formData.name,
      email: formData.email,
      phone: formData.phone,
      role: formData.role,
      createdAt: new Date().toISOString().split('T')[0],
      lastLogin: 'Nunca',
      status: formData.status,
      passwordHash: 'hashed_' + btoa(formData.password),
      cnpjVinculado: formData.role === UserRole.ADMIN ? undefined : formData.cnpjVinculado
    };

    setUsers(prev => [newUser, ...prev]);
    setShowCreateModal(false);
    setFormData({ name: '', email: '', password: '', phone: '', role: UserRole.CLIENT, status: 'active', cnpjVinculado: '' });
    alert('Usuário criado com sucesso e vinculado à empresa selecionada.');
  };

