    if (!cnpj) return 'Acesso Global (Admin)';
    const client = clients.find(c => c.identifier === cnpj);
    return client ? client.name : cnpj;
  };

  const toggleStatus = (id: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: u.status === 'active' ? 'blocked' : 'active' } : u));
  };

  return (
