import React, { useState, useEffect } from 'react';
import { Client, PortalIntegration, TaxAnexo } from '../types';

interface ClientManagementProps {
  clients: Client[];
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Estados para o formulário de Nova Empresa / Edição
  const [formData, setFormData] = useState({
    name: '', 
    nomeFantasia: '',
    nomeEmpresario: '',
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '',
    taxAnexo: 'III' as TaxAnexo,
    dataConsolidacao: '',
    cnaePrimary: '',
    cnaeSecondary: [] as string[],
    currentCnaeSecondary: '',
    inscricaoMunicipal: '',
    inscricaoEstadual: '',
    status: 'active' as 'active' | 'inactive'
  });

  const resetForm = () => {
    setFormData({
      name: '', nomeFantasia: '', nomeEmpresario: '', identifier: '', email: '', phone: '', type: 'PJ', 
      annualRevenue: '', taxAnexo: 'III', dataConsolidacao: '', cnaePrimary: '', cnaeSecondary: [], 
      currentCnaeSecondary: '', inscricaoMunicipal: '', inscricaoEstadual: '', status: 'active'
    });
    setEditingClient(null);
    setShowForm(false);
  };

  useEffect(() => {
    if (editingClient) {
      setFormData({
        name: editingClient.name,
        nomeFantasia: editingClient.nomeFantasia || '',
        nomeEmpresario: editingClient.nomeEmpresario || '',
        identifier: editingClient.identifier,
        email: editingClient.email,
        phone: editingClient.phone || '',
        type: editingClient.type,
        annualRevenue: editingClient.annualRevenue?.toString() || '',
        taxAnexo: editingClient.taxAnexo || 'III',
        dataConsolidacao: editingClient.dataConsolidacao || '',
        cnaePrimary: editingClient.cnaePrimary || '',
        cnaeSecondary: editingClient.cnaeSecondary || [],
        currentCnaeSecondary: '',
        inscricaoMunicipal: editingClient.inscricaoMunicipal || '',
