            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-xl space-y-8 animate-in slide-in-from-right-4 duration-500">
              <div className="flex flex-col items-center text-center">
                 <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center text-3xl font-black text-white shadow-2xl mb-4 ${
                   selectedUser.role === UserRole.ADMIN ? 'bg-slate-900 shadow-slate-900/20' : 
                   'bg-blue-600 shadow-blue-600/20'
                 }`}>
                    {selectedUser.name.charAt(0)}
                 </div>
                 <h4 className="text-xl font-black text-slate-900 tracking-tight leading-none">{selectedUser.name}</h4>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">{selectedUser.email}</p>
                 <span className={`mt-4 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                   selectedUser.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'
                 }`}>
                   Conta {selectedUser.status === 'active' ? 'Ativa' : 'Desativada'}
                 </span>
              </div>

              <div className="space-y-4 pt-6 border-t border-slate-50">
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Empresa Vinculada</span>
                  <span className="text-xs font-bold text-slate-800">{getCompanyName(selectedUser.cnpjVinculado)}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Data Criação</span>
                  <span className="text-xs font-bold text-slate-800">{selectedUser.createdAt}</span>
                </div>
              </div>

              <div className="space-y-3 pt-6">
                 <button onClick={() => toggleStatus(selectedUser.id)} className={`w-full py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all border-2 ${
                    selectedUser.status === 'active' ? 'border-red-100 text-red-600 hover:bg-red-50' : 'border-emerald-100 text-emerald-600 hover:bg-emerald-50'
                 }`}>
                   {selectedUser.status === 'active' ? 'Bloquear Acesso' : 'Ativar Acesso'}
                 </button>
              </div>
            </div>
          ) : (
             <div className="h-full min-h-[400px] border-2 border-dashed border-slate-100 rounded-[2.5rem] flex flex-col items-center justify-center p-12 text-center text-slate-400">
               <span className="text-4xl mb-4 opacity-20">🛡️</span>
               <p className="text-[10px] font-black uppercase tracking-widest">Selecione um usuário para gerenciar</p>
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

