import AdminUserManager from './components/AdminUserManager';
import Login from './components/Login';
import { View, UserRole, User, Client, UserAccount } from './types';
import { deleteClientRequest } from './services/clientService';

const initialClients: Client[] = [
  { id: '1', name: 'Tecnologia Avançada LTDA', identifier: '12.345.678/0001-90', email: 'contato@techavancada.com', status: 'active', type: 'PJ', createdAt: '2024-01-10', annualRevenue: 1450000, integrations: [{ city: 'São Paulo', status: 'connected' }], taxAnexo: 'III', cnaePrimary: '6201-5/01' },
  { id: '2', name: 'Ana Maria Ferreira', identifier: '123.456.789-00', email: 'ana.ferreira@email.com', status: 'active', type: 'PF', createdAt: '2024-03-22', annualRevenue: 85000 },
  { id: '3', name: 'Logística Express S.A.', identifier: '98.765.432/0001-21', email: 'financeiro@logexpress.com.br', status: 'active', type: 'PJ', createdAt: '2023-11-05', annualRevenue: 3850000, integrations: [{ city: 'Salvador', status: 'connected' }], taxAnexo: 'I', cnaePrimary: '4930-2/02' },
  { id: '4', name: 'Padaria do Bairro', identifier: '44.333.222/0001-11', email: 'contato@padaria.com', status: 'active', type: 'PJ', createdAt: '2024-05-15', annualRevenue: 2950000, taxAnexo: 'I', cnaePrimary: '4721-1/02' },
];

const initialUserAccounts: UserAccount[] = [
  { id: 'USR_001', name: 'João Silva', email: 'joao@email.com', phone: '(11) 98877-6655', role: UserRole.CLIENT, createdAt: '2026-01-05', lastLogin: '2026-01-06 14:30', status: 'active', passwordHash: 'hash1', cnpjVinculado: '12.345.678/0001-90' },
  { id: 'USR_458', name: 'Admin Master', email: 'admin@axis.com', phone: '(11) 90000-0000', role: UserRole.ADMIN, createdAt: '2025-10-12', lastLogin: '2026-01-06 18:20', status: 'active', passwordHash: 'hash2' },
  { id: 'USR_992', name: 'Roberto Financeiro', email: 'financeiro@alpha.com', phone: '(71) 3322-1100', role: UserRole.OPERATOR, createdAt: '2025-12-20', lastLogin: '2026-01-04 09:15', status: 'active', passwordHash: 'hash3', cnpjVinculado: '98.765.432/0001-21' }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(initialUserAccounts);
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    const linkedCnpj = role === UserRole.CLIENT ? clients[0].identifier : undefined;
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role,
      cnpjVinculado: linkedCnpj
    });

    if (role === UserRole.CLIENT && linkedCnpj) {
      const client = clients.find(c => c.identifier === linkedCnpj);
      if (client) setFocusedClient(client);
    }
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const handleAddClient = (client: Client) => setClients(prev => [client, ...prev]);

  const handleUpdateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    if (focusedClient?.id === updatedClient.id) setFocusedClient(updatedClient);
  };

  const handleDeleteClient = async (clientId: string) => {
    const clientToDelete = clients.find(c => c.id === clientId);
    if (!clientToDelete) return;

    const confirmMessage = `⚠️ AÇÃO CRÍTICA (ADMIN): Deseja DELETAR PERMANENTEMENTE a empresa "${clientToDelete.name}"?\n\nEsta ação:\n1. Removerá a empresa de todos os relatórios.\n2. Bloqueará IMEDIATAMENTE todos os usuários vinculados ao CNPJ ${clientToDelete.identifier}.`;

    if (confirm(confirmMessage)) {
      try {
        // 1. Chamada ao "Backend" para exclusão física
        const success = await deleteClientRequest(clientId);

        if (success) {
          // 2. Remoção do estado global (Exclusão Efetiva)
          setClients(prev => prev.filter(c => c.id !== clientId));

          // 3. Cascade: Bloqueio de Usuários e remoção de vínculo
          setUserAccounts(prev => prev.map(user => {
            if (user.cnpjVinculado === clientToDelete.identifier) {
              return { ...user, status: 'blocked', cnpjVinculado: undefined };
            }
            return user;
          }));

          // 4. Limpeza de Sessão se a empresa excluída for a em foco
          if (focusedClient?.id === clientId) {
            setFocusedClient(null);
            setCurrentView(View.CLIENTS);
          }

          alert(`Sucesso: A empresa ${clientToDelete.identifier} foi deletada. 
Acessos de terceiros vinculados a este CNPJ foram revogados.`);
        }
      } catch (error) {
        alert("Erro ao tentar excluir a empresa. Por favor, tente novamente.");
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || currentUser.role === UserRole.OPERATOR || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} userRole={currentUser.role} clients={clients} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
        case View.TAX_CONSULTANCY: return <TaxConsultancy focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.PAYROLL: return <PayrollManager focusedClient={focusedClient} />;
        case View.PRICING_CALCULATOR: return <PricingCalculator focusedClient={focusedClient} />;
        case View.FINANCIAL_PLANNER: return <FinancialPlanner focusedClient={focusedClient} />;
        default: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard userRole={currentUser.role} />;
      case View.ADMIN_USERS: return <AdminUserManager clients={clients} users={userAccounts} setUsers={setUserAccounts} />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker userRole={currentUser.role} clients={clients} />;
      case View.AI_CHAT: return <AIChat />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy userRole={currentUser.role} />;
      case View.PAYROLL: return <PayrollManager />;
      default: return <Dashboard userRole={currentUser.role} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />

      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md animate-in slide-in-from-top duration-300">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate pr-4">
              <span className="text-lg">👁️</span>
              <span className="truncate">Modo: <span className="underline">{focusedClient.name}</span></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg transition-all border border-amber-600/30 whitespace-nowrap">Sair</button>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-2">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão Corporativa' : 'Painel Administrativo'}</p>
              <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
            </div>
          </header>
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Client, PortalIntegration, TaxAnexo } from '../types';

interface ClientManagementProps {
  clients: Client[];
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState({
    name: '', 
    nomeFantasia: '',
    nomeEmpresario: '',
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '',
    taxAnexo: 'III' as TaxAnexo,
    dataConsolidacao: '',
    cnaePrimary: '',
    cnaeSecondary: [] as string[],
    currentCnaeSecondary: '',
    inscricaoMunicipal: '',
    inscricaoEstadual: '',
    status: 'active' as 'active' | 'inactive'
  });

  const resetForm = () => {
    setFormData({
      name: '', nomeFantasia: '', nomeEmpresario: '', identifier: '', email: '', phone: '', type: 'PJ', 
      annualRevenue: '', taxAnexo: 'III', dataConsolidacao: '', cnaePrimary: '', cnaeSecondary: [], 
      currentCnaeSecondary: '', inscricaoMunicipal: '', inscricaoEstadual: '', status: 'active'
    });
    setEditingClient(null);
    setShowForm(false);
  };

  useEffect(() => {
    if (editingClient) {
      setFormData({
        name: editingClient.name,
        nomeFantasia: editingClient.nomeFantasia || '',
        nomeEmpresario: editingClient.nomeEmpresario || '',
        identifier: editingClient.identifier,
        email: editingClient.email,
        phone: editingClient.phone || '',
        type: editingClient.type,
        annualRevenue: editingClient.annualRevenue?.toString() || '',
        taxAnexo: editingClient.taxAnexo || 'III',
        dataConsolidacao: editingClient.dataConsolidacao || '',
        cnaePrimary: editingClient.cnaePrimary || '',
        cnaeSecondary: editingClient.cnaeSecondary || [],
        currentCnaeSecondary: '',
        inscricaoMunicipal: editingClient.inscricaoMunicipal || '',
        inscricaoEstadual: editingClient.inscricaoEstadual || '',
        status: editingClient.status
      });
      setShowForm(true);
    }
  }, [editingClient]);

  const addCnaeSecondary = () => {
    if (formData.currentCnaeSecondary.trim() && !formData.cnaeSecondary.includes(formData.currentCnaeSecondary.trim())) {
      setFormData({
        ...formData,
        cnaeSecondary: [...formData.cnaeSecondary, formData.currentCnaeSecondary.trim()],
        currentCnaeSecondary: ''
      });
    }
  };

  const removeCnaeSecondary = (cnae: string) => {
    setFormData({
      ...formData,
      cnaeSecondary: formData.cnaeSecondary.filter(c => c !== cnae)
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!editingClient && clients.some(c => c.identifier === formData.identifier)) {
      alert('Erro: Já existe uma empresa cadastrada com este CNPJ/CPF.');
      return;
    }

    if (!formData.cnaePrimary) {
      alert('Erro: O CNAE Principal é obrigatório.');
      return;
    }

    setIsProcessing(true);
    await new Promise(r => setTimeout(r, 800));

    const clientData: Client = {
      id: editingClient?.id || Math.random().toString(36).substr(2, 9),
      name: formData.name,
      nomeFantasia: formData.nomeFantasia,
      nomeEmpresario: formData.nomeEmpresario,
      identifier: formData.identifier,
      email: formData.email,
      phone: formData.phone,
      type: formData.type,
      status: formData.status,
      createdAt: editingClient?.createdAt || new Date().toISOString().split('T')[0],
      dataConsolidacao: formData.dataConsolidacao,
      annualRevenue: parseFloat(formData.annualRevenue) || 0,
      taxAnexo: formData.taxAnexo,
      cnaePrimary: formData.cnaePrimary,
      cnaeSecondary: formData.cnaeSecondary,
      inscricaoMunicipal: formData.inscricaoMunicipal,
      inscricaoEstadual: formData.inscricaoEstadual,
      integrations: editingClient?.integrations || []
    };

    if (editingClient) {
      onUpdateClient?.(clientData);
    } else {
      onAddClient(clientData);
    }

    setIsProcessing(false);
    resetForm();
  };

  const handleDeleteInternally = async () => {
    if (editingClient) {
      setIsProcessing(true);
      await onDeleteClient(editingClient.id);
      setIsProcessing(false);
      resetForm();
    }
  };

  const filteredClients = clients.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.nomeFantasia?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    c.identifier.includes(searchTerm)
  );

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Gestão de Empresas</h2>
          <p className="text-slate-500 text-xs font-medium">Controle central de CNPJs e dados fiscais corporativos.</p>
        </div>
        <div className="flex flex-col md:flex-row gap-3 items-center w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </span>
            <input 
              type="text" 
              placeholder="Razão ou CNPJ..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none font-medium focus:ring-4 focus:ring-blue-500/5 transition-all"
            />
          </div>
          <button 
            onClick={() => setShowForm(true)}
            className="w-full md:w-auto px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-800 transition-all flex items-center justify-center space-x-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            <span>Cadastrar Empresa</span>
          </button>
        </div>
      </header>

      {showForm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white w-full max-w-5xl rounded-[2.5rem] shadow-2xl p-8 md:p-12 animate-in zoom-in duration-300 my-8">
            <div className="flex items-center justify-between mb-8">
              <div className="flex items-center space-x-4">
                <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center text-2xl shadow-lg">🏢</div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">{editingClient ? 'Perfil da Empresa' : 'Nova Empresa'}</h3>
                  <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Base de Dados CNPJ Corporativa</p>
                </div>
              </div>
              <button onClick={resetForm} className="text-slate-300 hover:text-slate-500 p-2 transition-colors">
                <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-8">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest flex items-center">
                  <span className="w-2 h-2 bg-blue-500 rounded-full mr-2"></span> Identificação Jurídica
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNPJ / CPF (Único)</label>
                    <input required value={formData.identifier} onChange={(e) => setFormData({...formData, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="00.000.000/0001-00" />
                  </div>
                  <div className="space-y-1 lg:col-span-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social</label>
                    <input required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4 border-t border-slate-100">
                <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center">
                    <span className="w-2 h-2 bg-emerald-500 rounded-full mr-2"></span> Inscrições e Tributação
                  </h4>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Regime Simples</label>
                      <select value={formData.taxAnexo} onChange={(e) => setFormData({...formData, taxAnexo: e.target.value as TaxAnexo})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none">
                        <option value="I">Anexo I</option>
                        <option value="II">Anexo II</option>
                        <option value="III">Anexo III</option>
                        <option value="IV">Anexo IV</option>
                        <option value="V">Anexo V</option>
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Status</label>
                      <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none">
                        <option value="active">ATIVO</option>
                        <option value="inactive">INATIVO</option>
                      </select>
                    </div>
                  </div>
                </div>

                <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-purple-600 uppercase tracking-widest flex items-center">
                    <span className="w-2 h-2 bg-purple-500 rounded-full mr-2"></span> Atividade Principal
                  </h4>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNAE Principal</label>
                    <input required value={formData.cnaePrimary} onChange={(e) => setFormData({...formData, cnaePrimary: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold border-blue-100" placeholder="Ex: 6201-5/01" />
                  </div>
                </div>
              </div>

              <div className="pt-8 flex flex-col md:flex-row gap-4">
                <button 
                  type="submit" 
                  disabled={isProcessing}
                  className="flex-1 py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl hover:bg-blue-700 transition-all flex items-center justify-center"
                >
                  {isProcessing ? <div className="w-5 h-5 border-3 border-white/30 border-t-white rounded-full animate-spin"></div> : <span>{editingClient ? 'Salvar Alterações' : 'Concluir Cadastro'}</span>}
                </button>

                {editingClient && (
                  <button 
                    type="button" 
                    onClick={handleDeleteInternally}
                    disabled={isProcessing}
                    className="px-8 py-5 border-2 border-red-100 text-red-600 rounded-2xl font-black uppercase tracking-widest hover:bg-red-50 transition-all flex items-center space-x-2"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    <span>DELETAR EMPRESA</span>
                  </button>
                )}

                <button 
                  type="button" 
                  onClick={resetForm} 
                  className="px-12 py-5 border-2 border-slate-100 rounded-2xl font-black text-slate-400 uppercase tracking-widest hover:bg-slate-50 transition-all"
                >
                  Fechar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50 text-slate-400 text-[10px] font-black uppercase tracking-[0.15em] border-b border-slate-100">
                <th className="px-6 py-5">Empresa / CNPJ</th>
                <th className="px-6 py-4">Tributação</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Controle</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredClients.map((client) => (
                <tr key={client.id} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-6 py-5">
                    <div className="flex items-center space-x-4">
                      <div className="w-10 h-10 rounded-xl bg-slate-100 text-slate-400 flex items-center justify-center font-black group-hover:bg-blue-600 group-hover:text-white transition-all shadow-sm">
                        {client.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-black text-slate-800 text-sm">{client.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold font-mono">{client.identifier}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="bg-blue-50 text-blue-600 px-2.5 py-1 rounded-lg text-[9px] font-black uppercase border border-blue-100">
                      Anexo {client.taxAnexo}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-2">
                      <span className={`w-1.5 h-1.5 rounded-full ${client.status === 'active' ? 'bg-emerald-500' : 'bg-red-500'}`}></span>
                      <span className={`text-[10px] font-black uppercase ${client.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>
                        {client.status === 'active' ? 'Ativo' : 'Inativo'}
                      </span>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end space-x-1">
                      <button 
                        onClick={() => onSelectClient?.(client)}
                        className="p-2 text-slate-400 hover:text-blue-600"
                        title="Ver Dashboard"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                      </button>
                      <button 
                        onClick={() => setEditingClient(client)}
                        className="p-2 text-slate-400 hover:text-slate-900"
                        title="Editar Detalhes"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                      </button>
                      <button 
                        onClick={() => onDeleteClient(client.id)}
                        className="p-2 text-slate-400 hover:text-red-600"
                        title="DELETAR IMEDIATAMENTE"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default ClientManagement;

export enum UserRole {
  ADMIN = 'admin',
  CLIENT = 'client',
  OPERATOR = 'operator'
}

export enum View {
  DASHBOARD = 'dashboard',
  CLIENTS = 'clients',
  DOCUMENTS = 'documents',
  TAXES = 'taxes',
  REVENUE = 'revenue',
  REVENUE_TAXES = 'revenue_taxes',
  INVOICE_ISSUE = 'invoice_issue',
  AI_CHAT = 'ai_chat',
  SETTINGS = 'settings',
  TAX_CONSULTANCY = 'tax_consultancy',
  PAYROLL = 'payroll',
  PRICING_CALCULATOR = 'pricing_calculator',
  FINANCIAL_PLANNER = 'financial_planner',
  ADMIN_USERS = 'admin_users'
}

export type TaxAnexo = 'I' | 'II' | 'III' | 'IV' | 'V';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  companyId?: string;
  cnpjVinculado?: string; // CNPJ associado ao login
}

export interface UserAccount {
  id: string;
  name: string;
  email: string;
  phone: string;
  role: UserRole;
  createdAt: string;
  lastLogin: string;
  status: 'active' | 'blocked' | 'pending';
  passwordHash: string;
  cnpjVinculado?: string; // Vínculo obrigatório para Clientes e Operadores
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  salary: number;
  admissionDate: string;
  status: 'active' | 'on_vacation' | 'terminated';
  department: string;
}

export interface PortalIntegration {
  city: 'Salvador' | 'São Paulo';
  status: 'connected' | 'error' | 'disconnected';
  lastSync?: string;
}

export interface Client {
  id: string;
  name: string; // Razão Social
  nomeFantasia?: string;
  nomeEmpresario?: string;
  identifier: string; // Este é o CNPJ (ou CPF)
  email: string;
  phone?: string;
  status: 'active' | 'inactive';
  type: 'PF' | 'PJ';
  createdAt: string; // Data de criação no sistema
  dataConsolidacao?: string; // Data de constituição/abertura
  annualRevenue?: number;
  hasCertificate?: boolean;
  integrations?: PortalIntegration[];
  taxAnexo?: TaxAnexo;
  cnaePrimary?: string;
  cnaeSecondary?: string[]; // Múltiplos CNAEs secundários
  inscricaoMunicipal?: string;
  inscricaoEstadual?: string;
}

export interface FinancialMetric {
  label: string;
  value: number;
  change: number;
  trend: 'up' | 'down' | 'neutral';
}

export interface Tax {
  id: string;
  name: string;
  amount: number;
  dueDate: string;
  status: 'paid' | 'pending' | 'overdue';
  reminderSent?: boolean;
  clientId?: string;
  attachment?: {
    name: string;
    url: string;
    size: string;
  };
}

export interface Document {
  id: string;
  name: string;
  type: string;
  uploadDate: string;
  size: string;
  category: 'invoice' | 'contract' | 'tax_report' | 'other';
  ownerId?: string;
}

export interface Revenue {
  id: string;
  client: string;
  amount: number;
  date: string;
  status: 'received' | 'expected';
  description?: string;
  source?: 'manual' | 'api_cityhall';
}

import React, { useState } from 'react';
import { UserAccount, UserRole, Client } from '../types';

interface AdminUserManagerProps {
  clients: Client[];
  users: UserAccount[];
  setUsers: React.Dispatch<React.SetStateAction<UserAccount[]>>;
}

const AdminUserManager: React.FC<AdminUserManagerProps> = ({ clients, users, setUsers }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<UserAccount | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    phone: '',
    role: UserRole.CLIENT,
    status: 'active' as 'active' | 'blocked' | 'pending',
    cnpjVinculado: ''
  });

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    u.cnpjVinculado?.includes(searchTerm)
  );

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();

    // VALIDAÇÕES CRÍTICAS DE SEGURANÇA
    if (users.some(u => u.email.toLowerCase() === formData.email.toLowerCase())) {
      alert('❌ Erro: Este e-mail já está cadastrado no sistema.');
      return;
    }

    if (!formData.password || formData.password.length < 6) {
      alert('❌ Erro: A senha é obrigatória e deve ter no mínimo 6 caracteres.');
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      alert('❌ Erro: As senhas digitadas não coincidem.');
      return;
    }

    if (formData.role !== UserRole.ADMIN && !formData.cnpjVinculado) {
      alert('❌ Erro: Clientes e Operadores devem obrigatoriamente estar vinculados a uma empresa (CNPJ).');
      return;
    }

    const newUser: UserAccount = {
      id: `USR_${Math.floor(Math.random() * 9000) + 1000}`,
      name: formData.name,
      email: formData.email,
      phone: formData.phone,
      role: formData.role,
      createdAt: new Date().toISOString().split('T')[0],
      lastLogin: 'Nunca',
      status: formData.status,
      passwordHash: 'hashed_' + btoa(formData.password), // Simulação de hash seguro
      cnpjVinculado: formData.role === UserRole.ADMIN ? undefined : formData.cnpjVinculado
    };

    setUsers(prev => [newUser, ...prev]);
    setShowCreateModal(false);

    // Reset do form garantindo limpeza de dados sensíveis
    setFormData({ 
      name: '', 
      email: '', 
      password: '', 
      confirmPassword: '', 
      phone: '', 
      role: UserRole.CLIENT, 
      status: 'active', 
      cnpjVinculado: '' 
    });

    alert('✅ Login Corporativo criado com sucesso e ativado!');
  };

  const getCompanyName = (cnpj?: string) => {
    if (!cnpj) return 'Acesso Global (Admin)';
    const client = clients.find(c => c.identifier === cnpj);
    return client ? client.name : (cnpj + ' (Empresa não encontrada)');
  };

  const toggleStatus = (id: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { 
      ...u, 
      status: u.status === 'active' ? 'blocked' : 'active' 
    } : u));
    if (selectedUser?.id === id) {
      setSelectedUser(prev => prev ? { 
        ...prev, 
        status: prev.status === 'active' ? 'blocked' : 'active' 
      } : null);
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Gestão de Acessos</h2>
          <p className="text-slate-500 text-xs font-medium">Provisionamento de logins vinculados a CNPJs.</p>
        </div>
        <div className="flex flex-col md:flex-row gap-3 items-center w-full md:w-auto">
          <div className="relative flex-1 md:w-64">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            </span>
            <input 
              type="text" 
              placeholder="Buscar por nome ou CNPJ..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none font-medium focus:ring-4 focus:ring-blue-500/5 transition-all"
            />
          </div>
          <button 
            onClick={() => setShowCreateModal(true)}
            className="w-full md:w-auto px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-all flex items-center justify-center space-x-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" /></svg>
            <span>Novo Login Seguro</span>
          </button>
        </div>
      </header>

      {showCreateModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl p-8 md:p-12 animate-in zoom-in duration-300 my-8">
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Configurar Novo Acesso</h3>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-1">Vínculo obrigatório com Empresa e Senha</p>
              </div>
              <button onClick={() => setShowCreateModal(false)} className="text-slate-400 hover:text-slate-600 p-2">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>

            <form onSubmit={handleCreateUser} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Vincular à Empresa (CNPJ)</label>
                  <select 
                    required={formData.role !== UserRole.ADMIN}
                    disabled={formData.role === UserRole.ADMIN}
                    value={formData.cnpjVinculado}
                    onChange={(e) => setFormData({...formData, cnpjVinculado: e.target.value})}
                    className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:ring-4 focus:ring-blue-500/5 disabled:opacity-50"
                  >
                    <option value="">Selecione a empresa...</option>
                    {clients.map(client => (
                      <option key={client.id} value={client.identifier}>
                        {client.name} ({client.identifier})
                      </option>
                    ))}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Perfil de Acesso</label>
                  <select 
                    value={formData.role}
                    onChange={(e) => setFormData({...formData, role: e.target.value as UserRole, cnpjVinculado: e.target.value === UserRole.ADMIN ? '' : formData.cnpjVinculado})}
                    className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none"
                  >
                    <option value={UserRole.CLIENT}>CLIENTE (Visualização)</option>
                    <option value={UserRole.OPERATOR}>OPERADOR (Financeiro)</option>
                    <option value={UserRole.ADMIN}>ADMIN (Gestor Master)</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nome Completo</label>
                  <input required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold focus:bg-white transition-all outline-none" placeholder="Ex: Maria Oliveira" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail de Login (Único)</label>
                  <input required type="email" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold focus:bg-white transition-all outline-none" placeholder="exemplo@email.com" />
                </div>
              </div>

              <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Segurança do Acesso</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Definir Senha</label>
                    <input 
                      required 
                      type="password" 
                      value={formData.password} 
                      onChange={(e) => setFormData({...formData, password: e.target.value})} 
                      className="w-full p-4 border rounded-2xl bg-white font-bold outline-none focus:ring-4 focus:ring-blue-500/10" 
                      placeholder="••••••••"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Confirmar Senha</label>
                    <input 
                      required 
                      type="password" 
                      value={formData.confirmPassword} 
                      onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})} 
                      className={`w-full p-4 border rounded-2xl bg-white font-bold outline-none focus:ring-4 ${formData.confirmPassword && formData.password !== formData.confirmPassword ? 'border-red-300 focus:ring-red-500/10' : 'focus:ring-blue-500/10'}`} 
                      placeholder="••••••••"
                    />
                    {formData.confirmPassword && formData.password !== formData.confirmPassword && (
                      <p className="text-[9px] text-red-500 font-black uppercase mt-1 ml-1">As senhas não coincidem</p>
                    )}
                  </div>
                </div>
              </div>

              <div className="pt-4 flex flex-col md:flex-row gap-4">
                <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all">Ativar e Criar Login</button>
                <button type="button" onClick={() => setShowCreateModal(false)} className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black text-slate-400 uppercase tracking-widest hover:bg-slate-50 transition-all">Cancelar</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50/50 text-slate-400 text-[10px] font-black uppercase tracking-[0.15em] border-b border-slate-100">
                  <th className="px-6 py-5">Usuário</th>
                  <th className="px-6 py-5">Empresa Vinculada</th>
                  <th className="px-6 py-5">Perfil</th>
                  <th className="px-6 py-5">Status</th>
                  <th className="px-6 py-5 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredUsers.map(user => (
                  <tr key={user.id} onClick={() => setSelectedUser(user)} className={`hover:bg-slate-50/80 transition-all cursor-pointer ${selectedUser?.id === user.id ? 'bg-blue-50/50' : ''}`}>
                    <td className="px-6 py-5">
                      <div className="flex items-center space-x-3">
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-white ${user.role === UserRole.ADMIN ? 'bg-slate-900' : 'bg-blue-600'}`}>
                          {user.name.charAt(0)}
                        </div>
                        <div>
                          <p className="font-black text-slate-800 text-sm">{user.name}</p>
                          <p className="text-[10px] text-slate-400 font-bold">{user.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex flex-col">
                        <span className={`text-[10px] font-black uppercase ${user.cnpjVinculado ? 'text-slate-700' : 'text-amber-600'}`}>
                          {getCompanyName(user.cnpjVinculado)}
                        </span>
                        {user.cnpjVinculado && <span className="text-[9px] text-slate-400 font-bold font-mono">{user.cnpjVinculado}</span>}
                      </div>
                    </td>
                    <td className="px-6 py-5">
                      <span className={`px-2 py-1 rounded-lg text-[9px] font-black uppercase border ${
                        user.role === UserRole.ADMIN ? 'bg-slate-100 text-slate-600 border-slate-200' : 'bg-blue-50 text-blue-600 border-blue-100'
                      }`}>
                        {user.role}
                      </span>
                    </td>
                    <td className="px-6 py-5">
                      <div className="flex items-center space-x-2">
                        <span className={`w-1.5 h-1.5 rounded-full ${user.status === 'active' ? 'bg-emerald-500' : user.status === 'pending' ? 'bg-amber-400' : 'bg-red-500'}`}></span>
                        <span className={`text-[10px] font-black uppercase ${user.status === 'active' ? 'text-emerald-600' : user.status === 'pending' ? 'text-amber-600' : 'text-red-500'}`}>
                          {user.status === 'active' ? 'Ativo' : user.status === 'pending' ? 'Pendente' : 'Bloqueado'}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-5 text-right">
                      <button onClick={(e) => { e.stopPropagation(); toggleStatus(user.id); }} className="p-2 text-slate-400 hover:text-blue-600" title={user.status === 'active' ? 'Bloquear' : 'Ativar'}>
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 5v.01M12 12v.01M12 19v.01" /></svg>
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="lg:col-span-4">
          {selectedUser ? (
            <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-xl space-y-8 animate-in slide-in-from-right-4 duration-500">
              <div className="flex flex-col items-center text-center">
                 <div className={`w-20 h-20 rounded-[2rem] flex items-center justify-center text-3xl font-black text-white shadow-2xl mb-4 ${
                   selectedUser.role === UserRole.ADMIN ? 'bg-slate-900 shadow-slate-900/20' : 
                   'bg-blue-600 shadow-blue-600/20'
                 }`}>
                    {selectedUser.name.charAt(0)}
                 </div>
                 <h4 className="text-xl font-black text-slate-900 tracking-tight leading-none">{selectedUser.name}</h4>
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">{selectedUser.email}</p>
                 <span className={`mt-4 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                   selectedUser.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'
                 }`}>
                   Conta {selectedUser.status === 'active' ? 'Ativa' : 'Desativada'}
                 </span>
              </div>

              <div className="space-y-4 pt-6 border-t border-slate-50">
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Empresa Vinculada</span>
                  <span className="text-xs font-bold text-slate-800">{getCompanyName(selectedUser.cnpjVinculado)}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Segurança</span>
                  <span className="text-xs font-bold text-emerald-600">✓ Senha Definida</span>
                </div>
              </div>

              <div className="space-y-3 pt-6">
                 <button onClick={() => toggleStatus(selectedUser.id)} className={`w-full py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all border-2 ${
                    selectedUser.status === 'active' ? 'border-red-100 text-red-600 hover:bg-red-50' : 'border-emerald-100 text-emerald-600 hover:bg-emerald-50'
                 }`}>
                   {selectedUser.status === 'active' ? 'Revogar Acesso' : 'Restaurar Acesso'}
                 </button>
              </div>
            </div>
          ) : (
             <div className="h-full min-h-[400px] border-2 border-dashed border-slate-100 rounded-[2.5rem] flex flex-col items-center justify-center p-12 text-center text-slate-400">
               <span className="text-4xl mb-4 opacity-20">🛡️</span>
               <p className="text-[10px] font-black uppercase tracking-widest">Selecione um login para auditoria</p>
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

