import React, { useState, useMemo } from 'react';
import { Revenue, Client } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
}

const months = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues }) => {
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'expected'>('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<Revenue | null>(null);

  const [formData, setFormData] = useState({
    client: '',
    amount: '',
    date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    description: ''
  });

  const filteredByClient = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;
  }, [revenues, focusedClient]);

  const monthlyTotals = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.forEach(rev => {
      const dateParts = rev.date.split('-');
      const m = parseInt(dateParts[1]) - 1;
      if (rev.entryType === 'inflow') {
        totals[m] += rev.amount;
      } else {
        totals[m] -= rev.amount;
      }
    });
    return totals;
  }, [filteredByClient]);

  const monthlyInflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'inflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const monthlyOutflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'outflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      const matchesMonth = m === selectedMonthIdx;
      const matchesSearch = rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            rev.description?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || rev.status === statusFilter;
      return matchesMonth && matchesSearch && matchesStatus;
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm, statusFilter]);

  const handleOpenAdd = () => {
    setEditingEntry(null);
    setFormData({
      client: '',
      amount: '',
      date: new Date().toISOString().split('T')[0],
      status: 'received',
      entryType: 'inflow',
      description: ''
    });
    setShowAddModal(true);
  };

  const handleOpenEdit = (rev: Revenue) => {
    if (rev.source === 'api_cityhall') {
      alert("Lançamentos automáticos (Prefeitura) não podem ser editados manualmente.");
      return;
    }
    setEditingEntry(rev);
    setFormData({
      client: rev.client,
      amount: rev.amount.toString(),
      date: rev.date,
      status: rev.status,
      entryType: rev.entryType,
      description: rev.description || ''
    });
    setShowAddModal(true);
  };

  const handleDelete = (id: string) => {
    const rev = revenues.find(r => r.id === id);
    if (rev?.source === 'api_cityhall') {
      alert("Lançamentos automáticos não podem ser excluídos.");
      return;
    }
    if (confirm("Deseja remover este lançamento do extrato?")) {
      setRevenues(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const newRev: Revenue = {
      id: editingEntry?.id || `man-${Math.random().toString(36).substr(2, 9)}`,
      client: formData.client,
      amount: parseFloat(formData.amount),
      date: formData.date,
      status: formData.status,
      entryType: formData.entryType,
      description: formData.description,
      source: 'manual',
      clientId: focusedClient?.id || '1'
    };

    if (editingEntry) {
      setRevenues(prev => prev.map(r => r.id === editingEntry.id ? newRev : r));
    } else {
      setRevenues(prev => [newRev, ...prev]);
    }
    setShowAddModal(false);
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      {/* Header com Saldo Mensal */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 rounded-full -mr-16 -mt-16"></div>
        <div className="space-y-1 relative z-10">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Gestão de Fluxo de Caixa</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Extrato Financeiro</h2>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-widest">{months[selectedMonthIdx]} / 2024</p>
        </div>

        <div className="flex flex-wrap gap-4 relative z-10">
           <div className="bg-emerald-50 px-6 py-4 rounded-2xl border border-emerald-100">
             <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mb-1">Entradas</p>
             <p className="text-xl font-black text-emerald-700">{fmt(monthlyInflows[selectedMonthIdx])}</p>
           </div>
           <div className="bg-red-50 px-6 py-4 rounded-2xl border border-red-100">
             <p className="text-[9px] font-black text-red-600 uppercase tracking-widest mb-1">Saídas</p>
             <p className="text-xl font-black text-red-700">{fmt(Math.abs(monthlyOutflows[selectedMonthIdx]))}</p>
           </div>
           <div className={`px-8 py-4 rounded-2xl shadow-xl min-w-[180px] ${monthlyTotals[selectedMonthIdx] >= 0 ? 'bg-slate-900 text-white' : 'bg-red-600 text-white'}`}>
              <p className="text-[9px] font-black text-white/50 uppercase tracking-widest mb-1">Saldo do Período</p>
              <p className="text-2xl font-black tracking-tighter">{fmt(monthlyTotals[selectedMonthIdx])}</p>
           </div>
        </div>
      </header>

      {/* Seletor de Mês */}
      <div className="grid grid-cols-3 md:grid-cols-6 lg:grid-cols-12 gap-2">
        {months.map((m, idx) => (
          <button
            key={m}
            onClick={() => setSelectedMonthIdx(idx)}
            className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-tighter transition-all ${
              selectedMonthIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100 hover:border-blue-200'
            }`}
          >
            {m.substring(0, 3)}
          </button>
        ))}
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Filtrar por descrição..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
          />
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl">
          {['all', 'received', 'expected'].map(f => (
            <button
              key={f}
              onClick={() => setStatusFilter(f as any)}
              className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${
                statusFilter === f ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              {f === 'all' ? 'Tudo' : f === 'received' ? 'Pago' : 'Pendente'}
