                <button 
                  type="button"
                  onClick={() => setFormData({...formData, entryType: 'outflow'})}
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                    formData.entryType === 'outflow' ? 'bg-red-500 text-white shadow-lg' : 'text-slate-400'
