                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identificação / Categoria</label>
                  <input required value={formData.client} onChange={(e) => setFormData({...formData, client: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Ex: Venda de Produto A" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Valor (R$)</label>
                  <input required type="number" step="0.01" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="0,00" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Data do Evento</label>
                  <input required type="date" value={formData.date} onChange={(e) => setFormData({...formData, date: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Status</label>
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none">
                    <option value="received">LIQUIDADO (Pago/Recebido)</option>
                    <option value="expected">PREVISTO (Agendado)</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Observações</label>
                <textarea rows={2} value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold resize-none" placeholder="Detalhes adicionais do lançamento..." />
              </div>

              <div className="pt-6 flex flex-col md:flex-row gap-4">
                <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all">Salvar no Extrato</button>
                <button type="button" onClick={() => setShowAddModal(false)} className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black text-slate-400 uppercase tracking-widest hover:bg-slate-50">Cancelar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

