const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(initialUserAccounts);
  // O Extrato agora inicia rigorosamente vazio.
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    const linkedCnpj = role === UserRole.CLIENT ? clients[0].identifier : undefined;
    setCurrentUser({
      id: role === UserRole.ADMIN ? 'admin-1' : 'client-123',
      name: role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo',
      role: role,
      cnpjVinculado: linkedCnpj
    });

    if (role === UserRole.CLIENT && linkedCnpj) {
      const client = clients.find(c => c.identifier === linkedCnpj);
      if (client) setFocusedClient(client);
    }
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const handleAddClient = (client: Client) => setClients(prev => [client, ...prev]);

  const handleUpdateClient = (updatedClient: Client) => {
    setClients(prev => prev.map(c => c.id === updatedClient.id ? updatedClient : c));
    if (focusedClient?.id === updatedClient.id) setFocusedClient(updatedClient);
  };

  const handleDeleteClient = async (clientId: string) => {
    const clientToDelete = clients.find(c => c.id === clientId);
    if (!clientToDelete) return;

    if (confirm(`⚠️ Excluir empresa "${clientToDelete.name}"?`)) {
      try {
        const success = await deleteClientRequest(clientId);
        if (success) {
          setClients(prev => prev.filter(c => c.id !== clientId));
          setUserAccounts(prev => prev.map(user => user.cnpjVinculado === clientToDelete.identifier ? { ...user, status: 'blocked', cnpjVinculado: undefined } : user));
          if (focusedClient?.id === clientId) setFocusedClient(null);
          alert(`Empresa ${clientToDelete.identifier} deletada.`);
        }
      } catch (error) {
        alert("Erro na exclusão.");
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || currentUser.role === UserRole.OPERATOR || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} revenues={revenues} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} userRole={currentUser.role} clients={clients} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} revenues={revenues} setRevenues={setRevenues} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} revenues={revenues} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
        case View.TAX_CONSULTANCY: return <TaxConsultancy focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.PAYROLL: return <PayrollManager focusedClient={focusedClient} />;
        case View.PRICING_CALCULATOR: return <PricingCalculator focusedClient={focusedClient} />;
        case View.FINANCIAL_PLANNER: return <FinancialPlanner focusedClient={focusedClient} />;
        default: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} revenues={revenues} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard userRole={currentUser.role} revenues={revenues} />;
      case View.ADMIN_USERS: return <AdminUserManager clients={clients} users={userAccounts} setUsers={setUserAccounts} />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker userRole={currentUser.role} clients={clients} />;
      case View.AI_CHAT: return <AIChat />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy userRole={currentUser.role} />;
      case View.PAYROLL: return <PayrollManager />;
      case View.REVENUE: return <RevenueSchedule revenues={revenues} setRevenues={setRevenues} />;
      default: return <Dashboard userRole={currentUser.role} revenues={revenues} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />

      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate pr-4">
              <span className="text-lg">👁️</span>
              <span className="truncate">Modo: <span className="underline">{focusedClient.name}</span></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg">Sair</button>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-2">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão Corporativa' : 'Painel Administrativo'}</p>
              <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
            </div>
          </header>
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AreaChart, Area, XAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { FinancialMetric, Client, UserRole, Revenue } from '../types';

interface DashboardProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
  revenues?: Revenue[];
}

const Dashboard: React.FC<DashboardProps> = ({ focusedClient, userRole, revenues = [] }) => {
  const currentMonth = new Date().getMonth();
  const currentYear = new Date().getFullYear();

  // Filtra as receitas baseadas no contexto (cliente focado ou global)
  const relevantRevenues = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;
  }, [revenues, focusedClient]);

  // Cálculos Reais (Apenas o que foi inserido manualmente)
  const metricsData = useMemo(() => {
    const monthlyInflow = relevantRevenues
      .filter(r => {
        const d = new Date(r.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear && r.entryType === 'inflow';
      })
      .reduce((acc, r) => acc + r.amount, 0);

    const totalAnnual = relevantRevenues
      .filter(r => new Date(r.date).getFullYear() === currentYear && r.entryType === 'inflow')
      .reduce((acc, r) => acc + r.amount, 0);

    const pendingDocs = 0; // Seria calculado do estado de documentos se disponível

    return {
      monthlyInflow,
      totalAnnual,
      pendingDocs
    };
  }, [relevantRevenues, currentMonth, currentYear]);

  const metrics: FinancialMetric[] = [
    { label: 'Faturamento Mensal Real', value: metricsData.monthlyInflow, change: 0, trend: 'neutral' },
    { label: 'Faturamento Anual Acumulado', value: metricsData.totalAnnual, change: 0, trend: 'neutral' },
    { label: 'Aguardando Lançamento', value: metricsData.pendingDocs, change: 0, trend: 'neutral' },
    { label: 'Receitas Totais Identificadas', value: relevantRevenues.filter(r => r.entryType === 'inflow').length, change: 0, trend: 'neutral' },
  ];

  // Gera dados para o gráfico baseados nos meses de 2024
  const chartData = useMemo(() => {
    const months = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];
    return months.map((m, idx) => {
      const monthTotal = relevantRevenues
        .filter(r => new Date(r.date).getMonth() === idx && r.entryType === 'inflow')
        .reduce((acc, r) => acc + r.amount, 0);
      return { name: m, value: monthTotal };
    });
  }, [relevantRevenues]);

  return (
    <div className="space-y-6">
      {/* Indicador de Transparência Financeira */}
      <div className="p-4 rounded-2xl border border-slate-200 bg-slate-50 flex items-center space-x-4">
        <div className="w-10 h-10 rounded-xl bg-slate-900 text-white flex items-center justify-center text-xl">
          📑
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">Modo de Lançamento Manual</p>
          <h4 className="text-sm font-black text-slate-800">
            Valores baseados exclusivamente em entradas do usuário.
          </h4>
        </div>
      </div>

      {/* Grid de Métricas Reais */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {metrics.map((metric, idx) => (
          <div key={idx} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 relative group transition-all">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{metric.label}</p>
            <div className="flex flex-col">
              <h3 className="text-2xl font-black text-slate-800 tracking-tighter">
                {metric.label.includes('Faturamento') || metric.label.includes('Receita')
                  ? new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(metric.value)
                  : metric.value}
              </h3>
              <div className="flex items-center mt-2">
                <span className="text-[9px] text-slate-300 uppercase font-bold tracking-widest">Controle Verificado</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Gráfico de Evolução Real */}
      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
        <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-6">Evolução de Entradas (2024)</h3>
        <div className="h-64 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
