                    <div className="flex items-center justify-center space-x-2 text-blue-600 font-bold text-sm">
                      <span className="truncate max-w-[200px]">{newTax.file.name}</span>
                    </div>
                  ) : (
                    <div className="text-slate-400 text-xs font-bold">Selecionar Guia em PDF</div>
                  )}
