              >
                {isUploading ? 'Processando...' : 'Registrar Guia no Portal'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* LISTAGEM VAZIA INICIAL */}
      {filteredTaxes.length === 0 ? (
