import { GoogleGenAI } from "@google/genai";

const getAIClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const analyzeFinances = async (data: any) => {
  const ai = getAIClient();
  const prompt = `
    Analise os seguintes dados financeiros reais (lançados manualmente pelo usuário):
    ${JSON.stringify(data)}

    IMPORTANTE:
    1. Baseie-se APENAS nos números fornecidos.
    2. NÃO CRIE, NÃO ESTIME e NÃO HALLUCINE valores que não estejam presentes.
    3. Se o faturamento for zero, informe que não há dados manuais para análise.

    Por favor, inclua:
    1. Resumo da saúde baseada no que foi declarado.
    2. Alertas sobre impostos.
    Responda em Português do Brasil de forma concisa.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro na análise da IA:", error);
    return "Não foi possível processar a análise no momento.";
  }
};

export const chatWithAccountingAI = async (message: string, context: any) => {
  const ai = getAIClient();
  const chat = ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `Você é o Axis AI, assistente contábil sênior. 

      REGRAS RÍGIDAS:
      1. Use APENAS os dados reais lançados manualmente fornecidos no contexto.
      2. NUNCA sugira valores automáticos ou estimativas fictícias de faturamento.
      3. Se o usuário perguntar sobre algo não lançado, diga explicitamente: "Este valor não consta no seu extrato manual. Por favor, realize o lançamento para que eu possa analisar".
      4. Seja preciso e cite os dados do Anexo e CNAE informados.`,
    }
  });

  try {
    const response = await chat.sendMessage({ 
      message: `[CONTEÚDO FISCAL DECLARADO]: ${JSON.stringify(context)}. 
      [PERGUNTA DO USUÁRIO]: ${message}` 
    });
    return response.text;
  } catch (error) {
    console.error("Erro no chat da IA:", error);
    return "Tive um problema técnico. Pode repetir a pergunta?";
  }
};

