        const success = await deleteClientRequest(clientId);
        if (success) {
          setClients(prev => prev.filter(c => c.id !== clientId));
          setUserAccounts(prev => prev.map(user => user.cnpjVinculado === clientToDelete.identifier ? { ...user, status: 'blocked', cnpjVinculado: undefined } : user));
          if (focusedClient?.id === clientId) setFocusedClient(null);
          alert(`Empresa ${clientToDelete.identifier} deletada.`);
        }
      } catch (error) {
        alert("Erro na exclusão.");
      }
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    if (currentUser.role === UserRole.CLIENT || currentUser.role === UserRole.OPERATOR || isImpersonating) {
      switch (currentView) {
        case View.DASHBOARD: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} revenues={revenues} />;
        case View.DOCUMENTS: return <DocumentManager focusedClient={focusedClient} />;
        case View.TAXES: return <TaxTracker focusedClient={focusedClient} userRole={currentUser.role} clients={clients} />;
        case View.REVENUE: return <RevenueSchedule focusedClient={focusedClient} revenues={revenues} setRevenues={setRevenues} selectedMonthIdx={selectedMonthIdx} setSelectedMonthIdx={setSelectedMonthIdx} />;
        case View.REVENUE_TAXES: return <RevenueTaxTracker focusedClient={focusedClient} revenues={revenues} />;
        case View.INVOICE_ISSUE: return <InvoiceIssuance focusedClient={focusedClient} />;
        case View.AI_CHAT: return <AIChat focusedClient={focusedClient} />;
        case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
        case View.TAX_CONSULTANCY: return <TaxConsultancy focusedClient={focusedClient} userRole={currentUser.role} />;
        case View.PAYROLL: return <PayrollManager focusedClient={focusedClient} />;
        case View.PRICING_CALCULATOR: return <PricingCalculator focusedClient={focusedClient} />;
        case View.FINANCIAL_PLANNER: return <FinancialPlanner focusedClient={focusedClient} revenues={revenues} selectedMonthIdx={selectedMonthIdx} />;
        default: return <Dashboard focusedClient={focusedClient} userRole={currentUser.role} revenues={revenues} />;
      }
    }

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard userRole={currentUser.role} revenues={revenues} />;
      case View.ADMIN_USERS: return <AdminUserManager clients={clients} users={userAccounts} setUsers={setUserAccounts} />;
      case View.CLIENTS: return <ClientManagement clients={clients} onSelectClient={handleSelectClient} onAddClient={handleAddClient} onDeleteClient={handleDeleteClient} onUpdateClient={handleUpdateClient} />;
      case View.DOCUMENTS: return <DocumentManager />;
      case View.TAXES: return <TaxTracker userRole={currentUser.role} clients={clients} />;
      case View.AI_CHAT: return <AIChat />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy userRole={currentUser.role} />;
      case View.PAYROLL: return <PayrollManager />;
      case View.REVENUE: return <RevenueSchedule revenues={revenues} setRevenues={setRevenues} selectedMonthIdx={selectedMonthIdx} setSelectedMonthIdx={setSelectedMonthIdx} />;
      case View.FINANCIAL_PLANNER: return <FinancialPlanner focusedClient={focusedClient} revenues={revenues} selectedMonthIdx={selectedMonthIdx} />;
      default: return <Dashboard userRole={currentUser.role} revenues={revenues} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />

      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate pr-4">
              <span className="text-lg">👁️</span>
              <span className="truncate">Modo: <span className="underline">{focusedClient.name}</span></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg">Sair</button>
          </div>
        )}

        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-2">
            <div className="space-y-0.5">
              <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão Corporativa' : 'Painel Administrativo'}</p>
              <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
            </div>
          </header>
          <div className="animate-in fade-in slide-in-from-bottom-2 duration-500">{renderContent()}</div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Revenue, Client } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
  selectedMonthIdx: number;
  setSelectedMonthIdx: (idx: number) => void;
}

const months = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues, selectedMonthIdx, setSelectedMonthIdx }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'expected'>('all');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingEntry, setEditingEntry] = useState<Revenue | null>(null);

  const [formData, setFormData] = useState({
    client: '',
    amount: '',
    date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    description: ''
  });

  const filteredByClient = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;
  }, [revenues, focusedClient]);

  const monthlyTotals = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.forEach(rev => {
      const dateParts = rev.date.split('-');
      const m = parseInt(dateParts[1]) - 1;
      if (rev.entryType === 'inflow') {
        totals[m] += rev.amount;
      } else {
        totals[m] -= rev.amount;
      }
    });
    return totals;
  }, [filteredByClient]);

  const monthlyInflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'inflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const monthlyOutflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'outflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      const matchesMonth = m === selectedMonthIdx;
      const matchesSearch = rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            rev.description?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || rev.status === statusFilter;
      return matchesMonth && matchesSearch && matchesStatus;
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm, statusFilter]);

  const handleOpenAdd = () => {
    setEditingEntry(null);
    setFormData({
      client: '',
      amount: '',
      date: new Date().toISOString().split('T')[0],
      status: 'received',
      entryType: 'inflow',
      description: ''
    });
    setShowAddModal(true);
  };

  const handleOpenEdit = (rev: Revenue) => {
    if (rev.source === 'api_cityhall') {
      alert("Lançamentos automáticos (Prefeitura) não podem ser editados manualmente.");
      return;
    }
    setEditingEntry(rev);
    setFormData({
      client: rev.client,
      amount: rev.amount.toString(),
      date: rev.date,
      status: rev.status,
      entryType: rev.entryType,
      description: rev.description || ''
    });
    setShowAddModal(true);
  };

  const handleDelete = (id: string) => {
    const rev = revenues.find(r => r.id === id);
    if (rev?.source === 'api_cityhall') {
      alert("Lançamentos automáticos não podem ser excluídos.");
      return;
    }
    if (confirm("Deseja remover este lançamento do extrato?")) {
      setRevenues(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    const newRev: Revenue = {
      id: editingEntry?.id || `man-${Math.random().toString(36).substr(2, 9)}`,
      client: formData.client,
      amount: parseFloat(formData.amount),
      date: formData.date,
      status: formData.status,
      entryType: formData.entryType,
      description: formData.description,
      source: 'manual',
      clientId: focusedClient?.id || '1'
    };

    if (editingEntry) {
      setRevenues(prev => prev.map(r => r.id === editingEntry.id ? newRev : r));
    } else {
      setRevenues(prev => [newRev, ...prev]);
    }
    setShowAddModal(false);
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      {/* Header com Saldo Mensal */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-blue-500/5 rounded-full -mr-16 -mt-16"></div>
        <div className="space-y-1 relative z-10">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Gestão de Fluxo de Caixa</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Extrato Financeiro</h2>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-widest">{months[selectedMonthIdx]} / 2024</p>
        </div>

        <div className="flex flex-wrap gap-4 relative z-10">
           <div className="bg-emerald-50 px-6 py-4 rounded-2xl border border-emerald-100">
             <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mb-1">Entradas</p>
             <p className="text-xl font-black text-emerald-700">{fmt(monthlyInflows[selectedMonthIdx])}</p>
           </div>
           <div className="bg-red-50 px-6 py-4 rounded-2xl border border-red-100">
             <p className="text-[9px] font-black text-red-600 uppercase tracking-widest mb-1">Saídas</p>
             <p className="text-xl font-black text-red-700">{fmt(Math.abs(monthlyOutflows[selectedMonthIdx]))}</p>
           </div>
           <div className={`px-8 py-4 rounded-2xl shadow-xl min-w-[180px] ${monthlyTotals[selectedMonthIdx] >= 0 ? 'bg-slate-900 text-white' : 'bg-red-600 text-white'}`}>
              <p className="text-[9px] font-black text-white/50 uppercase tracking-widest mb-1">Saldo do Período</p>
              <p className="text-2xl font-black tracking-tighter">{fmt(monthlyTotals[selectedMonthIdx])}</p>
           </div>
        </div>
      </header>

      {/* Seletor de Mês */}
      <div className="grid grid-cols-3 md:grid-cols-6 lg:grid-cols-12 gap-2">
        {months.map((m, idx) => (
          <button
            key={m}
            onClick={() => setSelectedMonthIdx(idx)}
            className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-tighter transition-all ${
              selectedMonthIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100 hover:border-blue-200'
            }`}
          >
            {m.substring(0, 3)}
          </button>
        ))}
      </div>

      {/* Toolbar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Filtrar por descrição..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
          />
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl">
          {['all', 'received', 'expected'].map(f => (
            <button
              key={f}
              onClick={() => setStatusFilter(f as any)}
              className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${
                statusFilter === f ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              {f === 'all' ? 'Tudo' : f === 'received' ? 'Pago' : 'Pendente'}
            </button>
          ))}
        </div>
        <button 
          onClick={handleOpenAdd}
          className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-800 transition-all flex items-center justify-center space-x-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          <span>Novo Lançamento</span>
        </button>
      </div>

      {/* Listagem Estilo Extrato */}
      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-slate-400 text-[9px] font-black uppercase tracking-[0.2em] border-b border-slate-100">
                <th className="px-8 py-5">Data / Tipo</th>
                <th className="px-8 py-5">Descrição / Fonte</th>
                <th className="px-8 py-5 text-right">Valor</th>
                <th className="px-8 py-5 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredRevenues.length > 0 ? filteredRevenues.map((rev) => (
                <tr key={rev.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="flex items-center space-x-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-[10px] ${
                        rev.entryType === 'inflow' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'
                      }`}>
                        {rev.date.split('-')[2]}
                      </div>
                      <div>
                        <p className="text-xs font-black text-slate-800 uppercase tracking-tighter">
                          {rev.entryType === 'inflow' ? 'Entrada' : 'Saída'}
                        </p>
                        <p className="text-[9px] text-slate-400 font-bold uppercase">{rev.date.split('-').reverse().join('/')}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5">
                    <div>
                      <p className="text-sm font-bold text-slate-700">{rev.client}</p>
                      <div className="flex items-center space-x-2 mt-0.5">
                        <span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded ${
                          rev.source === 'api_cityhall' ? 'bg-blue-100 text-blue-600' : 'bg-slate-100 text-slate-500'
                        }`}>
                          {rev.source === 'api_cityhall' ? 'Prefeitura' : 'Manual'}
                        </span>
                        <p className="text-[10px] text-slate-400 truncate max-w-xs">{rev.description}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <p className={`text-sm font-black ${rev.entryType === 'inflow' ? 'text-emerald-600' : 'text-red-600'}`}>
                      {rev.entryType === 'inflow' ? '+' : '-'} {fmt(rev.amount)}
                    </p>
                    <p className={`text-[9px] font-black uppercase ${rev.status === 'received' ? 'text-emerald-400' : 'text-amber-400'}`}>
                      {rev.status === 'received' ? 'Liquidado' : 'Provisionado'}
                    </p>
                  </td>
                  <td className="px-8 py-5 text-right">
                    <div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      {rev.source === 'manual' && (
                        <>
                          <button onClick={() => handleOpenEdit(rev)} className="p-2 text-slate-400 hover:text-blue-600">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                          </button>
                          <button onClick={() => handleDelete(rev.id)} className="p-2 text-slate-400 hover:text-red-600">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                          </button>
                        </>
                      )}
                      {rev.source === 'api_cityhall' && (
                        <div className="text-[8px] font-black text-slate-300 uppercase tracking-widest px-2">Bloqueado</div>
                      )}
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <p className="text-slate-400 text-xs font-black uppercase tracking-widest">Nenhum lançamento encontrado para {months[selectedMonthIdx]}</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal de Lançamento */}
      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in duration-300 overflow-y-auto max-h-[90vh]">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-8">
              {editingEntry ? 'Editar Lançamento' : 'Novo Lançamento Manual'}
            </h3>

            <form onSubmit={handleSave} className="space-y-6">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl mb-4">
                <button 
                  type="button"
                  onClick={() => setFormData({...formData, entryType: 'inflow'})}
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                    formData.entryType === 'inflow' ? 'bg-emerald-500 text-white shadow-lg' : 'text-slate-400'
                  }`}
                >Entrada (Receita)</button>
                <button 
                  type="button"
                  onClick={() => setFormData({...formData, entryType: 'outflow'})}
                  className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                    formData.entryType === 'outflow' ? 'bg-red-500 text-white shadow-lg' : 'text-slate-400'
                  }`}
                >Saída (Despesa)</button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Identificação / Categoria</label>
                  <input required value={formData.client} onChange={(e) => setFormData({...formData, client: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Ex: Venda de Produto A" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Valor (R$)</label>
                  <input required type="number" step="0.01" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="0,00" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Data do Evento</label>
                  <input required type="date" value={formData.date} onChange={(e) => setFormData({...formData, date: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Status</label>
                  <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none">
                    <option value="received">LIQUIDADO (Pago/Recebido)</option>
                    <option value="expected">PREVISTO (Agendado)</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Observações</label>
                <textarea rows={2} value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold resize-none" placeholder="Detalhes adicionais do lançamento..." />
              </div>

              <div className="pt-6 flex flex-col md:flex-row gap-4">
                <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all">Salvar no Extrato</button>
                <button type="button" onClick={() => setShowAddModal(false)} className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black text-slate-400 uppercase tracking-widest hover:bg-slate-50">Cancelar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

