}

const FinancialPlanner: React.FC<FinancialPlannerProps> = ({ focusedClient, revenues, selectedMonthIdx }) => {
  // Estados do Planejamento (Custos ainda são configuráveis para simulação)
  const [fixedCosts, setFixedCosts] = useState<number>(10000);
  const [variableCosts, setVariableCosts] = useState<number>(5000);
  const [period, setPeriod] = useState<'monthly' | 'quarterly' | 'annual'>('monthly');

  // Estados da IA
  const [aiInsight, setAiInsight] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const multiplier = period === 'monthly' ? 1 : period === 'quarterly' ? 3 : 12;

  // CÁLCULO AUTOMÁTICO DA RECEITA BASEADO NO EXTRATO (Somatório Real)
  const faturamentoManual = useMemo(() => {
    const relevant = focusedClient ? revenues.filter(r => r.clientId === focusedClient.id) : revenues;

    // Filtro cronológico baseado no período selecionado
    const sumForPeriod = (startMonth: number, endMonth: number) => {
      return relevant
        .filter(r => {
          const m = parseInt(r.date.split('-')[1]) - 1;
          return m >= startMonth && m <= endMonth && r.entryType === 'inflow';
        })
        .reduce((acc, r) => acc + r.amount, 0);
    };

    if (period === 'monthly') return sumForPeriod(selectedMonthIdx, selectedMonthIdx);
    if (period === 'quarterly') {
      const qStart = Math.floor(selectedMonthIdx / 3) * 3;
      return sumForPeriod(qStart, qStart + 2);
    }
    return sumForPeriod(0, 11); // Anual
  }, [revenues, focusedClient, selectedMonthIdx, period]);

  // Cálculo Fiscal Real baseado no perfil do cliente e receita consolidada
  const taxResults = useMemo(() => {
    const rbt12 = focusedClient?.annualRevenue || 0;
    const anexo = focusedClient?.taxAnexo || 'III';

    const calculation = calculateSimplesNacional(rbt12, faturamentoManual, anexo);

    return {
      ...calculation,
      totalTax: calculation.taxAmount // Já é baseado no faturamento do período total
    };
  }, [focusedClient, faturamentoManual]);

  const financialSummary = useMemo(() => {
    const totalRev = faturamentoManual;
    const totalFixed = fixedCosts * multiplier;
    const totalVar = variableCosts * multiplier;
    const totalTaxes = taxResults.totalTax;

    const totalCosts = totalFixed + totalVar + totalTaxes;
    const netProfit = totalRev - totalCosts;
    const margin = totalRev > 0 ? (netProfit / totalRev) * 100 : 0;

    return {
      totalRev,
      totalFixed,
      totalVar,
      totalTaxes,
      totalCosts,
      netProfit,
      margin
    };
  }, [faturamentoManual, fixedCosts, variableCosts, taxResults, multiplier]);

  // Dados para o Gráfico de Pizza (Composição do Faturamento)
  const pieData = useMemo(() => [
    { name: 'Lucro Líquido', value: Math.max(0, financialSummary.netProfit), color: '#10b981' },
    { name: 'Impostos (DAS)', value: financialSummary.totalTaxes, color: '#3b82f6' },
    { name: 'Custos Fixos', value: financialSummary.totalFixed, color: '#f59e0b' },
    { name: 'Custos Variáveis', value: financialSummary.totalVar, color: '#94a3b8' },
  ], [financialSummary]);

  // Dados para o Gráfico de Barras (Sensibilidade de Faturamento)
  const sensitivityData = useMemo(() => {
    const steps = [-0.2, -0.1, 0, 0.1, 0.2]; // -20% a +20%
    return steps.map(step => {
      const rev = faturamentoManual * (1 + step);
      const rbt12 = focusedClient?.annualRevenue || 0;
      const anexo = focusedClient?.taxAnexo || 'III';
      const tax = calculateSimplesNacional(rbt12, rev, anexo).taxAmount;
      const profit = rev - (fixedCosts * multiplier) - (variableCosts * multiplier * (1 + step)) - tax;

      return {
        label: `${(step * 100).toFixed(0)}%`,
        faturamento: rev,
        lucro: profit,
        impostos: tax
      };
    });
  }, [faturamentoManual, fixedCosts, variableCosts, focusedClient, multiplier]);

  const handleAskAI = async () => {
    setIsAiLoading(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Você é um consultor financeiro sênior da Axis Accounting. 
      Analise o seguinte cenário financeiro CONSOLIDADO DO EXTRATO MANUAL para o período ${period === 'monthly' ? 'Mensal' : period === 'quarterly' ? 'Trimestral' : 'Anual'}:

      DADOS DO CLIENTE:
      Empresa: ${focusedClient?.name || 'Empresário'}
      Anexo Simples: ${focusedClient?.taxAnexo || 'III'}

      MÉTRICAS REAIS DO PERÍODO:
      Receita (Extrato): R$ ${financialSummary.totalRev}
      Impostos DAS (Baseado na Receita do Extrato): R$ ${financialSummary.totalTaxes}
      Lucro Líquido Final: R$ ${financialSummary.netProfit}
      Margem Real: ${financialSummary.margin.toFixed(2)}%

      TAREFAS:
      1. Avalie a lucratividade real baseada nos lançamentos manuais.
      2. Dê recomendações sobre a viabilidade do negócio com esses números atuais.
      3. Sugira ajustes de custos se a margem estiver baixa.

      Responda em Português do Brasil de forma profissional e markdown.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setAiInsight(response.text || '');
    } catch (error) {
      setAiInsight('Análise suspensa temporariamente.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm gap-4">
        <div className="space-y-1">
          <h2 className="text-xl md:text-2xl font-black text-slate-800 uppercase tracking-tight">Consolidação de Faturamento</h2>
          <p className="text-slate-500 text-xs font-medium">Dados agregados automaticamente do seu extrato manual.</p>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-2xl w-full md:w-auto">
          {(['monthly', 'quarterly', 'annual'] as const).map(p => (
            <button 
              key={p}
              onClick={() => setPeriod(p)}
              className={`flex-1 md:px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              {p === 'monthly' ? 'Mensal' : p === 'quarterly' ? 'Trimestral' : 'Anual'}
            </button>
          ))}
        </div>
      </header>

      {/* MÉTRICAS CONSOLIDADAS */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: 'Receita Total (Extrato)', value: financialSummary.totalRev, color: 'text-slate-900', accent: 'bg-slate-900' },
          { label: 'Lucro Líquido Real', value: financialSummary.netProfit, color: 'text-emerald-600', accent: 'bg-emerald-500' },
          { label: 'Imposto DAS (Calculado)', value: financialSummary.totalTaxes, color: 'text-blue-600', accent: 'bg-blue-600' },
          { label: 'Custos Provisionados', value: financialSummary.totalFixed + financialSummary.totalVar, color: 'text-amber-600', accent: 'bg-amber-500' },
        ].map((item, i) => (
          <div key={i} className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col justify-between transition-all hover:shadow-lg relative overflow-hidden">
            <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${item.accent} opacity-20`}></div>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.15em] mb-4">
              {item.label}
            </p>
            <div className="flex flex-col">
              <span className={`text-2xl md:text-3xl lg:text-4xl font-black ${item.color} tracking-tighter leading-none mb-2`}>
                {fmt(item.value)}
              </span>
              <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">
                Valores {period === 'monthly' ? 'do Mês' : period === 'quarterly' ? 'do Trimestre' : 'Anuais'}
              </span>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* PARÂMETROS DE CUSTO */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
            <div>
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center mb-4">
                <span className="w-2 h-2 bg-blue-500 rounded-full mr-2"></span> Fonte de Dados
              </h3>
              <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100">
                <p className="text-[9px] font-black text-blue-600 uppercase mb-1">Receita Identificada</p>
                <p className="text-xl font-black text-blue-900">{fmt(faturamentoManual)}</p>
                <p className="text-[10px] text-blue-700 mt-1 italic font-medium">Sincronizado com Extrato Financeiro</p>
              </div>
            </div>

            <div className="pt-4 border-t border-slate-50">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center mb-4">
                <span className="w-2 h-2 bg-amber-500 rounded-full mr-2"></span> Provisão de Gastos
              </h3>
              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Custos Fixos (Estimativa)</label>
                  <input type="number" value={fixedCosts} onChange={(e) => setFixedCosts(Number(e.target.value))} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Custos Variáveis (Estimativa)</label>
                  <input type="number" value={variableCosts} onChange={(e) => setVariableCosts(Number(e.target.value))} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* ANÁLISE GRÁFICA */}
        <div className="lg:col-span-8 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[400px]">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Composição Real da Receita</h3>
               <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={pieData} cx="50%" cy="50%" innerRadius={70} outerRadius={110} paddingAngle={8} dataKey="value">
                        {pieData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                        ))}
                      </Pie>
                      <Tooltip formatter={(value: number) => fmt(value)} contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', fontWeight: 800}} />
                    </PieChart>
                  </ResponsiveContainer>
               </div>
            </div>

            <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[400px]">
               <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Sensibilidade de Margem</h3>
               <div className="flex-1">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={sensitivityData} margin={{ top: 20, right: 0, left: -25, bottom: 0 }}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="label" tick={{fontSize: 9, fontWeight: 900, fill: '#94a3b8'}} />
                      <Tooltip formatter={(value: number) => fmt(value)} contentStyle={{borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', fontWeight: 800}} />
                      <Bar dataKey="lucro" name="Lucro" fill="#10b981" radius={[6, 6, 0, 0]} />
                      <Bar dataKey="impostos" name="Impostos" fill="#3b82f6" radius={[6, 6, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
               </div>
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-xl overflow-hidden flex flex-col min-h-[450px]">
             <div className="p-8 bg-slate-900 text-white flex flex-col md:flex-row items-center justify-between gap-6">
                <div className="flex items-center space-x-5">
                   <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-2xl shadow-2xl">🤖</div>
                   <div>
                      <h4 className="font-black text-lg uppercase tracking-tight">Axis Real Analysis</h4>
                      <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest">IA Sincronizada com seu Extrato</p>
                   </div>
                </div>
                <button 
                  onClick={handleAskAI}
                  disabled={isAiLoading || faturamentoManual === 0}
                  className="w-full md:w-auto px-10 py-4 bg-white text-slate-900 rounded-2xl font-black text-[12px] uppercase tracking-widest hover:bg-blue-50 transition-all disabled:opacity-50"
                >
                   {isAiLoading ? 'Analizando...' : 'Gerar Insight Real'}
                </button>
             </div>

             <div className="p-10 flex-1 overflow-y-auto max-h-[400px]">
                {aiInsight ? (
                  <div className="prose prose-sm max-w-none text-slate-700 whitespace-pre-wrap">{aiInsight}</div>
                ) : (
                  <div className="h-full flex flex-col items-center justify-center text-slate-400 space-y-4">
                    <span className="text-4xl grayscale opacity-20">📊</span>
                    <p className="text-[10px] font-black uppercase tracking-widest">Aguardando solicitação de análise baseada no extrato</p>
                  </div>
                )}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

