    if (confirm(`⚠️ Excluir empresa "${clientToDelete.name}"?`)) {
      try {
        const success = await deleteClientRequest(clientId);
        if (success) {
          setClients(prev => prev.filter(c => c.id !== clientId));
          setUserAccounts(prev => prev.map(user => user.cnpjVinculado === clientToDelete.identifier ? { ...user, status: 'blocked', cnpjVinculado: undefined } : user));
          if (focusedClient?.id === clientId) setFocusedClient(null);
          alert(`Empresa ${clientToDelete.identifier} deletada.`);
        }
      } catch (error) {
        alert("Erro na exclusão.");
      }
    }
