import React, { useState, useRef, useEffect } from 'react';
import { chatWithAccountingAI } from '../services/geminiService';
import { Client } from '../types';
import { calculateSimplesNacional } from '../services/taxCalculator';

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

interface AIChatProps {
  focusedClient?: Client | null;
}

const AIChat: React.FC<AIChatProps> = ({ focusedClient }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'assistant', content: 'Olá! Sou o Axis AI. Minhas análises são baseadas estritamente nos cálculos de precificação e planejamento do sistema. Em que posso ajudar?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
    setInput('');
    setIsLoading(true);

    // Contexto baseado na fonte única de verdade (Precificação/Planejamento)
    let fiscalContext = {};

    if (focusedClient) {
      const rbt12 = focusedClient.annualRevenue || 0;
      const anexo = focusedClient.taxAnexo || 'III';
      // Utilizamos o motor de cálculo oficial como referência absoluta para a IA
      const officialCalculation = calculateSimplesNacional(rbt12, 1000, anexo);

      fiscalContext = {
        referencia_fonte_verdade: "Aba Precificação e Planejamento Tributário",
        empresa: focusedClient.name,
        cnpj_cpf: focusedClient.identifier,
        regime: 'Simples Nacional',
        anexo_configurado: anexo,
        faturamento_rbt12: rbt12,
        logica_calculo_oficial: {
          aliquota_nominal: `${(officialCalculation.nominalRate * 100).toFixed(2)}%`,
          parcela_deducao: officialCalculation.deduction,
          aliquota_efetiva_calculada: `${(officialCalculation.effectiveRate * 100).toFixed(2)}%`,
          limite_faixa_atual: officialCalculation.bracketLimit,
          indice_faixa: officialCalculation.bracketIndex
        },
        cnae: focusedClient.cnaePrimary
      };
    } else {
      fiscalContext = {
        status: 'Sem cliente focado',
        regra: 'Utilizar exclusivamente as tabelas de alíquotas do Simples Nacional configuradas no sistema.'
      };
    }

    const response = await chatWithAccountingAI(userMsg, fiscalContext);

    setMessages(prev => [...prev, { role: 'assistant', content: response || "Erro ao responder." }]);
    setIsLoading(false);
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)] bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <header className="p-4 border-b border-slate-100 flex items-center justify-between bg-slate-900 text-white">
        <div className="flex items-center space-x-3">
          <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center text-xl shadow-lg">🤖</div>
          <div>
            <h3 className="font-bold">Axis AI</h3>
            <p className="text-[10px] text-blue-300 font-black uppercase tracking-widest">
              {focusedClient ? `Operational: ${focusedClient.name}` : 'Inteligência Sincronizada'}
            </p>
          </div>
        </div>
        <div className="hidden md:block px-3 py-1 bg-white/10 rounded-lg border border-white/5">
           <span className="text-[9px] font-black text-emerald-400 uppercase tracking-tighter">Fórmulas Bloqueadas</span>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/30 no-scrollbar">
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${
              msg.role === 'user' 
                ? 'bg-blue-600 text-white rounded-tr-none' 
                : 'bg-white text-slate-700 rounded-tl-none border border-slate-100'
            }`}>
              <div className="text-sm leading-relaxed whitespace-pre-wrap prose prose-sm max-w-none">
                {msg.content}
              </div>
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 rounded-tl-none flex space-x-1">
              <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce"></div>
              <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
              <div className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-white border-t border-slate-100">
        <div className="flex items-center space-x-2 bg-slate-50 p-2 rounded-xl border border-slate-200 focus-within:ring-2 focus-within:ring-blue-500/20 focus-within:border-blue-500 transition-all">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Consulte dados operacionais baseados na precificação..."
            className="flex-1 bg-transparent border-none focus:outline-none px-2 text-sm text-slate-700 h-10"
          />
          <button 
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="bg-blue-600 text-white p-2.5 rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50 shadow-md shadow-blue-500/20"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </div>
        <p className="text-[8px] text-center text-slate-400 mt-3 font-black uppercase tracking-[0.2em]">
          A IA NÃO ALTERA ESTRUTURAS OU FÓRMULAS DE PRECIFICAÇÃO E PLANEJAMENTO.
        </p>
      </div>
    </div>
  );
};

