import React, { useState, useMemo } from 'react';
import { Client, Revenue } from '../types';
import { calculateSimplesNacional } from '../services/taxCalculator';
import { GoogleGenAI } from "@google/genai";
import { 
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer, 
  BarChart, Bar, XAxis, CartesianGrid 
} from 'recharts';

interface FinancialPlannerProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  selectedMonthIdx: number;
}

const FinancialPlanner: React.FC<FinancialPlannerProps> = ({ focusedClient, revenues, selectedMonthIdx }) => {
  // Custos provisionados (Estimativas manuais para análise de margem)
  const [fixedCosts, setFixedCosts] = useState<number>(10000);
  const [variableCosts, setVariableCosts] = useState<number>(5000);
  const [period, setPeriod] = useState<'monthly' | 'quarterly' | 'annual'>('monthly');

  // Estados da IA (Apenas operacional)
  const [aiInsight, setAiInsight] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const multiplier = period === 'monthly' ? 1 : period === 'quarterly' ? 3 : 12;

  // 1. RECEITA TOTAL: SOMATÓRIO EXATO DOS LANÇAMENTOS MANUAIS DO EXTRATO
  const faturamentoManual = useMemo(() => {
    // Considerar apenas lançamentos manuais confirmados e vinculados ao cliente
    const relevant = revenues.filter(r => 
      (focusedClient ? r.clientId === focusedClient.id : true) && 
      r.source === 'manual' && 
      r.entryType === 'inflow'
    );

    const sumForPeriod = (startMonth: number, endMonth: number) => {
      return relevant
        .filter(r => {
          const m = parseInt(r.date.split('-')[1]) - 1;
          return m >= startMonth && m <= endMonth;
        })
        .reduce((acc, r) => acc + r.amount, 0);
    };

    if (period === 'monthly') return sumForPeriod(selectedMonthIdx, selectedMonthIdx);
    if (period === 'quarterly') {
      const qStart = Math.floor(selectedMonthIdx / 3) * 3;
      return sumForPeriod(qStart, qStart + 2);
    }
    return sumForPeriod(0, 11);
  }, [revenues, focusedClient, selectedMonthIdx, period]);

  // 2. IMPOSTO CALCULADO: ESPELHAMENTO 1:1 COM PLANEJAMENTO TRIBUTÁRIO
  // Utiliza a mesma fonte de verdade (Anexo, Faixa e Alíquota Efetiva)
  const taxResults = useMemo(() => {
    const rbt12 = focusedClient?.annualRevenue || 0;
    const anexo = focusedClient?.taxAnexo || 'III';

    // Aplica rigorosamente a mesma alíquota efetiva do motor de cálculo
    const calculation = calculateSimplesNacional(rbt12, faturamentoManual, anexo);

    return {
      ...calculation,
      totalTax: calculation.taxAmount 
    };
  }, [focusedClient, faturamentoManual]);

  const financialSummary = useMemo(() => {
    const totalRev = faturamentoManual;
    const totalFixed = fixedCosts * multiplier;
    const totalVar = variableCosts * multiplier;
    const totalTaxes = taxResults.totalTax;

    const totalCosts = totalFixed + totalVar + totalTaxes;
    const netProfit = totalRev - totalCosts;
    const margin = totalRev > 0 ? (netProfit / totalRev) * 100 : 0;

    return {
      totalRev,
      totalFixed,
      totalVar,
      totalTaxes,
      totalCosts,
      netProfit,
      margin
    };
  }, [faturamentoManual, fixedCosts, variableCosts, taxResults, multiplier]);

  const pieData = [
    { name: 'Lucro Líquido', value: Math.max(0, financialSummary.netProfit), color: '#10b981' },
    { name: 'Imposto Calculado (DAS)', value: financialSummary.totalTaxes, color: '#3b82f6' },
    { name: 'Custos Fixos', value: financialSummary.totalFixed, color: '#f59e0b' },
    { name: 'Custos Variáveis', value: financialSummary.totalVar, color: '#94a3b8' },
  ];

  const handleAskAI = async () => {
    setIsAiLoading(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Você é um assistente operacional. Analise os resultados abaixo baseados estritamente nas fórmulas do sistema:
      - Receita Real (Extrato): R$ ${financialSummary.totalRev}
      - Imposto Calculado (Pareado ao Planejamento): R$ ${financialSummary.totalTaxes}
      - Margem Líquida: ${financialSummary.margin.toFixed(2)}%

      Não altere as regras de cálculo. Apenas forneça uma interpretação estratégica dos números.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setAiInsight(response.text || '');
    } catch (error) {
      setAiInsight('Falha na conexão operacional.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="space-y-1">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Gestão Financeira Estratégica</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Análise de Faturamento Real</h2>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-2xl">
          {(['monthly', 'quarterly', 'annual'] as const).map(p => (
            <button 
              key={p}
              onClick={() => setPeriod(p)}
              className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              {p === 'monthly' ? 'Mensal' : p === 'quarterly' ? 'Trimestral' : 'Anual'}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Receita Total (Extrato)</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">{fmt(financialSummary.totalRev)}</p>
          <p className="text-[9px] text-slate-400 mt-2 font-bold uppercase tracking-widest">Sincronizado em tempo real</p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-2">Imposto Calculado</p>
          <p className="text-3xl font-black text-blue-600 tracking-tighter">{fmt(financialSummary.totalTaxes)}</p>
          <p className="text-[9px] text-blue-400 mt-2 font-bold uppercase tracking-widest">Alíquota Efetiva: {(taxResults.effectiveRate * 100).toFixed(2)}%</p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-2">Lucro Líquido Real</p>
          <p className="text-3xl font-black text-emerald-600 tracking-tighter">{fmt(financialSummary.netProfit)}</p>
          <p className="text-[9px] text-emerald-400 mt-2 font-bold uppercase tracking-widest">Margem: {financialSummary.margin.toFixed(1)}%</p>
