                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Provisionamento Fixo</label>
                  <input type="number" value={fixedCosts} onChange={(e) => setFixedCosts(Number(e.target.value))} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Custos Variáveis</label>
                  <input type="number" value={variableCosts} onChange={(e) => setVariableCosts(Number(e.target.value))} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
                </div>
             </div>
          </div>
        </div>

        <div className="lg:col-span-8 space-y-8">
