                <button 
                  onClick={handleAskAI}
                  disabled={isAiLoading}
                  className="px-6 py-3 bg-white text-slate-900 rounded-xl font-black text-[10px] uppercase tracking-widest disabled:opacity-50"
                >
                   {isAiLoading ? 'Analisando...' : 'Obter Recomendações'}
                </button>
             </div>
             <div className="p-10 text-slate-400 text-sm leading-relaxed min-h-[200px]">
                {aiInsight || 'Solicite uma análise consultiva baseada nos dados projetados acima.'}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

