             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FinancialPlanner;

import React, { useState, useMemo } from 'react';
import { Revenue, Client, User } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
  selectedMonthIdx: number;
  setSelectedMonthIdx: (idx: number) => void;
  currentUser: User | null;
}

const months = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues, selectedMonthIdx, setSelectedMonthIdx, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'expected'>('all');
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    client: '',
    amount: '',
    date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    description: ''
  });

  const filteredByClient = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;
  }, [revenues, focusedClient]);

  const monthlyTotals = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.forEach(rev => {
      const dateParts = rev.date.split('-');
      const m = parseInt(dateParts[1]) - 1;
      if (rev.entryType === 'inflow') {
        totals[m] += rev.amount;
      } else {
        totals[m] -= rev.amount;
      }
    });
    return totals;
  }, [filteredByClient]);

  const monthlyInflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'inflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const monthlyOutflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'outflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      const matchesMonth = m === selectedMonthIdx;
      const matchesSearch = rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            rev.description?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || rev.status === statusFilter;
      return matchesMonth && matchesSearch && matchesStatus;
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm, statusFilter]);

  const handleOpenAdd = () => {
    setEditingId(null);
    setFormData({
      client: '',
      amount: '',
      date: new Date().toISOString().split('T')[0],
      status: 'received',
      entryType: 'inflow',
      description: ''
    });
    setShowModal(true);
  };

  const handleOpenEdit = (rev: Revenue) => {
    setEditingId(rev.id);
    setFormData({
      client: rev.client,
      amount: rev.amount.toString(),
      date: rev.date,
      status: rev.status,
      entryType: rev.entryType,
      description: rev.description || ''
    });
    setShowModal(true);
  };

  const handleDelete = (id: string) => {
    const rev = revenues.find(r => r.id === id);
    if (!rev) return;

    if (rev.source !== 'manual' || rev.createdBy !== currentUser?.id) {
      alert("Ação Bloqueada: Você só pode excluir lançamentos manuais criados por você.");
      return;
    }

    if (confirm("Deseja excluir permanentemente este lançamento?")) {
      setRevenues(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      setRevenues(prev => prev.map(r => r.id === editingId ? {
        ...r,
        client: formData.client,
        amount: parseFloat(formData.amount),
        date: formData.date,
        status: formData.status,
        entryType: formData.entryType,
        description: formData.description,
      } : r));
    } else {
      const newRev: Revenue = {
        id: `man-${Math.random().toString(36).substr(2, 9)}`,
        client: formData.client,
        amount: parseFloat(formData.amount),
        date: formData.date,
        status: formData.status,
        entryType: formData.entryType,
        description: formData.description,
        source: 'manual',
        clientId: focusedClient?.id || '1',
        createdBy: currentUser?.id
      };
      setRevenues(prev => [newRev, ...prev]);
    }

    setShowModal(false);
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative">
        <div className="space-y-1 relative z-10">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Fluxo de Caixa</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Extrato Detalhado</h2>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-widest">{months[selectedMonthIdx]} / 2024</p>
        </div>

        <div className="flex flex-wrap gap-4 relative z-10">
           <div className="bg-emerald-50 px-6 py-4 rounded-2xl border border-emerald-100">
             <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mb-1">Entradas</p>
             <p className="text-xl font-black text-emerald-700">{fmt(monthlyInflows[selectedMonthIdx])}</p>
           </div>
           <div className="bg-red-50 px-6 py-4 rounded-2xl border border-red-100">
             <p className="text-[9px] font-black text-red-600 uppercase tracking-widest mb-1">Saídas</p>
             <p className="text-xl font-black text-red-700">{fmt(Math.abs(monthlyOutflows[selectedMonthIdx]))}</p>
           </div>
           <div className={`px-8 py-4 rounded-2xl shadow-xl min-w-[180px] ${monthlyTotals[selectedMonthIdx] >= 0 ? 'bg-slate-900 text-white' : 'bg-red-600 text-white'}`}>
              <p className="text-[9px] font-black text-white/50 uppercase tracking-widest mb-1">Saldo</p>
              <p className="text-2xl font-black tracking-tighter">{fmt(monthlyTotals[selectedMonthIdx])}</p>
           </div>
        </div>
      </header>

      <div className="grid grid-cols-3 md:grid-cols-6 lg:grid-cols-12 gap-2">
        {months.map((m, idx) => (
          <button
            key={m}
            onClick={() => setSelectedMonthIdx(idx)}
            className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-tighter transition-all ${
              selectedMonthIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100 hover:border-blue-200'
            }`}
          >
            {m.substring(0, 3)}
          </button>
        ))}
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Buscar lançamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
          />
        </div>
        <button 
          onClick={handleOpenAdd}
          className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-800 transition-all flex items-center justify-center space-x-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          <span>Novo Lançamento</span>
        </button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50 text-slate-400 text-[9px] font-black uppercase tracking-[0.2em] border-b border-slate-100">
              <th className="px-8 py-5">Data / Tipo</th>
              <th className="px-8 py-5">Descrição</th>
              <th className="px-8 py-5 text-right">Valor</th>
              <th className="px-8 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredRevenues.length > 0 ? filteredRevenues.map((rev) => (
              <tr key={rev.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-8 py-5">
                  <div className="flex items-center space-x-4">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-[10px] ${
                      rev.entryType === 'inflow' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'
                    }`}>
                      {rev.date.split('-')[2]}
                    </div>
                    <div>
                      <p className="text-xs font-black text-slate-800 uppercase tracking-tighter">
                        {rev.entryType === 'inflow' ? 'Entrada' : 'Saída'}
                      </p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{rev.date.split('-').reverse().join('/')}</p>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-5">
                  <div>
                    <p className="text-sm font-bold text-slate-700">{rev.client}</p>
                    <p className="text-[10px] text-slate-400 truncate max-w-xs">{rev.description}</p>
                  </div>
                </td>
                <td className="px-8 py-5 text-right">
                  <p className={`text-sm font-black ${rev.entryType === 'inflow' ? 'text-emerald-600' : 'text-red-600'}`}>
                    {rev.entryType === 'inflow' ? '+' : '-'} {fmt(rev.amount)}
                  </p>
                </td>
                <td className="px-8 py-5 text-right">
                  <div className="flex items-center justify-end space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    {rev.source === 'manual' && rev.createdBy === currentUser?.id ? (
                      <>
                        <button onClick={() => handleOpenEdit(rev)} className="p-2.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                        </button>
                        <button onClick={() => handleDelete(rev.id)} className="p-2.5 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                        </button>
                      </>
                    ) : (
                      <span className="text-[8px] font-black text-slate-300 uppercase px-2">Bloqueado</span>
                    )}
                  </div>
                </td>
              </tr>
            )) : (
              <tr><td colSpan={4} className="py-20 text-center text-slate-400 text-[10px] font-black uppercase">Sem registros</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in duration-300">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-8">
              {editingId ? 'Editar Lançamento' : 'Novo Lançamento'}
            </h3>
            <form onSubmit={handleSave} className="space-y-6">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                <button type="button" onClick={() => setFormData({...formData, entryType: 'inflow'})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${formData.entryType === 'inflow' ? 'bg-emerald-500 text-white shadow-lg' : 'text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setFormData({...formData, entryType: 'outflow'})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${formData.entryType === 'outflow' ? 'bg-red-500 text-white shadow-lg' : 'text-slate-400'}`}>Saída</button>
              </div>
