        setIsSidebarCollapsed(true);
      }
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: UserRole) => {
    const matchedAccount = userAccounts.find(u => u.role === role);
    setCurrentUser({
      id: matchedAccount?.id || (role === UserRole.ADMIN ? 'admin-1' : 'client-123'),
      name: matchedAccount?.name || (role === UserRole.ADMIN ? 'Admin Axis' : 'Cliente Exemplo'),
      role: role,
      cnpjVinculado: role === UserRole.CLIENT ? clients[0].identifier : undefined
    });

    if (role === UserRole.CLIENT) {
      const client = clients[0];
      if (client) setFocusedClient(client);
    }
    setCurrentView(View.DASHBOARD);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
