import React, { useState, useMemo } from 'react';
import { Client, Revenue } from '../types';
import { calculateSimplesNacional } from '../services/taxCalculator';
import { GoogleGenAI } from "@google/genai";
import { 
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer 
} from 'recharts';

interface FinancialPlannerProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  selectedMonthIdx: number;
}

const FinancialPlanner: React.FC<FinancialPlannerProps> = ({ focusedClient, revenues, selectedMonthIdx }) => {
  // Custos provisionados (Estimativas manuais para análise de margem líquida)
  const [fixedCosts, setFixedCosts] = useState<number>(10000);
  const [variableCosts, setVariableCosts] = useState<number>(5000);
  const [period, setPeriod] = useState<'monthly' | 'quarterly' | 'annual'>('monthly');

  const [aiInsight, setAiInsight] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  const multiplier = period === 'monthly' ? 1 : period === 'quarterly' ? 3 : 12;

  // 1. CÁLCULO DA RECEITA MENSAL TRIBUTÁVEL (Soma dos créditos operacionais do extrato)
  // Added: Explicit useMemo type parameter to resolve unknown type assignment errors
  const monthlyRevenueTributable = useMemo<number>(() => {
    const relevant = focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;

    const getMonthRev = (mIdx: number): number => {
      return relevant
        .filter(r => {
          const dateParts = r.date.split('-');
          const m = parseInt(dateParts[1]) - 1;
          return m === mIdx && r.entryType === 'inflow';
        })
        .reduce((acc, r) => acc + (r.amount || 0), 0);
    };

    if (period === 'monthly') return getMonthRev(selectedMonthIdx);

    if (period === 'quarterly') {
      const qStart = Math.floor(selectedMonthIdx / 3) * 3;
      return getMonthRev(qStart) + getMonthRev(qStart + 1) + getMonthRev(qStart + 2);
    }

    if (period === 'annual') {
      return Array.from({length: 12}).reduce((acc: number, _, i) => acc + getMonthRev(i), 0);
    }

    return 0;
  }, [revenues, focusedClient, selectedMonthIdx, period]);

  // 2. CÁLCULO DO RBT12 REAL (Soma dos últimos 12 meses de receita operacional no extrato)
  // Added: Explicit useMemo type parameter
  const rbt12Real = useMemo<number>(() => {
    const relevant = focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id && r.entryType === 'inflow') 
      : revenues.filter(r => r.entryType === 'inflow');

    // Aqui somamos todo o histórico de créditos operacionais para determinar a faixa
    return relevant.reduce((acc, r) => acc + (r.amount || 0), 0);
  }, [revenues, focusedClient]);

  // 3. IMPOSTO CALCULADO: Derivado diretamente do Planejamento Tributário (Motor Simples Nacional)
  const taxData = useMemo(() => {
    // Parâmetros de enquadramento (Anexo selecionado no Perfil do Cliente)
    const anexo = focusedClient?.taxAnexo || 'III';

    // Cálculo oficial: Anexo -> RBT12 -> Faixa -> Alíquota Nominal -> Parcela a Deduzir -> Alíquota Efetiva
    return calculateSimplesNacional(rbt12Real, monthlyRevenueTributable, anexo);
  }, [rbt12Real, monthlyRevenueTributable, focusedClient]);

  const financialSummary = useMemo(() => {
    const totalRev = monthlyRevenueTributable;
    const totalFixed = fixedCosts * multiplier;
    const totalVar = variableCosts * multiplier;
    const totalTaxes = taxData.taxAmount;

    const totalCosts = totalFixed + totalVar + totalTaxes;
    const netProfit = totalRev - totalCosts;
    const margin = totalRev > 0 ? (netProfit / totalRev) * 100 : 0;

    return {
      totalRev,
      totalFixed,
      totalVar,
      totalTaxes,
      totalCosts,
      netProfit,
      margin
    };
  }, [monthlyRevenueTributable, fixedCosts, variableCosts, taxData, multiplier]);

  const pieData = [
    { name: 'Lucro Líquido', value: Math.max(0, financialSummary.netProfit), color: '#10b981' },
    { name: 'DAS Simples (Oficial)', value: financialSummary.totalTaxes, color: '#3b82f6' },
    { name: 'Custos Fixos', value: financialSummary.totalFixed, color: '#f59e0b' },
    { name: 'Custos Variáveis', value: financialSummary.totalVar, color: '#94a3b8' },
  ];

  const handleAskAI = async () => {
    setIsAiLoading(true);
    // Correctly initialize GoogleGenAI with named parameter
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Analise operacionalmente estes dados REAIS sincronizados:
      - Receita Mensal Operacional (Extrato): ${fmt(financialSummary.totalRev)}
      - RBT12 Acumulado (Base de Faixa): ${fmt(rbt12Real)}
      - Anexo Aplicado: ${taxData.appliedAnexo}
      - Faixa Enquadrada: ${taxData.bracketIndex}ª
      - Alíquota Efetiva Calculada: ${(taxData.effectiveRate * 100).toFixed(2)}%
      - DAS Mensal: ${fmt(financialSummary.totalTaxes)}

      IMPORTANTE: Seus comentários devem apenas explicar o fluxo financeiro. Você não tem autoridade para sugerir mudanças nas alíquotas ou na lógica de cálculo tributário do sistema.
    `;

    try {
      // Use ai.models.generateContent per standard Google GenAI guidelines
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      // Correct property access for text
      setAiInsight(response.text || '');
    } catch (error) {
      setAiInsight('Falha na sincronização operacional com a IA.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="space-y-1">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Gestão Financeira Consolidada</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Fluxo de Caixa e Impostos Reais</h2>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-2xl">
          {(['monthly', 'quarterly', 'annual'] as const).map(p => (
            <button 
              key={p}
              onClick={() => setPeriod(p)}
              className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${period === p ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
            >
              {p === 'monthly' ? 'Mensal' : p === 'quarterly' ? 'Trimestral' : 'Anual'}
            </button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Receita Mensal Operacional</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">{fmt(financialSummary.totalRev)}</p>
          <div className="absolute top-4 right-4 flex space-x-1">
             <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
          </div>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-2">DAS Simples Nacional</p>
          <p className="text-3xl font-black text-blue-600 tracking-tighter">{fmt(financialSummary.totalTaxes)}</p>
          <p className="text-[9px] text-blue-400 mt-2 font-bold uppercase tracking-widest">Alíquota Efetiva: {(taxData.effectiveRate * 100).toFixed(2)}%</p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-2">Lucro Líquido Real</p>
          <p className="text-3xl font-black text-emerald-600 tracking-tighter">{fmt(financialSummary.netProfit)}</p>
          <p className="text-[9px] text-emerald-400 mt-2 font-bold uppercase tracking-widest">Margem: {financialSummary.margin.toFixed(1)}%</p>
        </div>
        <div className="bg-slate-900 p-8 rounded-[2rem] shadow-xl text-white">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">RBT12 Acumulado</p>
          <p className="text-3xl font-black text-white tracking-tighter">{fmt(rbt12Real)}</p>
          <p className="text-[9px] text-slate-500 mt-2 font-bold uppercase tracking-widest">Base de Enquadramento</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
             <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Governança Fiscal</h3>

             <div className="p-5 bg-blue-50 rounded-2xl border border-blue-100 space-y-3">
                <div className="flex items-center space-x-2 text-[10px] font-black text-blue-600 uppercase">
                   <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"/></svg>
                   <span>Planejamento Tributário Sincronizado</span>
                </div>
                <div className="grid grid-cols-2 gap-2 text-[10px] font-bold">
                   <div className="text-slate-500">Anexo:</div>
                   <div className="text-slate-900 text-right">{taxData.appliedAnexo}</div>
                   <div className="text-slate-500">Faixa RBT12:</div>
                   <div className="text-slate-900 text-right">{taxData.bracketIndex}ª</div>
                   <div className="text-slate-500">Alíq. Nominal:</div>
                   <div className="text-slate-900 text-right">{(taxData.nominalRate * 100).toFixed(2)}%</div>
                   <div className="text-slate-500">Parcela Deduc.:</div>
                   <div className="text-slate-900 text-right">{fmt(taxData.deduction)}</div>
                </div>
             </div>

             <div className="space-y-4 pt-4 border-t border-slate-100">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Provisionamento Fixo</label>
                  <input type="number" value={fixedCosts} onChange={(e) => setFixedCosts(Number(e.target.value))} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:bg-white" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Custos Variáveis Estimados</label>
                  <input type="number" value={variableCosts} onChange={(e) => setVariableCosts(Number(e.target.value))} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:bg-white" />
                </div>
             </div>
          </div>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm h-[400px]">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-8">Composição do Fluxo Real</h3>
            <div className="h-64">
               <ResponsiveContainer width="100%" height="100%">
                 <PieChart>
                   <Pie data={pieData} cx="50%" cy="50%" innerRadius={70} outerRadius={100} paddingAngle={8} dataKey="value">
                     {pieData.map((entry, index) => <Cell key={index} fill={entry.color} />)}
                   </Pie>
                   <Tooltip formatter={(value: number) => fmt(value)} />
                 </PieChart>
               </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-slate-900 rounded-[2.5rem] overflow-hidden flex flex-col border border-white/5 shadow-2xl">
             <div className="p-8 border-b border-white/5 flex items-center justify-between">
                <div className="flex items-center space-x-4">
                   <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-xl">🤖</div>
                   <h4 className="text-white font-black uppercase text-sm tracking-tight">Axis AI Operational Monitor</h4>
                </div>
                <button 
                  onClick={handleAskAI}
                  disabled={isAiLoading || financialSummary.totalRev === 0}
                  className="px-6 py-3 bg-white text-slate-900 rounded-xl font-black text-[10px] uppercase tracking-widest disabled:opacity-50 active:scale-95 transition-all"
                >
                   {isAiLoading ? 'Sincronizando...' : 'Analisar Resultados Reais'}
                </button>
             </div>
             <div className="p-10 text-slate-400 text-sm leading-relaxed min-h-[200px] whitespace-pre-wrap">
                {aiInsight || 'Solicite uma análise operacional para verificar a conformidade dos impostos com os lançamentos do extrato.'}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FinancialPlanner;

import React, { useState, useMemo } from 'react';
import { Revenue, Client, User } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
  selectedMonthIdx: number;
  setSelectedMonthIdx: (idx: number) => void;
  currentUser: User | null;
}

const months = [
  'Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho',
  'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
];

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues, selectedMonthIdx, setSelectedMonthIdx, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | 'received' | 'expected'>('all');
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    client: '',
    amount: '',
    date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    description: ''
  });

  const filteredByClient = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;
  }, [revenues, focusedClient]);

  const monthlyTotals = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.forEach(rev => {
      const dateParts = rev.date.split('-');
      const m = parseInt(dateParts[1]) - 1;
      if (rev.entryType === 'inflow') {
        totals[m] += rev.amount;
      } else {
        totals[m] -= rev.amount;
      }
    });
    return totals;
  }, [filteredByClient]);

  const monthlyInflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'inflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const monthlyOutflows = useMemo(() => {
    const totals = new Array(12).fill(0);
    filteredByClient.filter(r => r.entryType === 'outflow').forEach(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      totals[m] += rev.amount;
    });
    return totals;
  }, [filteredByClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      const matchesMonth = m === selectedMonthIdx;
      const matchesSearch = rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            rev.description?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStatus = statusFilter === 'all' || rev.status === statusFilter;
      return matchesMonth && matchesSearch && matchesStatus;
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm, statusFilter]);

  const handleOpenAdd = () => {
    setEditingId(null);
    setFormData({
      client: '',
      amount: '',
      date: new Date().toISOString().split('T')[0],
      status: 'received',
      entryType: 'inflow',
      description: ''
    });
    setShowModal(true);
  };

  const handleOpenEdit = (rev: Revenue) => {
    setEditingId(rev.id);
    setFormData({
      client: rev.client,
      amount: rev.amount.toString(),
      date: rev.date,
      status: rev.status,
      entryType: rev.entryType,
      description: rev.description || ''
    });
    setShowModal(true);
  };

  const handleDelete = (id: string) => {
    // Exclusão imediata sem confirmação e sem checagem de autoria
    setRevenues(prev => prev.filter(r => r.id !== id));
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    if (editingId) {
      setRevenues(prev => prev.map(r => r.id === editingId ? {
        ...r,
        client: formData.client,
        amount: parseFloat(formData.amount),
        date: formData.date,
        status: formData.status,
        entryType: formData.entryType,
        description: formData.description,
      } : r));
    } else {
      const newRev: Revenue = {
        id: `man-${Math.random().toString(36).substr(2, 9)}`,
        client: formData.client,
        amount: parseFloat(formData.amount),
        date: formData.date,
        status: formData.status,
        entryType: formData.entryType,
        description: formData.description,
        source: 'manual',
        clientId: focusedClient?.id || '1',
        createdBy: currentUser?.id
      };
      setRevenues(prev => [newRev, ...prev]);
    }

    setShowModal(false);
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm relative">
        <div className="space-y-1 relative z-10">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Fluxo de Caixa</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Extrato Detalhado</h2>
          <p className="text-slate-500 text-sm font-bold uppercase tracking-widest">{months[selectedMonthIdx]} / 2024</p>
        </div>

        <div className="flex flex-wrap gap-4 relative z-10">
           <div className="bg-emerald-50 px-6 py-4 rounded-2xl border border-emerald-100">
             <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest mb-1">Entradas</p>
             <p className="text-xl font-black text-emerald-700">{fmt(monthlyInflows[selectedMonthIdx])}</p>
           </div>
           <div className="bg-red-50 px-6 py-4 rounded-2xl border border-red-100">
             <p className="text-[9px] font-black text-red-600 uppercase tracking-widest mb-1">Saídas</p>
             <p className="text-xl font-black text-red-700">{fmt(Math.abs(monthlyOutflows[selectedMonthIdx]))}</p>
           </div>
           <div className={`px-8 py-4 rounded-2xl shadow-xl min-w-[180px] ${monthlyTotals[selectedMonthIdx] >= 0 ? 'bg-slate-900 text-white' : 'bg-red-600 text-white'}`}>
              <p className="text-[9px] font-black text-white/50 uppercase tracking-widest mb-1">Saldo</p>
              <p className="text-2xl font-black tracking-tighter">{fmt(monthlyTotals[selectedMonthIdx])}</p>
           </div>
        </div>
      </header>

      <div className="grid grid-cols-3 md:grid-cols-6 lg:grid-cols-12 gap-2">
        {months.map((m, idx) => (
          <button
            key={m}
            onClick={() => setSelectedMonthIdx(idx)}
            className={`py-3 rounded-xl text-[10px] font-black uppercase tracking-tighter transition-all ${
              selectedMonthIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100 hover:border-blue-200'
            }`}
          >
            {m.substring(0, 3)}
          </button>
        ))}
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4">
        <div className="relative flex-1">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </span>
          <input 
            type="text" 
            placeholder="Buscar lançamentos..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500/20 outline-none transition-all"
          />
        </div>
        <button 
          onClick={handleOpenAdd}
          className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-slate-800 transition-all flex items-center justify-center space-x-2"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" /></svg>
          <span>Novo Lançamento</span>
        </button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50 text-slate-400 text-[9px] font-black uppercase tracking-[0.2em] border-b border-slate-100">
              <th className="px-8 py-5">Data / Tipo</th>
              <th className="px-8 py-5">Descrição</th>
              <th className="px-8 py-5 text-right">Valor</th>
              <th className="px-8 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredRevenues.length > 0 ? filteredRevenues.map((rev) => (
              <tr key={rev.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-8 py-5">
                  <div className="flex items-center space-x-4">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-[10px] ${
                      rev.entryType === 'inflow' ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'
                    }`}>
                      {rev.date.split('-')[2]}
                    </div>
                    <div>
                      <p className="text-xs font-black text-slate-800 uppercase tracking-tighter">
                        {rev.entryType === 'inflow' ? 'Entrada' : 'Saída'}
                      </p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{rev.date.split('-').reverse().join('/')}</p>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-5">
                  <div>
                    <p className="text-sm font-bold text-slate-700">{rev.client}</p>
                    <p className="text-[10px] text-slate-400 truncate max-w-xs">{rev.description}</p>
                  </div>
                </td>
                <td className="px-8 py-5 text-right">
                  <p className={`text-sm font-black ${rev.entryType === 'inflow' ? 'text-emerald-600' : 'text-red-600'}`}>
                    {rev.entryType === 'inflow' ? '+' : '-'} {fmt(rev.amount)}
                  </p>
                </td>
                <td className="px-8 py-5 text-right">
                  <div className="flex items-center justify-end space-x-1 opacity-100 transition-opacity">
                    <button onClick={() => handleOpenEdit(rev)} className="p-2.5 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-600 hover:text-white transition-all">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" /></svg>
                    </button>
                    <button onClick={() => handleDelete(rev.id)} className="p-2.5 bg-red-50 text-red-600 rounded-lg hover:bg-red-600 hover:text-white transition-all">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                    </button>
                  </div>
                </td>
              </tr>
            )) : (
              <tr><td colSpan={4} className="py-20 text-center text-slate-400 text-[10px] font-black uppercase">Sem registros</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in duration-300">
            <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight mb-8">
              {editingId ? 'Editar Lançamento' : 'Novo Lançamento'}
            </h3>
            <form onSubmit={handleSave} className="space-y-6">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                <button type="button" onClick={() => setFormData({...formData, entryType: 'inflow'})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${formData.entryType === 'inflow' ? 'bg-emerald-500 text-white shadow-lg' : 'text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setFormData({...formData, entryType: 'outflow'})} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase ${formData.entryType === 'outflow' ? 'bg-red-500 text-white shadow-lg' : 'text-slate-400'}`}>Saída</button>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <input required value={formData.client} onChange={(e) => setFormData({...formData, client: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Descrição" />
                <input required type="number" step="0.01" value={formData.amount} onChange={(e) => setFormData({...formData, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Valor" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <input required type="date" value={formData.date} onChange={(e) => setFormData({...formData, date: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                <select value={formData.status} onChange={(e) => setFormData({...formData, status: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold">
                  <option value="received">Liquidado</option>
                  <option value="expected">Pendente</option>
                </select>
              </div>
              <textarea rows={2} value={formData.description} onChange={(e) => setFormData({...formData, description: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold resize-none" placeholder="Notas" />
              <div className="flex gap-4 pt-6">
                <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest">Confirmar</button>
                <button type="button" onClick={() => setShowModal(false)} className="px-8 py-5 border-2 border-slate-100 rounded-2xl font-black text-slate-400 uppercase">Cancelar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

