  { id: '1', name: 'Tecnologia Avançada LTDA', identifier: '12.345.678/0001-90', email: 'contato@techavancada.com', status: 'active', type: 'PJ', createdAt: '2024-01-10', annualRevenue: 0, integrations: [], taxAnexo: 'III', cnaePrimary: '6201-5/01' },
