];

const initialUserAccounts: UserAccount[] = [
  { id: 'USR_001', name: 'João Silva', email: 'joao@email.com', phone: '(11) 98877-6655', role: UserRole.CLIENT, createdAt: '2026-01-05', lastLogin: '2026-01-06 14:30', status: 'active', passwordHash: 'MTIzNDU2', cnpjVinculado: '12.345.678/0001-90' }, // senha: 123456
  { id: 'USR_458', name: 'Admin Master', email: 'admin@axis.com', phone: '(11) 90000-0000', role: UserRole.ADMIN, createdAt: '2025-10-12', lastLogin: '2026-01-06 18:20', status: 'active', passwordHash: 'YWRtaW4=' } // senha: admin
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [clients, setClients] = useState<Client[]>(initialClients);
  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(initialUserAccounts);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) setIsSidebarCollapsed(true);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (email: string, pass: string) => {
    const hashed = btoa(pass);
    const account = userAccounts.find(u => u.email.toLowerCase() === email.toLowerCase() && u.passwordHash === hashed);

    if (account) {
      if (account.status !== 'active') {
        alert("Acesso Bloqueado: Entre em contato com o administrador.");
        return;
      }

      const user: User = {
        id: account.id,
        name: account.name,
        role: account.role,
        cnpjVinculado: account.cnpjVinculado
      };

      setCurrentUser(user);

      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
      }

      setCurrentView(View.DASHBOARD);
      setUserAccounts(prev => prev.map(u => u.id === account.id ? {...u, lastLogin: new Date().toLocaleString('pt-BR')} : u));
    } else {
      alert("Credenciais Inválidas: Verifique e-mail e senha.");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const handleSelectClient = (client: Client) => {
    setFocusedClient(client);
    setCurrentView(View.DASHBOARD);
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const isImpersonating = currentUser.role === UserRole.ADMIN && focusedClient;

    const props = {
      focusedClient,
      userRole: currentUser.role,
      revenues,
      setRevenues,
      selectedMonthIdx,
      setSelectedMonthIdx,
      currentUser,
      clients,
      onSelectClient: handleSelectClient,
      onAddClient: (c: Client) => setClients(prev => [c, ...prev]),
      onDeleteClient: async (id: string) => {
        const success = await deleteClientRequest(id);
        if (success) setClients(prev => prev.filter(c => c.id !== id));
      },
      onUpdateClient: (c: Client) => setClients(prev => prev.map(old => old.id === c.id ? c : old)),
      users: userAccounts,
      setUsers: setUserAccounts
    };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...props} />;
      case View.CLIENTS: return <ClientManagement {...props} />;
      case View.DOCUMENTS: return <DocumentManager {...props} />;
      case View.TAXES: return <TaxTracker {...props} />;
      case View.REVENUE: return <RevenueSchedule {...props} />;
      case View.INVOICE_ISSUE: return <InvoiceIssuance {...props} />;
      case View.AI_CHAT: return <AIChat {...props} />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy {...props} />;
      case View.PAYROLL: return <PayrollManager {...props} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...props} />;
      case View.FINANCIAL_PLANNER: return <FinancialPlanner {...props} />;
      case View.ADMIN_USERS: return <AdminUserManager {...props} />;
      case View.SETTINGS: return <Settings {...props} />;
      default: return <Dashboard {...props} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />
      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate">
              <span className="text-lg">👁️</span>
              <span>Visualizando como: <b>{focusedClient.name}</b></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg">Sair do Modo Foco</button>
          </div>
        )}
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="mb-8">
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">{focusedClient ? 'Gestão Corporativa' : 'Painel de Controle'}</p>
            <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

