import React, { useState } from 'react';
import { UserAccount, UserRole, Client } from '../types';

interface AdminUserManagerProps {
  clients: Client[];
  users: UserAccount[];
  setUsers: React.Dispatch<React.SetStateAction<UserAccount[]>>;
}

const AdminUserManager: React.FC<AdminUserManagerProps> = ({ clients, users, setUsers }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<UserAccount | null>(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [resetFeedback, setResetFeedback] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    name: '', email: '', password: '', confirmPassword: '', phone: '', role: UserRole.CLIENT, status: 'active' as any, cnpjVinculado: ''
  });

  const generateRandomPassword = () => Math.random().toString(36).slice(-8);

  const handleCreateUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (users.some(u => u.email.toLowerCase() === formData.email.toLowerCase())) {
      alert('Erro: E-mail já cadastrado.'); return;
    }
    if (formData.password !== formData.confirmPassword) {
      alert('Erro: Senhas não coincidem.'); return;
    }

    const newUser: UserAccount = {
      id: `USR_${Date.now()}`,
      name: formData.name,
      email: formData.email,
      phone: formData.phone,
      role: formData.role,
      createdAt: new Date().toISOString().split('T')[0],
      lastLogin: 'Nunca',
      status: 'active',
      passwordHash: btoa(formData.password),
      cnpjVinculado: formData.role === UserRole.ADMIN ? undefined : formData.cnpjVinculado
    };

    setUsers(prev => [newUser, ...prev]);
    setShowCreateModal(false);
    alert('Usuário criado com sucesso!');
  };

  const handleResetPassword = (userId: string) => {
    const newPass = generateRandomPassword();
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, passwordHash: btoa(newPass) } : u));
    setResetFeedback(`SENHA RESETADA! Nova senha: ${newPass}`);
    setTimeout(() => setResetFeedback(null), 10000);
  };

  const toggleStatus = (id: string) => {
    setUsers(prev => prev.map(u => u.id === id ? { ...u, status: u.status === 'active' ? 'blocked' : 'active' } : u));
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-800 uppercase">Gestão de Usuários</h2>
          <p className="text-slate-500 text-xs">Administração de logins e reset de senhas.</p>
        </div>
        <button onClick={() => setShowCreateModal(true)} className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest">Novo Login</button>
      </header>

      {resetFeedback && (
        <div className="p-6 bg-emerald-600 text-white rounded-2xl shadow-xl animate-bounce">
          <p className="font-black text-sm uppercase mb-1">⚠️ ATENÇÃO ADMINISTRADOR</p>
          <p className="font-bold">{resetFeedback}</p>
          <p className="text-[10px] opacity-70 mt-2 italic">Informe esta senha ao cliente. Ela não será mostrada novamente.</p>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400">
              <tr>
                <th className="px-6 py-4">Usuário</th>
                <th className="px-6 py-4">Perfil</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {users.map(user => (
                <tr key={user.id} onClick={() => setSelectedUser(user)} className="hover:bg-slate-50 cursor-pointer">
                  <td className="px-6 py-4">
                    <p className="font-bold text-slate-800 text-sm">{user.name}</p>
                    <p className="text-[10px] text-slate-400">{user.email}</p>
                  </td>
                  <td className="px-6 py-4">
                    <span className="text-[10px] font-black uppercase text-blue-600">{user.role}</span>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`text-[10px] font-black uppercase ${user.status === 'active' ? 'text-emerald-500' : 'text-red-500'}`}>{user.status}</span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={(e) => {e.stopPropagation(); handleResetPassword(user.id);}} className="text-xs font-black text-amber-600 hover:underline">RESETAR SENHA</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="lg:col-span-4">
          {selectedUser ? (
            <div className="bg-slate-900 p-8 rounded-[2.5rem] text-white space-y-6 shadow-2xl">
              <div className="text-center">
                <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-2xl mx-auto mb-4">{selectedUser.name[0]}</div>
                <h3 className="font-black text-xl">{selectedUser.name}</h3>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{selectedUser.role}</p>
              </div>
              <div className="space-y-4 pt-4 border-t border-white/10">
                <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Segurança</span>
                  <span className="text-sm font-bold">Hash: {selectedUser.passwordHash.substring(0, 10)}...</span>
                </div>
                <button onClick={() => toggleStatus(selectedUser.id)} className="w-full py-4 border-2 border-white/10 rounded-2xl text-[10px] font-black uppercase hover:bg-white/5">
                  {selectedUser.status === 'active' ? 'Bloquear Acesso' : 'Ativar Acesso'}
                </button>
              </div>
            </div>
          ) : (
            <div className="h-full border-2 border-dashed rounded-[2.5rem] flex items-center justify-center text-slate-400 text-xs font-black uppercase">Selecione para ver detalhes</div>
          )}
        </div>
      </div>

      {showCreateModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg p-10 rounded-[2.5rem] shadow-2xl space-y-6">
            <h3 className="text-xl font-black uppercase tracking-tight">Novo Login Corporativo</h3>
            <form onSubmit={handleCreateUser} className="space-y-4">
              <input required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Nome do Usuário" />
              <input required type="email" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="E-mail" />
              <div className="grid grid-cols-2 gap-4">
                <input required type="password" value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Senha Inicial" />
                <input required type="password" value={formData.confirmPassword} onChange={(e) => setFormData({...formData, confirmPassword: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" placeholder="Confirme" />
              </div>
              <select value={formData.role} onChange={(e) => setFormData({...formData, role: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold">
                <option value={UserRole.CLIENT}>CLIENTE</option>
                <option value={UserRole.OPERATOR}>OPERADOR</option>
                <option value={UserRole.ADMIN}>ADMIN</option>
              </select>
              <div className="flex gap-4 pt-4">
                <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-black uppercase">Criar Login</button>
                <button type="button" onClick={() => setShowCreateModal(false)} className="px-8 py-5 border-2 rounded-2xl font-black uppercase text-slate-400">Sair</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminUserManager;

import React, { useState } from 'react';
import { User, UserAccount } from '../types';

interface SettingsProps {
  currentUser: User | null;
  users: UserAccount[];
  setUsers: React.Dispatch<React.SetStateAction<UserAccount[]>>;
}

const Settings: React.FC<SettingsProps> = ({ currentUser, users, setUsers }) => {
  const [currentPass, setCurrentPass] = useState('');
  const [newPass, setNewPass] = useState('');
  const [confirmPass, setConfirmPass] = useState('');

  const handleChangePassword = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentUser) return;

    const userAcc = users.find(u => u.id === currentUser.id);
    if (!userAcc) return;

    if (btoa(currentPass) !== userAcc.passwordHash) {
      alert("Erro: Senha atual incorreta."); return;
    }

    if (newPass !== confirmPass) {
      alert("Erro: Novas senhas não coincidem."); return;
    }

    if (newPass.length < 6) {
      alert("Erro: A nova senha deve ter no mínimo 6 caracteres."); return;
    }

    setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, passwordHash: btoa(newPass) } : u));
    alert("Senha alterada com sucesso!");
    setCurrentPass(''); setNewPass(''); setConfirmPass('');
  };

  return (
    <div className="max-w-2xl space-y-8">
      <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
        <header className="flex items-center space-x-4 mb-4">
          <div className="w-12 h-12 bg-slate-900 text-white rounded-2xl flex items-center justify-center text-xl">👤</div>
          <div>
            <h3 className="text-xl font-black text-slate-900 tracking-tight uppercase">Segurança da Conta</h3>
            <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Altere sua senha de acesso</p>
          </div>
        </header>

        <form onSubmit={handleChangePassword} className="space-y-5">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Senha Atual</label>
            <input required type="password" value={currentPass} onChange={(e) => setCurrentPass(e.target.value)} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nova Senha</label>
              <input required type="password" value={newPass} onChange={(e) => setNewPass(e.target.value)} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Confirmar Nova Senha</label>
              <input required type="password" value={confirmPass} onChange={(e) => setConfirmPass(e.target.value)} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
            </div>
          </div>
          <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl">Salvar Nova Senha</button>
        </form>
      </div>

      <div className="bg-amber-50 p-6 rounded-3xl border border-amber-100">
        <p className="text-[10px] font-black text-amber-600 uppercase tracking-[0.2em] mb-2">Aviso de Segurança</p>
        <p className="text-xs text-amber-800 leading-relaxed">Sua senha é pessoal e intransferível. O administrador do sistema **nunca** solicitará sua senha atual por e-mail ou telefone. Caso esqueça, solicite um **Reset de Senha** para gerar uma nova chave temporária.</p>
      </div>
    </div>
  );
};

export default Settings;

