import React, { useState, useEffect } from 'react';
import { Client, TaxAnexo, UserAccount, UserRole } from '../types';

interface ClientManagementProps {
  clients: Client[];
  users: UserAccount[];
  setUsers: React.Dispatch<React.SetStateAction<UserAccount[]>>;
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
}

const ClientManagement: React.FC<ClientManagementProps> = ({ clients, users, setUsers, onSelectClient, onAddClient, onDeleteClient, onUpdateClient }) => {
  const [showForm, setShowForm] = useState(false);
  const [editingClient, setEditingClient] = useState<Client | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const [formData, setFormData] = useState({
    name: '', identifier: '', email: '', phone: '', type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '', taxAnexo: 'III' as TaxAnexo, status: 'active' as 'active' | 'inactive',
    initialPassword: 'axis' + Math.floor(Math.random() * 999)
  });

  const resetForm = () => {
    setFormData({
      name: '', identifier: '', email: '', phone: '', type: 'PJ', 
      annualRevenue: '', taxAnexo: 'III', status: 'active',
      initialPassword: 'axis' + Math.floor(Math.random() * 999)
    });
    setEditingClient(null); setShowForm(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingClient && clients.some(c => c.identifier === formData.identifier)) {
      alert('Erro: CNPJ já cadastrado.'); return;
    }

    setIsProcessing(true);
    const clientId = editingClient?.id || Math.random().toString(36).substr(2, 9);

    const clientData: Client = {
      id: clientId,
      name: formData.name,
      identifier: formData.identifier,
      email: formData.email,
      phone: formData.phone,
      type: formData.type,
      status: formData.status,
      createdAt: editingClient?.createdAt || new Date().toISOString().split('T')[0],
      taxAnexo: formData.taxAnexo,
      annualRevenue: parseFloat(formData.annualRevenue) || 0,
    };

    // REGRA DE VÍNCULO: Criar ou atualizar login vinculado
    if (!editingClient) {
      const newUser: UserAccount = {
        id: `USR_${Date.now()}`,
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        role: UserRole.CLIENT,
        createdAt: new Date().toISOString().split('T')[0],
        lastLogin: 'Nunca',
        status: 'active',
        passwordHash: btoa(formData.initialPassword),
        cnpjVinculado: formData.identifier
      };
      setUsers(prev => [newUser, ...prev]);
      alert(`Empresa Criada! Login de acesso: ${formData.email} / Senha: ${formData.initialPassword}`);
    } else {
      setUsers(prev => prev.map(u => u.cnpjVinculado === editingClient.identifier ? { ...u, cnpjVinculado: formData.identifier, name: formData.name } : u));
    }

    if (editingClient) onUpdateClient?.(clientData);
    else onAddClient(clientData);

    setIsProcessing(false);
    resetForm();
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Portfólio de Empresas</h2>
          <p className="text-slate-500 text-xs">Cada empresa aqui terá um login exclusivo vinculado.</p>
        </div>
        <button onClick={() => setShowForm(true)} className="px-6 py-3 bg-slate-900 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg">Cadastrar Nova Empresa</button>
      </header>

      {showForm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in duration-300">
            <h3 className="text-xl font-black text-slate-900 uppercase mb-8">Cadastro com Vínculo de Login</h3>
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <input required placeholder="Razão Social" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="p-4 border rounded-2xl bg-slate-50 font-bold" />
                <input required placeholder="CNPJ (Formato: 00.000.000/0001-00)" value={formData.identifier} onChange={(e) => setFormData({...formData, identifier: e.target.value})} className="p-4 border rounded-2xl bg-slate-50 font-bold" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <input required type="email" placeholder="E-mail do Login" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="p-4 border rounded-2xl bg-slate-50 font-bold" />
                {!editingClient && (
                  <div className="p-4 bg-blue-50 border border-blue-100 rounded-2xl flex flex-col justify-center">
                    <span className="text-[9px] font-black text-blue-400 uppercase">Senha Gerada</span>
                    <span className="text-sm font-black text-blue-900">{formData.initialPassword}</span>
                  </div>
                )}
              </div>
              <div className="grid grid-cols-2 gap-4">
                <select value={formData.taxAnexo} onChange={(e) => setFormData({...formData, taxAnexo: e.target.value as TaxAnexo})} className="p-4 border rounded-2xl bg-slate-50 font-bold">
                  <option value="I">Anexo I</option><option value="III">Anexo III</option>
                </select>
                <input type="number" placeholder="Faturamento Anual" value={formData.annualRevenue} onChange={(e) => setFormData({...formData, annualRevenue: e.target.value})} className="p-4 border rounded-2xl bg-slate-50 font-bold" />
              </div>
              <button type="submit" disabled={isProcessing} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest">
                {isProcessing ? 'Sincronizando...' : 'Confirmar e Criar Acesso'}
              </button>
              <button type="button" onClick={resetForm} className="w-full text-slate-400 font-bold uppercase text-xs">Cancelar</button>
            </form>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase border-b">
            <tr><th className="px-6 py-4">Empresa / CNPJ</th><th className="px-6 py-4">Status</th><th className="px-6 py-4 text-right">Ações</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {clients.map(client => (
              <tr key={client.id} className="hover:bg-slate-50 transition-all">
                <td className="px-6 py-5">
                  <p className="font-black text-slate-800 text-sm">{client.name}</p>
                  <p className="text-[10px] text-slate-400 font-bold">{client.identifier}</p>
                </td>
                <td className="px-6 py-4">
                  <span className={`text-[10px] font-black uppercase ${client.status === 'active' ? 'text-emerald-500' : 'text-red-500'}`}>{client.status}</span>
                </td>
                <td className="px-6 py-4 text-right">
                  <button onClick={() => onSelectClient?.(client)} className="text-[10px] font-black text-blue-600 uppercase hover:underline">Acessar Painel</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ClientManagement;

import React, { useState, useMemo, useRef } from 'react';
import { Tax, Client, UserRole } from '../types';
import { sendTaxReminderWhatsApp } from '../services/notificationService';

interface TaxTrackerProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
  clients?: Client[];
  taxes: Tax[];
  setTaxes: React.Dispatch<React.SetStateAction<Tax[]>>;
}

const TaxTracker: React.FC<TaxTrackerProps> = ({ focusedClient, userRole, clients = [], taxes, setTaxes }) => {
  const [showAddModal, setShowAddModal] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [newTax, setNewTax] = useState({ name: 'DAS - Simples Nacional', amount: '', dueDate: '', clientId: '', file: null as File | null });

  const isAdmin = userRole === UserRole.ADMIN;

  const filteredTaxes = useMemo(() => {
    return taxes.filter(tax => focusedClient ? tax.clientId === focusedClient.id : true);
  }, [taxes, focusedClient]);

  const handleAddTax = (e: React.FormEvent) => {
    e.preventDefault();
    const tax: Tax = {
      id: Math.random().toString(36).substr(2, 9),
      name: newTax.name,
      amount: parseFloat(newTax.amount),
      dueDate: newTax.dueDate,
      status: 'pending',
      clientId: focusedClient?.id || newTax.clientId,
    };
    setTaxes(prev => [tax, ...prev]);
    setShowAddModal(false);
  };

  return (
    <div className="space-y-6">
      <header className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black text-slate-800">Impostos e Guias</h2>
          <p className="text-slate-500 text-sm">{focusedClient ? `Guia exclusiva de ${focusedClient.name}` : 'Visão consolidada do escritório.'}</p>
        </div>
        {isAdmin && <button onClick={() => setShowAddModal(true)} className="px-6 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase">Nova Guia</button>}
      </header>

      {filteredTaxes.length === 0 ? (
        <div className="py-20 text-center border-2 border-dashed rounded-3xl text-slate-400 font-black uppercase text-xs">Sem guias lançadas para esta empresa.</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {filteredTaxes.map(tax => (
            <div key={tax.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
              <span className="text-[9px] font-black uppercase text-blue-600">Vencimento: {tax.dueDate}</span>
              <h3 className="font-black text-slate-800 mt-2">{tax.name}</h3>
              <p className="text-xl font-black text-slate-900 mt-1">R$ {tax.amount.toFixed(2)}</p>
            </div>
          ))}
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 shadow-2xl">
            <h3 className="text-xl font-black uppercase mb-6">Lançamento de Imposto</h3>
            <form onSubmit={handleAddTax} className="space-y-4">
              {!focusedClient && (
                <select required value={newTax.clientId} onChange={(e) => setNewTax({...newTax, clientId: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold">
                  <option value="">Selecione a Empresa</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              )}
              <input required type="number" placeholder="Valor" value={newTax.amount} onChange={(e) => setNewTax({...newTax, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
              <input required type="date" value={newTax.dueDate} onChange={(e) => setNewTax({...newTax, dueDate: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
              <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest">Publicar Guia</button>
              <button type="button" onClick={() => setShowAddModal(false)} className="w-full text-slate-400 font-bold uppercase text-xs">Fechar</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

