import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import InvoiceIssuance from './components/InvoiceIssuance';
import TaxConsultancy from './components/TaxConsultancy';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import FinancialPlanner from './components/FinancialPlanner';
import AdminUserManager from './components/AdminUserManager';
import Settings from './components/Settings';
import Login from './components/Login';
import { View, UserRole, User, Client, UserAccount, Revenue, Tax, Employee, Document } from './types';
import { deleteClientRequest } from './services/clientService';

const STORAGE_KEYS = {
  CLIENTS: 'axis_clients_v2',
  USERS: 'axis_users_v2',
  REVENUES: 'axis_revenues_v2',
  TAXES: 'axis_taxes_v2',
  EMPLOYEES: 'axis_employees_v2',
  DOCUMENTS: 'axis_docs_v2'
};

const initialClients: Client[] = [
  { id: '1', name: 'Tecnologia Avançada LTDA', identifier: '12.345.678/0001-90', email: 'contato@techavancada.com', status: 'active', type: 'PJ', createdAt: '2024-01-10', annualRevenue: 180000, taxAnexo: 'III' },
];

const initialUserAccounts: UserAccount[] = [
  { id: 'USR_ADM_NEW', name: 'Administrador Axis', email: 'adm@ad.com', phone: '(11) 99999-9999', role: UserRole.ADMIN, createdAt: '2026-01-01', lastLogin: 'Nunca', status: 'active', passwordHash: 'MTIzNDU=' },
  { id: 'USR_001', name: 'João Silva', email: 'joao@email.com', phone: '(11) 98877-6655', role: UserRole.CLIENT, createdAt: '2026-01-05', lastLogin: 'Nunca', status: 'active', passwordHash: 'MTIzNDU2', cnpjVinculado: '12.345.678/0001-90' },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    return saved ? JSON.parse(saved) : initialClients;
  });

  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.USERS);
    return saved ? JSON.parse(saved) : initialUserAccounts;
  });

  const [revenues, setRevenues] = useState<Revenue[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.REVENUES);
    return saved ? JSON.parse(saved) : [];
  });

  const [taxes, setTaxes] = useState<Tax[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAXES);
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.EMPLOYEES);
    return saved ? JSON.parse(saved) : [];
  });

  const [documents, setDocuments] = useState<Document[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(userAccounts)); }, [userAccounts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.REVENUES, JSON.stringify(revenues)); }, [revenues]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAXES, JSON.stringify(taxes)); }, [taxes]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.EMPLOYEES, JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(documents)); }, [documents]);

  const handleLogin = (email: string, pass: string) => {
    const hashed = btoa(pass);
    const account = userAccounts.find(u => u.email.toLowerCase() === email.toLowerCase() && u.passwordHash === hashed);

    if (account) {
      if (account.status !== 'active') { alert("Acesso Bloqueado."); return; }

      const user: User = { id: account.id, name: account.name, role: account.role, cnpjVinculado: account.cnpjVinculado };
      setCurrentUser(user);

      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
      }

      setCurrentView(View.DASHBOARD);
      setUserAccounts(prev => prev.map(u => u.id === account.id ? {...u, lastLogin: new Date().toLocaleString('pt-BR')} : u));
    } else {
      alert("Credenciais Inválidas.");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const renderContent = () => {
    if (!currentUser) return null;

    const commonProps = {
      focusedClient,
      userRole: currentUser.role,
      revenues, setRevenues,
      taxes, setTaxes,
      employees, setEmployees,
      documents, setDocuments,
      selectedMonthIdx, setSelectedMonthIdx,
      currentUser,
      clients,
      onSelectClient: (c: Client) => { setFocusedClient(c); setCurrentView(View.DASHBOARD); },
      onAddClient: (c: Client) => setClients(prev => [c, ...prev]),
      onDeleteClient: async (id: string) => {
        const success = await deleteClientRequest(id);
        if (success) setClients(prev => prev.filter(c => c.id !== id));
      },
      onUpdateClient: (c: Client) => setClients(prev => prev.map(old => old.id === c.id ? c : old)),
      users: userAccounts,
      setUsers: setUserAccounts
    };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.FINANCIAL_PLANNER: return <FinancialPlanner {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />
      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {/* MODO FOCO: Bloqueado para Clientes (Imutabilidade do Contexto) */}
        {currentUser.role === UserRole.ADMIN && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate">
              <span className="text-lg">👁️</span>
              <span>Monitorando: <b>{focusedClient.name}</b></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg">Ver Painel Global</button>
          </div>
        )}
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="mb-8">
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">
              {focusedClient ? `UNIDADE: ${focusedClient.identifier}` : 'CONTROLADORIA AXIS'}
            </p>
            <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useMemo } from 'react';
import { Document, Client } from '../types';

interface DocumentManagerProps {
  focusedClient?: Client | null;
  documents: Document[];
  setDocuments: React.Dispatch<React.SetStateAction<Document[]>>;
}

const DocumentManager: React.FC<DocumentManagerProps> = ({ focusedClient, documents, setDocuments }) => {
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadingFileName, setUploadingFileName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // REGRA DE OURO: Isolamento por Empresa (Mandatário)
  const filteredDocs = useMemo(() => {
    return documents.filter(doc => focusedClient ? doc.ownerId === focusedClient.id : true);
  }, [documents, focusedClient]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!focusedClient) {
      alert("Erro: Selecione uma empresa ou foque em um cliente antes do upload.");
      return;
    }

    if (e.target.files && e.target.files.length > 0) {
      const file = e.target.files[0];
      const fileSizeMB = file.size / (1024 * 1024);

      setIsUploading(true);
      setUploadProgress(0);
      setUploadingFileName(file.name);

      let progress = 0;
      const interval = setInterval(() => {
        progress += Math.random() * 20;
        if (progress >= 100) {
          progress = 100;
          setUploadProgress(100);
          clearInterval(interval);
          setTimeout(() => {
            const newDoc: Document = {
              id: `DOC_${Math.random().toString(36).substr(2, 9)}`,
              name: file.name,
              type: file.name.split('.').pop()?.toUpperCase() || 'FILE',
              uploadDate: new Date().toISOString().split('T')[0],
              size: fileSizeMB < 1 ? `${(file.size / 1024).toFixed(0)} KB` : `${fileSizeMB.toFixed(1)} MB`,
              category: 'other',
              ownerId: focusedClient.id
            };
            setDocuments(prev => [newDoc, ...prev]);
            setIsUploading(false);
            setUploadProgress(0);
            setUploadingFileName('');
          }, 500);
        } else {
          setUploadProgress(Math.floor(progress));
        }
      }, 100);
    }
  };

  const categoryLabels = { invoice: 'Nota Fiscal', contract: 'Contrato', tax_report: 'Relatório', other: 'Outros' };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-xl md:text-2xl font-black text-slate-800 tracking-tight">Gestão de Arquivos Permanentes</h2>
          <p className="text-slate-500 text-xs md:text-sm">
            {focusedClient ? `Exclusivo: ${focusedClient.name}` : 'Acesso Global do Escritório'}
          </p>
        </div>

        {focusedClient && (
          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={isUploading}
            className={`w-full md:w-auto px-8 py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all ${
              isUploading ? 'bg-slate-100 text-slate-400' : 'bg-blue-600 text-white hover:bg-blue-700'
            }`}
          >
            {isUploading ? 'Processando...' : 'Enviar Documento'}
            <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
          </button>
        )}
      </header>

      {isUploading && (
        <div className="bg-white border-2 border-blue-500/10 rounded-[2rem] p-6 shadow-2xl animate-in slide-in-from-top-4">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-black text-slate-800 text-xs truncate max-w-[200px]">{uploadingFileName}</h4>
            <span className="text-lg font-black text-blue-600">{uploadProgress}%</span>
          </div>
          <div className="relative w-full h-2.5 bg-slate-100 rounded-full overflow-hidden">
            <div className="absolute top-0 left-0 h-full bg-blue-600 transition-all duration-300" style={{ width: `${uploadProgress}%` }}></div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-widest border-b">
            <tr>
              <th className="px-6 py-5">Nome do Arquivo</th>
              <th className="px-6 py-5">Upload</th>
              <th className="px-6 py-5">Tamanho</th>
              <th className="px-6 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredDocs.length > 0 ? filteredDocs.map((doc) => (
              <tr key={doc.id} className="hover:bg-slate-50/80 transition-colors">
                <td className="px-6 py-5 flex items-center space-x-3">
                  <div className="w-10 h-10 bg-slate-50 border border-slate-100 rounded-xl flex items-center justify-center text-[8px] font-black">{doc.type}</div>
                  <span className="font-bold text-sm text-slate-800">{doc.name}</span>
                </td>
                <td className="px-6 py-5">
                  <p className="text-xs font-bold text-slate-600">{doc.uploadDate.split('-').reverse().join('/')}</p>
                </td>
                <td className="px-6 py-5">
                  <span className="text-[10px] font-black text-slate-400">{doc.size}</span>
                </td>
                <td className="px-6 py-5 text-right">
                  <button className="p-2 text-blue-600 hover:scale-110 transition-transform">⬇️</button>
                </td>
              </tr>
            )) : (
              <tr><td colSpan={4} className="py-20 text-center text-slate-300 font-black uppercase text-xs">Nenhum documento nesta empresa.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default DocumentManager;

import React, { useState, useMemo } from 'react';
import { Revenue, Client, User } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
  selectedMonthIdx: number;
  setSelectedMonthIdx: (idx: number) => void;
  currentUser: User | null;
}

const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues, selectedMonthIdx, setSelectedMonthIdx, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    client: '', amount: '', date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    description: ''
  });

  // ISOLAMENTO DE DADOS (Mandatário)
  const filteredByClient = useMemo(() => {
    return focusedClient ? revenues.filter(r => r.clientId === focusedClient.id) : [];
  }, [revenues, focusedClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      return m === selectedMonthIdx && 
             (rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
              rev.description?.toLowerCase().includes(searchTerm.toLowerCase()));
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!focusedClient) { alert("Erro: Contexto de empresa não definido."); return; }

    if (editingId) {
      setRevenues(prev => prev.map(r => r.id === editingId ? {
        ...r,
        client: formData.client,
        amount: parseFloat(formData.amount),
        date: formData.date,
        status: formData.status,
        entryType: formData.entryType,
        description: formData.description,
      } : r));
    } else {
      const newRev: Revenue = {
        id: `REV_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
        client: formData.client,
        amount: parseFloat(formData.amount),
        date: formData.date,
        status: formData.status,
        entryType: formData.entryType,
        description: formData.description,
        source: 'manual',
        clientId: focusedClient.id,
        createdBy: currentUser?.id
      };
      setRevenues(prev => [newRev, ...prev]);
    }
    setShowModal(false);
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      <header className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Memória Financeira</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Extrato Histórico</h2>
        </div>
        <button 
          onClick={() => { setEditingId(null); setShowModal(true); }}
          className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl"
        >
          Novo Lançamento
        </button>
      </header>

      <div className="grid grid-cols-4 md:grid-cols-12 gap-2">
        {months.map((m, idx) => (
          <button
            key={m}
            onClick={() => setSelectedMonthIdx(idx)}
            className={`py-3 rounded-xl text-[10px] font-black uppercase transition-all ${
              selectedMonthIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100'
            }`}
          >
            {m.substring(0, 3)}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b">
            <tr>
              <th className="px-8 py-5">Data</th>
              <th className="px-8 py-5">Descrição</th>
              <th className="px-8 py-5 text-right">Valor</th>
              <th className="px-8 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredRevenues.length > 0 ? filteredRevenues.map(rev => (
              <tr key={rev.id} className="hover:bg-slate-50/50 transition-colors">
                <td className="px-8 py-5 font-black text-slate-600 text-xs">{rev.date.split('-').reverse().join('/')}</td>
                <td className="px-8 py-5">
                  <p className="font-bold text-slate-800 text-sm">{rev.client}</p>
                  <p className="text-[10px] text-slate-400">{rev.description}</p>
                </td>
                <td className={`px-8 py-5 text-right font-black ${rev.entryType === 'inflow' ? 'text-emerald-600' : 'text-red-600'}`}>
                  {rev.entryType === 'inflow' ? '+' : '-'} {fmt(rev.amount)}
                </td>
                <td className="px-8 py-5 text-right">
                  <button onClick={() => setRevenues(prev => prev.filter(r => r.id !== rev.id))} className="text-red-400 hover:text-red-600 text-xs font-black">EXCLUIR</button>
                </td>
              </tr>
            )) : (
              <tr><td colSpan={4} className="py-20 text-center text-slate-300 font-black uppercase text-xs">Sem registros permanentemente salvos neste mês.</td></tr>
            )}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] p-10 shadow-2xl space-y-6">
            <h3 className="text-xl font-black text-slate-900 uppercase">Novo Registro Permanente</h3>
            <form onSubmit={handleSave} className="space-y-4">
               <div className="grid grid-cols-2 gap-4">
                 <input required placeholder="Descrição" value={formData.client} onChange={e => setFormData({...formData, client: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                 <input required type="number" placeholder="Valor" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
               </div>
               <div className="grid grid-cols-2 gap-4">
                 <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                 <select value={formData.entryType} onChange={e => setFormData({...formData, entryType: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold">
                    <option value="inflow">Entrada</option>
                    <option value="outflow">Saída</option>
                 </select>
               </div>
               <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase">Salvar no Histórico</button>
               <button type="button" onClick={() => setShowModal(false)} className="w-full text-slate-400 font-black uppercase text-xs">Cancelar</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default RevenueSchedule;

