import React, { useState, useMemo } from 'react';
import { Client, TaxAnexo, SimplesCalculationResult } from '../types';
import { calculateSimplesNacional } from '../services/taxCalculator';

interface SimplesCalculatorProps {
  focusedClient?: Client | null;
  onSaveCalculation: (res: SimplesCalculationResult) => void;
  history: SimplesCalculationResult[];
}

const SimplesCalculator: React.FC<SimplesCalculatorProps> = ({ focusedClient, onSaveCalculation, history }) => {
  const [mode, setMode] = useState<'FISCAL' | 'OPERATION'>('FISCAL');
  const [rbt12, setRbt12] = useState<number>(focusedClient?.annualRevenue || 180000);
  const [monthlyRevenue, setMonthlyRevenue] = useState<number>(0);
  const [saleValue, setSaleValue] = useState<number>(0);
  const [productCost, setProductCost] = useState<number>(0);
  const [otherCosts, setOtherCosts] = useState<number>(0);
  const [payroll, setPayroll] = useState<number>(0);
  const [anexo, setAnexo] = useState<TaxAnexo>(focusedClient?.taxAnexo || 'III');
  const [activity, setActivity] = useState<'SERVICO' | 'COMERCIO' | 'INDUSTRIA'>('SERVICO');

  const result = useMemo(() => {
    let activeAnexo = anexo;
    let fatorR = 0;

    if (activity === 'SERVICO' && (anexo === 'III' || anexo === 'V')) {
      fatorR = rbt12 > 0 ? payroll / rbt12 : 0;
      activeAnexo = fatorR >= 0.28 ? 'III' : 'V';
    }

    const currentAmount = mode === 'FISCAL' ? monthlyRevenue : saleValue;
    const calc = calculateSimplesNacional(rbt12, currentAmount, activeAnexo);

    // Cálculos de Rentabilidade para o Modo Operação
    let profitability = undefined;
    if (mode === 'OPERATION') {
      const totalDirectCosts = productCost + otherCosts;
      const grossProfit = saleValue - totalDirectCosts;
      const netProfit = saleValue - totalDirectCosts - calc.taxAmount;
      const grossMargin = saleValue > 0 ? (grossProfit / saleValue) * 100 : 0;
      const netMargin = saleValue > 0 ? (netProfit / saleValue) * 100 : 0;

      profitability = {
        grossProfit,
        netProfit,
        grossMargin,
        netMargin
      };
    }

    return { ...calc, fatorR, profitability };
  }, [rbt12, monthlyRevenue, saleValue, productCost, otherCosts, payroll, anexo, activity, mode]);

  const handleSave = () => {
    const newCalc: SimplesCalculationResult = {
