                <p className="text-xl font-black text-slate-900">Faixa {result.bracketIndex}</p>
              </div>
            </header>

            {mode === 'OPERATION' && result.profitability && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 p-8 bg-slate-900 rounded-[2rem] text-white">
                <div>
                   <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Lucro Líquido Real</p>
                   <p className={`text-4xl font-black ${result.profitability.netProfit >= 0 ? 'text-emerald-400' : 'text-red-400'}`}>
                    {fmt(result.profitability.netProfit)}
                   </p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Margem Líquida</p>
                    <p className="text-xl font-black">{result.profitability.netMargin.toFixed(1)}%</p>
                  </div>
                  <div>
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Peso Imposto</p>
                    <p className="text-xl font-black text-blue-400">{(result.effectiveRate * 100).toFixed(1)}%</p>
                  </div>
                </div>
              </div>
            )}

            <div className="space-y-6">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b pb-2 flex justify-between">
                <span>Detalhamento Tributário da Operação</span>
                <span className="text-blue-500">Anexo {result.appliedAnexo}</span>
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-4">
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                   <div className="flex flex-col">
                     <span className="text-xs font-black text-slate-800">IRPJ</span>
                     <span className="text-[8px] text-slate-400 uppercase font-bold">Imposto de Renda PJ</span>
                   </div>
                   <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.irpj)}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                   <div className="flex flex-col">
                     <span className="text-xs font-black text-slate-800">CSLL</span>
                     <span className="text-[8px] text-slate-400 uppercase font-bold">Contr. Social Lucro Líquido</span>
                   </div>
                   <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.csll)}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                   <div className="flex flex-col">
                     <span className="text-xs font-black text-slate-800">COFINS</span>
                     <span className="text-[8px] text-slate-400 uppercase font-bold">Contrib. Seguridade Social</span>
                   </div>
                   <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.cofins)}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                   <div className="flex flex-col">
                     <span className="text-xs font-black text-slate-800">PIS/PASEP</span>
                     <span className="text-[8px] text-slate-400 uppercase font-bold">Programa Integração Social</span>
                   </div>
                   <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.pis)}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-slate-50">
                   <div className="flex flex-col">
                     <span className="text-xs font-black text-slate-800">CPP</span>
                     <span className="text-[8px] text-slate-400 uppercase font-bold">Contr. Previdenciária Patronal</span>
                   </div>
                   <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.cpp)}</span>
                </div>
                {result.breakdown.iss !== undefined && (
                  <div className="flex justify-between items-center py-2 border-b border-slate-50">
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-slate-800">ISS</span>
                      <span className="text-[8px] text-slate-400 uppercase font-bold">Imposto s/ Serviços</span>
                    </div>
                    <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.iss)}</span>
                  </div>
                )}
                {result.breakdown.icms !== undefined && (
                  <div className="flex justify-between items-center py-2 border-b border-slate-50">
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-slate-800">ICMS</span>
                      <span className="text-[8px] text-slate-400 uppercase font-bold">Imposto s/ Circulação</span>
                    </div>
                    <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.icms)}</span>
                  </div>
                )}
                {result.breakdown.ipi !== undefined && (
                  <div className="flex justify-between items-center py-2 border-b border-slate-50">
                    <div className="flex flex-col">
                      <span className="text-xs font-black text-slate-800">IPI</span>
                      <span className="text-[8px] text-slate-400 uppercase font-bold">Prod. Industrializados</span>
                    </div>
                    <span className="text-sm font-black text-slate-800">{fmt(result.breakdown.ipi)}</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Histórico de Cálculos Gravados</h3>
            <div className="space-y-3">
              {history.length > 0 ? history.map(h => (
                <div key={h.id} className="p-5 border border-slate-50 bg-slate-50/50 rounded-2xl flex justify-between items-center hover:bg-white transition-all group">
                  <div className="flex items-center space-x-4">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-xs font-black ${h.type === 'FISCAL' ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>
                      {h.type === 'FISCAL' ? 'Mês' : 'Venda'}
                    </div>
                    <div>
                      <p className="text-sm font-black text-slate-800">{fmt(h.amount)}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">{new Date(h.date).toLocaleDateString()} • Anexo {h.anexo}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-black text-blue-600">-{fmt(h.taxAmount)}</p>
                    {h.profitability && (
                       <p className="text-[9px] text-emerald-500 font-black">Lucro: {fmt(h.profitability.netProfit)} ({h.profitability.netMargin.toFixed(1)}%)</p>
                    )}
                  </div>
                </div>
              )) : (
                <p className="text-[10px] text-slate-300 font-black uppercase py-8 text-center italic">Aguardando novos cálculos operacionais.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

