  { id: 'USR_ADM_NEW', name: 'Administrador Axis', email: 'adm@ad.com', phone: '(11) 99999-9999', role: UserRole.ADMIN, createdAt: '2026-01-01', lastLogin: 'Nunca', status: 'active', passwordHash: 'MTIzNDU=' },
  { id: 'USR_001', name: 'João Silva', email: 'joao@email.com', phone: '(11) 98877-6655', role: UserRole.CLIENT, createdAt: '2026-01-05', lastLogin: 'Nunca', status: 'active', passwordHash: 'MTIzNDU2', cnpjVinculado: '12.345.678/0001-90' },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    return saved ? JSON.parse(saved) : initialClients;
  });

  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.USERS);
    return saved ? JSON.parse(saved) : initialUserAccounts;
  });

  const [revenues, setRevenues] = useState<Revenue[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.REVENUES);
    return saved ? JSON.parse(saved) : [];
  });

  const [taxes, setTaxes] = useState<Tax[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAXES);
    return saved ? JSON.parse(saved) : [];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.EMPLOYEES);
    return saved ? JSON.parse(saved) : [];
  });

  const [documents, setDocuments] = useState<Document[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
    return saved ? JSON.parse(saved) : [];
  });

  const [simplesHistory, setSimplesHistory] = useState<SimplesCalculationResult[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.SIMPLES_HISTORY);
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(userAccounts)); }, [userAccounts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.REVENUES, JSON.stringify(revenues)); }, [revenues]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAXES, JSON.stringify(taxes)); }, [taxes]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.EMPLOYEES, JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(documents)); }, [documents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.SIMPLES_HISTORY, JSON.stringify(simplesHistory)); }, [simplesHistory]);

  const handleLogin = (email: string, pass: string) => {
    const hashed = btoa(pass);
    const account = userAccounts.find(u => u.email.toLowerCase() === email.toLowerCase() && u.passwordHash === hashed);

    if (account) {
      if (account.status !== 'active') { alert("Acesso Bloqueado."); return; }
      const user: User = { 
        id: account.id, 
        name: account.name, 
        email: account.email, // Importante para validação estrita
        role: account.role, 
        cnpjVinculado: account.cnpjVinculado 
      };
      setCurrentUser(user);
      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
      }
      setCurrentView(View.DASHBOARD);
      setUserAccounts(prev => prev.map(u => u.id === account.id ? {...u, lastLogin: new Date().toLocaleString('pt-BR')} : u));
    } else {
      alert("Credenciais Inválidas.");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setCurrentView(View.DASHBOARD);
    setFocusedClient(null);
  };

  const renderContent = () => {
    if (!currentUser) return null;

    const commonProps = {
      focusedClient,
      userRole: currentUser.role,
      revenues, setRevenues,
      taxes, setTaxes,
      employees, setEmployees,
      documents, setDocuments,
      selectedMonthIdx, setSelectedMonthIdx,
      currentUser,
      clients,
      onSelectClient: (c: Client) => { setFocusedClient(c); setCurrentView(View.DASHBOARD); },
      onAddClient: (c: Client) => setClients(prev => [c, ...prev]),
      onDeleteClient: async (id: string) => {
        // REGRA DE OURO: Apenas o e-mail administrativo definido pode executar a exclusão
        if (currentUser.email.toLowerCase() !== ADMIN_EMAIL_AUTH) {
          alert("ERRO DE SEGURANÇA: Ação restrita ao administrador mestre (adm@ad.com).");
          return;
        }

        const clientToDelete = clients.find(c => c.id === id);
        if (!clientToDelete) return;

        const success = await deleteClientRequest(id);
        if (success) {
          // Limpeza total de vínculos (Física e Lógica)
          setClients(prev => prev.filter(c => c.id !== id));
          setUserAccounts(prev => prev.filter(u => u.cnpjVinculado !== clientToDelete.identifier));
          setRevenues(prev => prev.filter(r => r.clientId !== id));
          setTaxes(prev => prev.filter(t => t.clientId !== id));
          setDocuments(prev => prev.filter(d => d.ownerId !== id));
          setSimplesHistory(prev => prev.filter(h => h.clientId !== id));

          if (focusedClient?.id === id) setFocusedClient(null);
          alert(`EXCLUSÃO CONCLUÍDA: A empresa "${clientToDelete.nomeFantasia}" e todos os registros associados foram removidos pelo ADM.`);
        }
      },
      onUpdateClient: (c: Client) => setClients(prev => prev.map(old => old.id === c.id ? c : old)),
      users: userAccounts,
      setUsers: setUserAccounts
    };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.FINANCIAL_PLANNER: return <FinancialPlanner {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.TAX_CONSULTANCY: return <TaxConsultancy {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      case View.SIMPLES_CALCULATOR: 
        return (
          <SimplesCalculator 
            focusedClient={focusedClient} 
            onSaveCalculation={(res) => setSimplesHistory(prev => [res, ...prev])}
            history={simplesHistory.filter(h => focusedClient ? h.clientId === focusedClient.id : true)}
          />
        );
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans overflow-x-hidden">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={handleLogout} hasActiveFocus={!!focusedClient}
      />
      <main className={`flex-1 transition-all duration-300 ease-in-out w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        {(currentUser.email === ADMIN_EMAIL_AUTH) && focusedClient && (
          <div className="sticky top-0 z-40 bg-amber-500 text-amber-950 px-4 md:px-6 py-2 flex items-center justify-between shadow-md">
            <div className="flex items-center space-x-2 text-[10px] md:text-xs font-bold uppercase truncate">
              <span className="text-lg">🛡️</span>
              <span>ADMIN MODE: Monitorando <b>{focusedClient.name}</b></span>
            </div>
            <button onClick={() => setFocusedClient(null)} className="text-[10px] font-black uppercase bg-white/20 hover:bg-white/40 px-3 py-1 rounded-lg">Voltar ao Global</button>
          </div>
        )}
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          <header className="mb-8">
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">
              {focusedClient ? `UNIDADE: ${focusedClient.identifier}` : 'CONTROLADORIA AXIS'}
            </p>
            <h1 className="text-xl md:text-2xl font-bold text-slate-800 capitalize tracking-tight">{currentView.replace(/_/g, ' ')}</h1>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Client, TaxAnexo, UserAccount, UserRole, User } from '../types';

interface ClientManagementProps {
  clients: Client[];
  users: UserAccount[];
  setUsers: React.Dispatch<React.SetStateAction<UserAccount[]>>;
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
  currentUser?: User | null;
}

const ADMIN_EMAIL_AUTH = 'adm@ad.com';

const ClientManagement: React.FC<ClientManagementProps> = ({ 
  clients, 
  users, 
  setUsers, 
  onSelectClient, 
  onAddClient, 
  onDeleteClient, 
  onUpdateClient,
  currentUser
}) => {
  const [showForm, setShowForm] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const [formData, setFormData] = useState({
    name: '', 
    nomeFantasia: '',
    nomeEmpresario: '',
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '', 
    taxAnexo: 'III' as TaxAnexo, 
    status: 'active' as 'active' | 'inactive',
    initialPassword: 'axis' + Math.floor(1000 + Math.random() * 9000)
  });

  const resetForm = () => {
    setFormData({
      name: '', nomeFantasia: '', nomeEmpresario: '', identifier: '', email: '', phone: '', type: 'PJ', 
      annualRevenue: '', taxAnexo: 'III', status: 'active',
      initialPassword: 'axis' + Math.floor(1000 + Math.random() * 9000)
    });
    setShowForm(false);
  };

  const isMasterAdmin = currentUser?.email.toLowerCase() === ADMIN_EMAIL_AUTH;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (clients.some(c => c.identifier === formData.identifier)) {
      alert('Erro: Este CNPJ já possui uma empresa e um login vinculados.'); return;
    }

    setIsProcessing(true);
    const clientId = `CLI_${Date.now()}`;

    const clientData: Client = {
      id: clientId,
      name: formData.name,
      nomeFantasia: formData.nomeFantasia,
      nomeEmpresario: formData.nomeEmpresario,
      identifier: formData.identifier,
      email: formData.email,
      phone: formData.phone,
      type: formData.type,
      status: formData.status,
      createdAt: new Date().toISOString().split('T')[0],
      taxAnexo: formData.taxAnexo,
      annualRevenue: parseFloat(formData.annualRevenue) || 0,
    };

    const newUser: UserAccount = {
      id: `USR_${Date.now()}`,
      name: formData.nomeEmpresario,
      email: formData.email,
      phone: formData.phone,
      role: UserRole.CLIENT,
      createdAt: new Date().toISOString().split('T')[0],
      lastLogin: 'Nunca',
      status: 'active',
      passwordHash: btoa(formData.initialPassword),
      cnpjVinculado: formData.identifier
    };

    setUsers(prev => [newUser, ...prev]);
    onAddClient(clientData);

    alert(`SUCESSO!\nEmpresa: ${formData.nomeFantasia}\nLogin: ${formData.email}\nSenha Inicial: ${formData.initialPassword}\n\nO vínculo CNPJ ↔ Login foi estabelecido.`);

    setIsProcessing(false);
    resetForm();
  };

  const handleDeleteRequest = (client: Client) => {
    // Validação estrita por e-mail no ato do clique
    if (!isMasterAdmin) {
      alert("ACESSO NEGADO: Apenas o administrador mestre (adm@ad.com) pode excluir empresas.");
      return;
    }

    const confirmation = window.confirm(
      `⚠️ ATENÇÃO: ESTA AÇÃO É IRREVERSÍVEL.\n\nDeseja realmente excluir a empresa "${client.nomeFantasia}"?\n\nIsso removerá permanentemente:\n- Registro da Empresa\n- Login de Acesso (CNPJ: ${client.identifier})\n- Todo o histórico financeiro e documentos.`
    );

    if (confirmation) {
      onDeleteClient(client.id);
    }
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Gestão de Empresas</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Controle Central de Unidades</p>
        </div>
        <button onClick={() => setShowForm(true)} className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all">
          Nova Empresa + Login
        </button>
      </header>

      {showForm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl p-10 overflow-y-auto max-h-[90vh] animate-in zoom-in duration-300">
            <div className="flex justify-between items-start mb-8">
               <div>
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Cadastro Unificado</h3>
                  <p className="text-slate-500 text-xs font-bold uppercase">Empresa, Empresário e Credenciais</p>
               </div>
               <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full">✕</button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Razão Social</label>
                  <input required placeholder="Ex: Tecnologia LTDA" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:bg-white" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nome Fantasia</label>
                  <input required placeholder="Ex: Axis Tech" value={formData.nomeFantasia} onChange={(e) => setFormData({...formData, nomeFantasia: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:bg-white" />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nome do Empresário</label>
                  <input required placeholder="Responsável Legal" value={formData.nomeEmpresario} onChange={(e) => setFormData({...formData, nomeEmpresario: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:bg-white" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">CNPJ da Empresa</label>
                  <input required placeholder="00.000.000/0001-00" value={formData.identifier} onChange={(e) => setFormData({...formData, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none focus:bg-white" />
                </div>
              </div>

              <div className="p-6 bg-blue-50 rounded-3xl border border-blue-100 space-y-4">
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Acesso do Cliente</p>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-blue-400 uppercase tracking-widest ml-1">E-mail de Login</label>
                    <input required type="email" placeholder="acesso@empresa.com" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="w-full p-4 border border-blue-200 rounded-2xl bg-white font-bold" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-blue-400 uppercase tracking-widest ml-1">Senha Inicial</label>
                    <div className="p-4 bg-white border border-blue-200 rounded-2xl font-black text-blue-700 text-center uppercase tracking-widest">
                      {formData.initialPassword}
                    </div>
                  </div>
                </div>
              </div>

              <button type="submit" disabled={isProcessing} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-[0.2em] shadow-xl shadow-blue-500/20 hover:bg-blue-700 active:scale-[0.98] transition-all">
                {isProcessing ? 'Sincronizando...' : 'Confirmar Registro'}
              </button>
            </form>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase border-b">
            <tr>
              <th className="px-8 py-5">Empresa / Responsável</th>
              <th className="px-8 py-5">CNPJ Vinculado</th>
              <th className="px-8 py-5">Login de Acesso</th>
              <th className="px-8 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {clients.map(client => (
              <tr key={client.id} className="hover:bg-slate-50/50 transition-all group">
                <td className="px-8 py-6">
                  <p className="font-black text-slate-800 text-sm">{client.nomeFantasia}</p>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">{client.nomeEmpresario}</p>
                </td>
                <td className="px-8 py-6">
                  <span className="text-xs font-black text-slate-600 font-mono bg-slate-100 px-3 py-1 rounded-lg">{client.identifier}</span>
                </td>
                <td className="px-8 py-6">
                  <p className="text-xs font-bold text-slate-500">{client.email}</p>
                </td>
                <td className="px-8 py-6 text-right">
                  <div className="flex justify-end items-center space-x-2">
