export const calculateSimplesNacional = (rbt12: number, monthlyRevenue: number, selectedAnexo: TaxAnexo) => {
  const table = TABLES[selectedAnexo];
  const bracketIndex = table.findIndex(b => rbt12 <= b.limit);
  const bracket = bracketIndex !== -1 ? table[bracketIndex] : table[table.length - 1];

  let effectiveRate = 0;
  if (rbt12 <= 180000) {
    effectiveRate = bracket.nominalRate;
  } else {
    effectiveRate = ((rbt12 * bracket.nominalRate) - bracket.deduction) / rbt12;
  }

  effectiveRate = Math.max(0, effectiveRate);
  const taxAmount = monthlyRevenue * effectiveRate;
  const repartition = bracket.repartition;

  return {
    effectiveRate,
    nominalRate: bracket.nominalRate,
    deduction: bracket.deduction,
    taxAmount,
    bracketLimit: bracket.limit,
    bracketIndex: (bracketIndex !== -1 ? bracketIndex : table.length - 1) + 1,
    appliedAnexo: selectedAnexo
  };
};

/**
 * Novo Motor de Lucro Presumido - Suporta receitas mistas e isenções
 */
export const calculateLucroPresumidoAdvanced = (revenues: Revenue[]) => {
  let totals = {
    commerce: 0,
    service: 0,
    commerceExempt: 0, // Isento PIS/COFINS
    serviceExempt: 0,
    totalGross: 0
  };

  revenues.forEach(r => {
    if (r.entryType !== 'inflow') return;
    totals.totalGross += r.amount;

    if (r.activityType === 'commerce') {
      totals.commerce += r.amount;
      if (r.isPisCofinsExempt) totals.commerceExempt += r.amount;
    } else {
      totals.service += r.amount;
      if (r.isPisCofinsExempt) totals.serviceExempt += r.amount;
    }
  });

  // 1. Presunção
  const irpjBase = (totals.commerce * 0.08) + (totals.service * 0.32);
  const csllBase = (totals.commerce * 0.12) + (totals.service * 0.32);

  // 2. IRPJ (15% + 10% adicional sobre > 20k/mês)
  let irpj = irpjBase * 0.15;
  if (irpjBase > 20000) irpj += (irpjBase - 20000) * 0.10;

  // 3. CSLL (9%)
  const csll = csllBase * 0.09;

  // 4. PIS/COFINS (Zera onde for isento)
  const pisBase = totals.totalGross - totals.commerceExempt - totals.serviceExempt;
  const pis = pisBase * 0.0065;
  const cofins = pisBase * 0.03;

  // 5. ISS/ICMS (Estimados)
  const iss = totals.service * 0.05;
  const icms = totals.commerce * 0.18;

  const total = irpj + csll + pis + cofins + iss + icms;

  return {
    irpj, csll, pis, cofins, iss, icms, total,
    effectiveRate: totals.totalGross > 0 ? total / totals.totalGross : 0
  };
};

import React, { useState, useMemo } from 'react';
import { Revenue, Client, User } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
  selectedMonthIdx: number;
  setSelectedMonthIdx: (idx: number) => void;
  currentUser: User | null;
}

const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues, selectedMonthIdx, setSelectedMonthIdx, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState({
    client: '', 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    activityType: 'service' as 'service' | 'commerce',
    isPisCofinsExempt: false,
    description: ''
  });

  const filteredByClient = useMemo(() => {
    return focusedClient ? revenues.filter(r => r.clientId === focusedClient.id) : [];
  }, [revenues, focusedClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      return m === selectedMonthIdx && 
             (rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
              rev.description?.toLowerCase().includes(searchTerm.toLowerCase()));
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm]);

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!focusedClient) { alert("Erro: Selecione uma empresa."); return; }

    const revenueData: Revenue = {
      id: editingId || `REV_${Date.now()}`,
      client: formData.client,
      amount: parseFloat(formData.amount),
      date: formData.date,
      status: formData.status,
      entryType: formData.entryType,
      activityType: formData.activityType,
      isPisCofinsExempt: formData.isPisCofinsExempt,
      description: formData.description,
      source: 'manual',
      clientId: focusedClient.id,
      createdBy: currentUser?.id
    };

    if (editingId) {
      setRevenues(prev => prev.map(r => r.id === editingId ? revenueData : r));
    } else {
      setRevenues(prev => [revenueData, ...prev]);
    }
    setShowModal(false);
