                  <input type="checkbox" id="pisExempt" checked={formData.isPisCofinsExempt} onChange={e => setFormData({...formData, isPisCofinsExempt: e.target.checked})} className="w-5 h-5" />
                  <label htmlFor="pisExempt" className="text-xs font-black text-amber-700 uppercase">Produto com PIS/COFINS Zerado (Alíquota Zero)</label>
