      )}
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Client, Revenue } from '../types';
import { calculateSimplesNacional, calculateLucroPresumidoAdvanced } from '../services/taxCalculator';
import { GoogleGenAI } from "@google/genai";

interface IntelligentTaxManagerProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  selectedMonthIdx: number;
}

const IntelligentTaxManager: React.FC<IntelligentTaxManagerProps> = ({ focusedClient, revenues, selectedMonthIdx }) => {
  const [aiInsight, setAiInsight] = useState('');
  const [loading, setLoading] = useState(false);

  const monthRevenues = useMemo(() => {
    return revenues.filter(r => {
      const d = new Date(r.date);
      return focusedClient 
        ? r.clientId === focusedClient.id && d.getMonth() === selectedMonthIdx && r.entryType === 'inflow'
        : d.getMonth() === selectedMonthIdx && r.entryType === 'inflow';
    });
  }, [revenues, focusedClient, selectedMonthIdx]);

  const totalInvoiced = monthRevenues.reduce((acc, r) => acc + r.amount, 0);
  const rbt12 = focusedClient?.annualRevenue || 0;

  const comparison = useMemo(() => {
    const simples = calculateSimplesNacional(rbt12, totalInvoiced, focusedClient?.taxAnexo || 'III');
    const presumido = calculateLucroPresumidoAdvanced(monthRevenues);

    const economy = Math.abs(simples.taxAmount - presumido.total);
    const winner = simples.taxAmount < presumido.total ? 'Simples Nacional' : 'Lucro Presumido';
    const scoreDiff = winner === 'Lucro Presumido' ? 8 : 0;

    return { simples, presumido, economy, winner, score: 78 + scoreDiff };
  }, [monthRevenues, totalInvoiced, rbt12, focusedClient]);

  const getAiAdvice = async () => {
    setLoading(true);
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      Compare estes regimes fiscais para o cliente:
      - Simples Nacional: ${comparison.simples.taxAmount.toFixed(2)} (${(comparison.simples.effectiveRate * 100).toFixed(2)}%)
      - Lucro Presumido: ${comparison.presumido.total.toFixed(2)} (${(comparison.presumido.effectiveRate * 100).toFixed(2)}%)
      - Receita Total: ${totalInvoiced.toFixed(2)}

      Atividade identificada no extrato: ${monthRevenues.some(r => r.activityType === 'commerce') ? 'Comércio' : ''} ${monthRevenues.some(r => r.activityType === 'service') ? 'Serviços' : ''}.
      Itens com PIS/COFINS Zero: ${monthRevenues.filter(r => r.isPisCofinsExempt).length} itens.

      Dê um conselho curto em Português sobre economia tributária.
    `;

    try {
      const response = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: prompt });
      setAiInsight(response.text || '');
    } catch (e) {
      setAiInsight('Não foi possível gerar a análise no momento.');
    } finally {
      setLoading(false);
    }
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="flex flex-col md:flex-row justify-between items-center gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">IA Fiscal Desbloqueada</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Gestão Fiscal Inteligente</h2>
          <p className="text-slate-500 text-sm">Otimização automática baseada em regime comparado.</p>
        </div>
        <div className="flex items-center space-x-6">
           <div className="text-right">
             <p className="text-[9px] font-black text-slate-400 uppercase">Score de Saúde Fiscal</p>
             <p className={`text-3xl font-black ${comparison.score > 80 ? 'text-emerald-500' : 'text-blue-500'}`}>{comparison.score}/100</p>
           </div>
           <div className="w-16 h-16 rounded-3xl bg-slate-900 flex items-center justify-center text-white text-2xl shadow-xl">📊</div>
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Regime Simples */}
        <div className={`p-8 rounded-[2.5rem] border-4 transition-all ${comparison.winner === 'Simples Nacional' ? 'bg-white border-blue-500' : 'bg-slate-50 border-transparent opacity-60'}`}>
           <div className="flex justify-between items-start mb-6">
              <h3 className="text-xl font-black text-slate-800">Simples Nacional</h3>
              {comparison.winner === 'Simples Nacional' && <span className="bg-blue-600 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase">Melhor Escolha</span>}
           </div>
           <div className="space-y-4">
              <p className="text-4xl font-black text-slate-900">{fmt(comparison.simples.taxAmount)}</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Alíquota Efetiva: {(comparison.simples.effectiveRate * 100).toFixed(2)}%</p>
           </div>
        </div>

        {/* Regime Presumido */}
        <div className={`p-8 rounded-[2.5rem] border-4 transition-all ${comparison.winner === 'Lucro Presumido' ? 'bg-white border-emerald-500 shadow-2xl' : 'bg-slate-50 border-transparent opacity-60'}`}>
           <div className="flex justify-between items-start mb-6">
              <h3 className="text-xl font-black text-slate-800">Lucro Presumido</h3>
              {comparison.winner === 'Lucro Presumido' && <span className="bg-emerald-600 text-white text-[9px] font-black px-3 py-1 rounded-full uppercase">Economia Detectada</span>}
           </div>
           <div className="space-y-4">
              <p className="text-4xl font-black text-slate-900">{fmt(comparison.presumido.total)}</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Alíquota Efetiva: {(comparison.presumido.effectiveRate * 100).toFixed(2)}%</p>
           </div>
        </div>
      </div>

      {comparison.winner === 'Lucro Presumido' && (
        <div className="p-6 bg-emerald-50 border border-emerald-100 rounded-3xl flex items-center justify-between">
           <div className="flex items-center space-x-4">
             <div className="text-3xl">🚀</div>
             <div>
               <p className="text-[10px] font-black text-emerald-600 uppercase">Oportunidade de Migração</p>
               <h4 className="text-lg font-black text-emerald-900">Economia estimada de {fmt(comparison.economy)} este mês.</h4>
             </div>
           </div>
           <button onClick={getAiAdvice} className="px-6 py-3 bg-emerald-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-xl">Simular Troca</button>
        </div>
      )}

      <div className="bg-slate-900 rounded-[3rem] p-10 text-white relative overflow-hidden shadow-2xl">
         <div className="flex items-center space-x-4 mb-8">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-2xl">🤖</div>
            <div>
              <h3 className="font-black text-xl">Axis AI: Consultor Fiscal</h3>
              <p className="text-[9px] font-black text-blue-400 uppercase tracking-widest">Análise de Malha e Economia</p>
            </div>
         </div>
         <div className="text-slate-400 leading-relaxed text-sm min-h-[100px] border-l-2 border-blue-500 pl-6">
            {loading ? 'A IA está calculando o melhor cenário...' : aiInsight || 'Aguardando solicitação de análise profunda.'}
         </div>
         {totalInvoiced > 0 && !aiInsight && (
            <button onClick={getAiAdvice} className="mt-8 px-10 py-4 bg-white text-slate-900 rounded-2xl font-black text-[10px] uppercase tracking-widest">Analisar Faturamento Agora</button>
         )}
      </div>
    </div>
  );
};

