export const calculateSimplesNacional = (rbt12: number, monthlyRevenue: number, selectedAnexo: TaxAnexo) => {
  const table = TABLES[selectedAnexo];
  const bracketIndex = table.findIndex(b => rbt12 <= b.limit);
  const bracket = bracketIndex !== -1 ? table[bracketIndex] : table[table.length - 1];

  let effectiveRate = 0;
  if (rbt12 <= 180000) {
    effectiveRate = bracket.nominalRate;
  } else {
    effectiveRate = ((rbt12 * bracket.nominalRate) - bracket.deduction) / rbt12;
  }

  effectiveRate = Math.max(0, effectiveRate);
  const taxAmount = monthlyRevenue * effectiveRate;
  const repartition = bracket.repartition;

  const breakdown = {
    irpj: taxAmount * repartition.irpj,
    csll: taxAmount * repartition.csll,
    pis: taxAmount * repartition.pis,
    cofins: taxAmount * repartition.cofins,
    cpp: taxAmount * repartition.cpp,
    icms: repartition.icms ? taxAmount * repartition.icms : 0,
    iss: repartition.iss ? taxAmount * repartition.iss : 0,
    ipi: repartition.ipi ? taxAmount * repartition.ipi : 0,
  };

  return {
    effectiveRate,
    nominalRate: bracket.nominalRate,
    deduction: bracket.deduction,
    taxAmount,
    bracketLimit: bracket.limit,
    bracketIndex: (bracketIndex !== -1 ? bracketIndex : table.length - 1) + 1,
    appliedAnexo: selectedAnexo,
    breakdown
  };
};

/**
 * Novo Motor de Lucro Presumido - Suporta receitas mistas e isenções
 */
export const calculateLucroPresumidoAdvanced = (revenues: Revenue[]) => {
  let totals = {
    commerce: 0,
    service: 0,
    commerceExempt: 0, // Isento PIS/COFINS
    serviceExempt: 0,
    totalGross: 0
  };

  revenues.forEach(r => {
    if (r.entryType !== 'inflow') return;
    totals.totalGross += r.amount;

    if (r.activityType === 'commerce') {
      totals.commerce += r.amount;
      if (r.isPisCofinsExempt) totals.commerceExempt += r.amount;
    } else {
      totals.service += r.amount;
      if (r.isPisCofinsExempt) totals.serviceExempt += r.amount;
    }
  });

  // 1. Presunção
  const irpjBase = (totals.commerce * 0.08) + (totals.service * 0.32);
  const csllBase = (totals.commerce * 0.12) + (totals.service * 0.32);

  // 2. IRPJ (15% + 10% adicional sobre > 20k/mês)
  let irpj = irpjBase * 0.15;
  if (irpjBase > 20000) irpj += (irpjBase - 20000) * 0.10;

  // 3. CSLL (9%)
  const csll = csllBase * 0.09;

  // 4. PIS/COFINS (Zera onde for isento)
  const pisBase = totals.totalGross - totals.commerceExempt - totals.serviceExempt;
  const pis = pisBase * 0.0065;
  const cofins = pisBase * 0.03;

  // 5. ISS/ICMS (Estimados)
  const iss = totals.service * 0.05;
  const icms = totals.commerce * 0.18;

  const total = irpj + csll + pis + cofins + iss + icms;

  return {
    irpj, csll, pis, cofins, iss, icms, total,
    effectiveRate: totals.totalGross > 0 ? total / totals.totalGross : 0
  };
};

import React, { useMemo } from 'react';
import { Client, Revenue, TaxAnexo } from '../types';
import { calculateSimplesNacional, calculateLucroPresumidoAdvanced } from '../services/taxCalculator';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface IntelligentTaxManagerProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  selectedMonthIdx: number;
}

const IntelligentTaxManager: React.FC<IntelligentTaxManagerProps> = ({ focusedClient, revenues, selectedMonthIdx }) => {
  const currentMonthRevenues = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => {
          const d = new Date(r.date);
          return r.clientId === focusedClient.id && d.getMonth() === selectedMonthIdx && r.entryType === 'inflow';
        })
      : [];
  }, [revenues, focusedClient, selectedMonthIdx]);

  const stats = useMemo(() => {
    const totalInvoiced = currentMonthRevenues.reduce((acc, r) => acc + r.amount, 0);
    const rbt12 = focusedClient?.annualRevenue || 0;
    const anexo = focusedClient?.taxAnexo || 'III';

    const simples = calculateSimplesNacional(rbt12, totalInvoiced, anexo);
    const presumido = calculateLucroPresumidoAdvanced(currentMonthRevenues);

    const isSimplesBetter = simples.taxAmount <= presumido.total;
    const economy = Math.abs(simples.taxAmount - presumido.total);

    // Score de Saúde Fiscal (0-100)
    // Baseado na eficiência do regime atual
    let score = 100;
    if (totalInvoiced > 0) {
      const currentTax = isSimplesBetter ? simples.taxAmount : simples.taxAmount; // Assume simples como atual
      const optimalTax = Math.min(simples.taxAmount, presumido.total);
      const efficiency = optimalTax / currentTax;
      score = Math.floor(efficiency * 100);
    }

    return {
      simples,
      presumido,
      isSimplesBetter,
      economy,
      score,
      totalInvoiced
    };
  }, [currentMonthRevenues, focusedClient]);

