import React, { useMemo } from 'react';
import { Client, Revenue, TaxAnexo, TaxRules } from '../types';
import { calculateSimplesNacional, calculateLucroPresumidoAdvanced } from '../services/taxCalculator';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface IntelligentTaxManagerProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  selectedMonthIdx: number;
  taxRules: TaxRules;
}

const IntelligentTaxManager: React.FC<IntelligentTaxManagerProps> = ({ focusedClient, revenues, selectedMonthIdx, taxRules }) => {
  const currentMonthRevenues = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => {
          const d = new Date(r.date);
          return r.clientId === focusedClient.id && d.getMonth() === selectedMonthIdx && r.entryType === 'inflow';
        })
      : [];
  }, [revenues, focusedClient, selectedMonthIdx]);

  const stats = useMemo(() => {
    const totalInvoiced = currentMonthRevenues.reduce((acc, r) => acc + r.amount, 0);
    const rbt12 = focusedClient?.annualRevenue || 0;
    const anexo = focusedClient?.taxAnexo || 'III';

    const simples = calculateSimplesNacional(rbt12, totalInvoiced, anexo);
    const presumido = calculateLucroPresumidoAdvanced(currentMonthRevenues, taxRules);

    const isSimplesBetter = simples.taxAmount <= presumido.total;
    const economy = Math.abs(simples.taxAmount - presumido.total);

    let score = 100;
    if (totalInvoiced > 0) {
      const optimalTax = Math.min(simples.taxAmount, presumido.total);
      const efficiency = optimalTax / simples.taxAmount;
      score = Math.floor(efficiency * 100);
    }

    return {
      simples,
      presumido,
      isSimplesBetter,
      economy,
      score,
      totalInvoiced
    };
  }, [currentMonthRevenues, focusedClient, taxRules]);

  const chartData = [
    { name: 'Simples Nacional', total: stats.simples.taxAmount, color: '#3b82f6' },
    { name: 'Lucro Presumido', total: stats.presumido.total, color: '#64748b' }
  ];

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  if (!focusedClient) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-slate-400 space-y-4">
        <div className="text-6xl opacity-20">📡</div>
        <p className="font-black uppercase text-xs tracking-[0.3em]">Selecione uma empresa para consolidar o regime</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 pb-12">
      <header className="bg-slate-900 text-white p-10 rounded-[2.5rem] border border-white/5 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600/10 blur-[100px] rounded-full translate-x-1/2 -translate-y-1/2"></div>

        <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
           <div className="space-y-3 flex-1">
             <div className="inline-flex items-center px-4 py-1.5 bg-blue-500/20 rounded-full text-[10px] font-black uppercase tracking-[0.2em] text-blue-400 border border-blue-500/30">
                Consolidação de Regime Tributário
             </div>
             <h2 className="text-4xl font-black tracking-tighter leading-none">Análise de Eficiência Fiscal</h2>
             <p className="text-slate-400 text-sm max-w-xl font-medium">
               Aqui a IA consolida regimes tributários e mostra o caminho de menor imposto baseado na Matriz de Regras do Administrador.
             </p>
           </div>

           <div className="w-full md:w-auto flex flex-col items-center justify-center p-8 bg-white/5 rounded-[2rem] border border-white/10">
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Score de Saúde Fiscal</p>
              <div className="text-6xl font-black text-blue-500 tracking-tighter">{stats.score}</div>
              <div className="mt-2 h-1.5 w-32 bg-white/10 rounded-full overflow-hidden">
                 <div className="h-full bg-blue-500 transition-all duration-1000" style={{ width: `${stats.score}%` }}></div>
              </div>
           </div>
        </div>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-7 space-y-8">
           <div className={`p-8 rounded-[2.5rem] border-2 shadow-sm transition-all flex items-center justify-between ${
             stats.isSimplesBetter ? 'bg-emerald-50 border-emerald-100' : 'bg-blue-50 border-blue-100'
           }`}>
              <div className="space-y-1">
                 <p className={`text-[10px] font-black uppercase tracking-widest ${stats.isSimplesBetter ? 'text-emerald-600' : 'text-blue-600'}`}>Regime mais vantajoso no momento</p>
                 <h3 className="text-2xl font-black text-slate-900">{stats.isSimplesBetter ? 'Simples Nacional' : 'Lucro Presumido'}</h3>
                 <p className="text-xs font-bold text-slate-500">
                    Sua tributação atual estimada é {fmt(stats.simples.taxAmount)} e a otimizada seria {fmt(Math.min(stats.simples.taxAmount, stats.presumido.total))}.
                 </p>
              </div>
              <div className="text-right">
                 <p className="text-[10px] font-black text-slate-400 uppercase">Economia Potencial</p>
                 <p className={`text-2xl font-black ${stats.economy > 0 ? 'text-emerald-600' : 'text-slate-400'}`}>{fmt(stats.economy)}</p>
              </div>
           </div>

           <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-10">Custo Mensal Comparativo</h4>
              <div className="h-64">
                 <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData} margin={{ top: 0, right: 0, left: -20, bottom: 0 }}>
                       <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                       <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} />
                       <YAxis hide />
                       <Tooltip 
                         cursor={{fill: '#f8fafc'}}
                         contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                         formatter={(value: number) => [fmt(value), 'Imposto Consolidado']}
                       />
                       <Bar dataKey="total" radius={[12, 12, 0, 0]} barSize={60}>
                          {chartData.map((entry, index) => <Cell key={index} fill={entry.color} />)}
                       </Bar>
                    </BarChart>
                 </ResponsiveContainer>
              </div>
           </div>
        </div>

        <div className="lg:col-span-5 space-y-8">
           <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Resumo Operacional (Regras Admin)</h4>

              <div className="space-y-4">
                 <div className="flex justify-between items-center p-5 bg-slate-50 rounded-2xl">
                    <p className="text-xs font-black text-slate-700 uppercase">Isento PIS/COFINS Identificado</p>
                    <p className="text-sm font-black text-slate-900">
                      {fmt(currentMonthRevenues.filter(r => {
                        if (r.productCategory === 'monofasico') return !taxRules.monofasicoHasPisCofins;
                        if (r.productCategory === 'isento') return !taxRules.isentoHasPisCofins;
                        return false;
                      }).reduce((a, b) => a + b.amount, 0))}
                    </p>
                 </div>

                 <div className="p-6 bg-amber-50 rounded-3xl border border-amber-100 space-y-3">
                    <p className="text-[10px] text-amber-700 font-bold leading-relaxed">
                       A incidência de PIS/COFINS sobre produtos <b>Monofásicos</b> e <b>Isentos</b> foi configurada como: 
                       <br/><b>{taxRules.monofasicoHasPisCofins ? 'ATIVA' : 'SUSPENSA'}</b> e <b>{taxRules.isentoHasPisCofins ? 'ATIVA' : 'SUSPENSA'}</b> respectivamente.
                    </p>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default IntelligentTaxManager;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import IntelligentTaxManager from './components/IntelligentTaxManager';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import AdminUserManager from './components/AdminUserManager';
import SimplesCalculator from './components/SimplesCalculator';
import Settings from './components/Settings';
import Login from './components/Login';
import { View, UserRole, User, Client, UserAccount, Revenue, Tax, Employee, Document, TaxRules } from './types';

const STORAGE_KEYS = {
  CLIENTS: 'axis_clients_v2',
  USERS: 'axis_users_v2',
  REVENUES: 'axis_revenues_v2',
  TAXES: 'axis_taxes_v2',
  EMPLOYEES: 'axis_employees_v2',
  DOCUMENTS: 'axis_docs_v2',
  TAX_RULES: 'axis_tax_rules_v2'
};

const ADMIN_EMAIL_AUTH = 'adm@ad.com';
const DEFAULT_ADMIN_PASS = 'admin';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  // MATRIZ TRIBUTÁRIA GLOBAL (Controlada pelo ADM)
  const [taxRules, setTaxRules] = useState<TaxRules>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAX_RULES);
    return saved ? JSON.parse(saved) : { monofasicoHasPisCofins: false, isentoHasPisCofins: false };
  });

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    return saved ? JSON.parse(saved) : [];
  });

  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.USERS);
    const parsed = saved ? JSON.parse(saved) : [];
    if (!parsed.some((u: UserAccount) => u.email.toLowerCase() === ADMIN_EMAIL_AUTH)) {
      const initialAdmin: UserAccount = {
        id: 'USR_MASTER',
        name: 'Administrador Axis',
        email: ADMIN_EMAIL_AUTH,
        phone: '11999999999',
        role: UserRole.ADMIN,
        createdAt: new Date().toISOString(),
        lastLogin: 'Nunca',
        status: 'active',
        passwordHash: btoa(DEFAULT_ADMIN_PASS)
      };
      return [initialAdmin, ...parsed];
    }
    return parsed;
  });

  const [revenues, setRevenues] = useState<Revenue[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.REVENUES);
    return saved ? JSON.parse(saved) : [];
  });

  const [taxes, setTaxes] = useState<Tax[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAXES);
    return saved ? JSON.parse(saved) : [];
  });

  const [documents, setDocuments] = useState<Document[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(userAccounts)); }, [userAccounts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.REVENUES, JSON.stringify(revenues)); }, [revenues]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAXES, JSON.stringify(taxes)); }, [taxes]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(documents)); }, [documents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAX_RULES, JSON.stringify(taxRules)); }, [taxRules]);

  const handleLogin = (email: string, pass: string) => {
    const normalizedEmailInput = email.trim().toLowerCase();
    const hashedInput = btoa(pass.trim());
    const account = userAccounts.find(u => u.email.trim().toLowerCase() === normalizedEmailInput && u.passwordHash === hashedInput);

    if (account) {
      if (account.status !== 'active' && account.email !== ADMIN_EMAIL_AUTH) { 
        alert("Acesso Bloqueado."); return; 
      }
      const user: User = { id: account.id, name: account.name, email: account.email, role: account.role, cnpjVinculado: account.cnpjVinculado };
      setCurrentUser(user);
      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
      }
      setCurrentView(View.DASHBOARD);
    } else {
      alert("Usuário ou senha incorretos.");
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const commonProps = { focusedClient, revenues, setRevenues, taxes, setTaxes, documents, setDocuments, selectedMonthIdx, setSelectedMonthIdx, currentUser, clients, users: userAccounts, setUsers: setUserAccounts, taxRules, setTaxRules };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} onAddClient={(c) => setClients(p => [c, ...p])} onDeleteClient={(id) => setClients(p => p.filter(x => x.id !== id))} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} userRole={currentUser.role} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.INTELLIGENT_TAX: return <IntelligentTaxManager {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      case View.SIMPLES_CALCULATOR: return <SimplesCalculator {...commonProps} onSaveCalculation={() => {}} history={[]} />;
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={() => { setCurrentUser(null); setFocusedClient(null); setCurrentView(View.DASHBOARD); }} 
        hasActiveFocus={!!focusedClient}
      />
      <main className={`flex-1 transition-all duration-300 w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

