                 <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Valor do Lançamento</label>
                    <input required type="number" placeholder="0,00" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
