import React, { useMemo } from 'react';
import { AreaChart, Area, XAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { FinancialMetric, Client, UserRole, Revenue, TaxRules } from '../types';
import { calculateSimplesNacional, calculateLucroPresumidoAdvanced } from '../services/taxCalculator';

interface DashboardProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
  revenues?: Revenue[];
  taxRules: TaxRules;
  selectedMonthIdx: number;
}

const Dashboard: React.FC<DashboardProps> = ({ focusedClient, userRole, revenues = [], taxRules, selectedMonthIdx }) => {
  const currentMonth = selectedMonthIdx;
  const currentYear = new Date().getFullYear();

  const relevantRevenues = useMemo(() => {
    return focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;
  }, [revenues, focusedClient]);

  const metricsData = useMemo(() => {
    const monthlyInflow = relevantRevenues
      .filter(r => {
        const d = new Date(r.date);
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear && r.entryType === 'inflow';
      })
      .reduce((acc, r) => acc + r.amount, 0);

    const totalAnnual = relevantRevenues
      .filter(r => new Date(r.date).getFullYear() === currentYear && r.entryType === 'inflow')
      .reduce((acc, r) => acc + r.amount, 0);

    return { monthlyInflow, totalAnnual };
  }, [relevantRevenues, currentMonth, currentYear]);

  // Score de Saúde Fiscal (Simulado no Dashboard para facilitar visualização do cliente)
  const healthScore = useMemo(() => {
    if (!focusedClient) return null;
    const currentMonthInflows = relevantRevenues.filter(r => new Date(r.date).getMonth() === currentMonth && r.entryType === 'inflow');
    const total = currentMonthInflows.reduce((a, b) => a + b.amount, 0);
    if (total === 0) return 100;

    const simples = calculateSimplesNacional(focusedClient.annualRevenue || 0, total, focusedClient.taxAnexo || 'III');
    const presumido = calculateLucroPresumidoAdvanced(currentMonthInflows, taxRules);

    const optimalTax = Math.min(simples.taxAmount, presumido.total);
    const efficiency = optimalTax / simples.taxAmount;
    return Math.floor(efficiency * 100);
  }, [focusedClient, relevantRevenues, currentMonth, taxRules]);

  const metrics: FinancialMetric[] = [
    { label: 'Faturamento Mensal Real', value: metricsData.monthlyInflow, change: 0, trend: 'neutral' },
    { label: 'Faturamento Anual Acumulado', value: metricsData.totalAnnual, change: 0, trend: 'neutral' },
    { label: 'Score de Saúde Fiscal', value: healthScore || 0, change: 0, trend: 'neutral' },
    { label: 'Lançamentos Identificados', value: relevantRevenues.filter(r => r.entryType === 'inflow').length, change: 0, trend: 'neutral' },
  ];

  const chartData = useMemo(() => {
    const months = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'];
    return months.map((m, idx) => {
      const monthTotal = relevantRevenues
        .filter(r => new Date(r.date).getMonth() === idx && r.entryType === 'inflow')
        .reduce((acc, r) => acc + r.amount, 0);
      return { name: m, value: monthTotal };
    });
  }, [relevantRevenues]);

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      {/* Resumo de Foco (Apenas se houver cliente) */}
      {focusedClient && (
        <div className="p-6 bg-slate-900 rounded-[2.5rem] text-white flex flex-col md:flex-row items-center justify-between gap-6 shadow-2xl relative overflow-hidden">
           <div className="absolute top-0 right-0 w-64 h-64 bg-blue-500/10 blur-[80px] rounded-full"></div>
           <div className="flex items-center space-x-6 relative z-10">
              <div className="w-16 h-16 bg-blue-600 rounded-3xl flex items-center justify-center text-3xl font-black">
                {focusedClient.nomeFantasia.charAt(0)}
              </div>
              <div className="space-y-1">
                 <h2 className="text-2xl font-black tracking-tight">{focusedClient.nomeFantasia}</h2>
                 <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{focusedClient.identifier} • {focusedClient.taxAnexo ? `Anexo ${focusedClient.taxAnexo}` : 'Regime a Definir'}</p>
              </div>
           </div>

           <div className="flex items-center space-x-8 relative z-10">
              <div className="text-center">
                 <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Score Fiscal</p>
                 <p className={`text-4xl font-black ${healthScore && healthScore > 80 ? 'text-emerald-400' : 'text-blue-400'}`}>{healthScore}%</p>
              </div>
              <div className="w-px h-12 bg-white/10 hidden md:block"></div>
              <div className="hidden md:block">
                 <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Status de Operação</p>
                 <span className="px-3 py-1 bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 text-[10px] font-black rounded-full uppercase">Em Conformidade</span>
              </div>
           </div>
        </div>
      )}

      {/* Grid de Métricas */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {metrics.map((metric, idx) => {
          const isScore = metric.label === 'Score de Saúde Fiscal';
          return (
            <div key={idx} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 transition-all hover:shadow-md">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{metric.label}</p>
              <h3 className={`text-2xl font-black tracking-tighter ${isScore ? 'text-blue-600' : 'text-slate-800'}`}>
                {metric.label.includes('Faturamento') ? fmt(metric.value) : isScore ? `${metric.value}%` : metric.value}
              </h3>
              <div className="flex items-center mt-2">
                <span className="text-[8px] text-slate-300 uppercase font-black tracking-widest">Sincronização 1:1</span>
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Gráfico de Evolução */}
        <div className="lg:col-span-8 bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100">
          <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-8">Evolução do Faturamento Mensal</h3>
          <div className="h-72 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 800, fill: '#94a3b8'}} dy={10} />
                <Tooltip 
                  formatter={(value: number) => fmt(value)}
                  contentStyle={{borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', fontSize: '12px', fontWeight: 'bold'}}
                />
                <Area type="monotone" dataKey="value" stroke="#3b82f6" strokeWidth={4} fillOpacity={1} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Alertas e Insights (Somente Leitura) */}
        <div className="lg:col-span-4 space-y-6">
           <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-6">
              <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Alertas Fiscais Inteligentes</h4>
              <div className="space-y-4">
                 <div className="p-4 bg-amber-50 border border-amber-100 rounded-2xl flex items-start space-x-3">
                    <span className="mt-0.5">⚠️</span>
                    <p className="text-[10px] font-bold text-amber-800 leading-relaxed uppercase">
                      Lançamentos sem classificação fiscal detectados. Revise o extrato para evitar tributação indevida.
                    </p>
                 </div>
                 <div className="p-4 bg-blue-50 border border-blue-100 rounded-2xl flex items-start space-x-3">
                    <span className="mt-0.5">📡</span>
                    <p className="text-[10px] font-bold text-blue-800 leading-relaxed uppercase">
                      Economia potencial de 12% identificada na transição para Lucro Presumido. Consulte seu contador.
                    </p>
                 </div>
              </div>
           </div>

           <div className="bg-blue-600 p-8 rounded-[2.5rem] shadow-xl text-white flex flex-col justify-center text-center">
              <p className="text-[9px] font-black uppercase tracking-[0.3em] mb-2 opacity-60">Insight Proativo</p>
              <p className="text-xs font-bold leading-relaxed">
                Baseado nos seus últimos 3 meses, o Anexo {focusedClient?.taxAnexo || 'III'} continua sendo a opção mais lucrativa para sua atividade.
              </p>
           </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Client, TaxAnexo, UserAccount, UserRole, User, View } from '../types';

interface ClientManagementProps {
  clients: Client[];
  users: UserAccount[];
  setUsers: React.Dispatch<React.SetStateAction<UserAccount[]>>;
  onSelectClient?: (client: Client) => void;
  onAddClient: (client: Client) => void;
  onDeleteClient: (clientId: string) => void;
  onUpdateClient?: (client: Client) => void;
  currentUser?: User | null;
  onViewChange?: (view: View) => void;
}

const ADMIN_EMAIL_AUTH = 'adm@ad.com';

const ClientManagement: React.FC<ClientManagementProps> = ({ 
  clients, 
  users, 
  setUsers, 
  onSelectClient, 
  onAddClient, 
  onDeleteClient, 
  onUpdateClient,
  currentUser,
  onViewChange
}) => {
  const [showForm, setShowForm] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  const [formData, setFormData] = useState({
    name: '', 
    nomeFantasia: '',
    nomeEmpresario: '',
    identifier: '', 
    email: '', 
    phone: '', 
    type: 'PJ' as 'PF' | 'PJ', 
    annualRevenue: '', 
    taxAnexo: 'III' as TaxAnexo, 
    status: 'active' as 'active' | 'inactive',
    initialPassword: 'axis' + Math.floor(1000 + Math.random() * 9000)
  });

  const resetForm = () => {
    setFormData({
      name: '', nomeFantasia: '', nomeEmpresario: '', identifier: '', email: '', phone: '', type: 'PJ', 
      annualRevenue: '', taxAnexo: 'III', status: 'active',
      initialPassword: 'axis' + Math.floor(1000 + Math.random() * 9000)
    });
    setShowForm(false);
  };

  const isMasterAdmin = currentUser?.email.toLowerCase() === ADMIN_EMAIL_AUTH;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const normalizedEmail = formData.email.trim().toLowerCase();
    const normalizedIdentifier = formData.identifier.trim();
    const normalizedPass = formData.initialPassword.trim();

    if (clients.some(c => c.identifier === normalizedIdentifier)) {
      alert('Erro: Este CNPJ já possui uma empresa vinculada.'); return;
    }

    setIsProcessing(true);
    const clientId = `CLI_${Date.now()}`;

    const clientData: Client = {
      id: clientId,
      name: formData.name.trim(),
      nomeFantasia: formData.nomeFantasia.trim(),
      nomeEmpresario: formData.nomeEmpresario.trim(),
      identifier: normalizedIdentifier,
      email: normalizedEmail,
      phone: formData.phone.trim(),
      type: formData.type,
      status: formData.status,
      createdAt: new Date().toISOString().split('T')[0],
      taxAnexo: formData.taxAnexo,
      annualRevenue: parseFloat(formData.annualRevenue) || 0,
    };

    const newUser: UserAccount = {
      id: `USR_${Date.now()}`,
      name: formData.nomeEmpresario.trim(),
      email: normalizedEmail,
      phone: formData.phone.trim(),
      role: UserRole.CLIENT,
      createdAt: new Date().toISOString().split('T')[0],
      lastLogin: 'Nunca',
      status: 'active',
      passwordHash: btoa(normalizedPass),
      cnpjVinculado: normalizedIdentifier
    };

    setUsers(prev => [newUser, ...prev]);
    onAddClient(clientData);

    setIsProcessing(false);
    resetForm();
    alert(`Sucesso: Empresa e Login criados para ${normalizedEmail}`);
  };

  const handleDeleteRequest = (client: Client) => {
    if (!isMasterAdmin) {
      alert("ACESSO NEGADO: Apenas o administrador mestre pode excluir empresas.");
      return;
    }
    if (window.confirm(`Deseja realmente excluir a empresa "${client.nomeFantasia}"?`)) {
      onDeleteClient(client.id);
    }
  };

  const handleAccessClient = (client: Client) => {
    onSelectClient?.(client);
    onViewChange?.(View.DASHBOARD); // Direciona para o Dashboard do cliente ao acessar
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">Gestão de Empresas</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Controle Central de Unidades</p>
        </div>
        <button onClick={() => setShowForm(true)} className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl active:scale-95 transition-all">
          Nova Empresa + Login
        </button>
      </header>

      {showForm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-3xl rounded-[2.5rem] shadow-2xl p-10 overflow-y-auto max-h-[90vh]">
            <div className="flex justify-between items-start mb-8">
               <div>
                  <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Cadastro Unificado</h3>
                  <p className="text-slate-500 text-xs font-bold uppercase">Empresa, Empresário e Credenciais</p>
               </div>
               <button onClick={resetForm} className="p-2 hover:bg-slate-100 rounded-full">✕</button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input required placeholder="Razão Social" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                <input required placeholder="Nome Fantasia" value={formData.nomeFantasia} onChange={(e) => setFormData({...formData, nomeFantasia: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input required placeholder="Empresário" value={formData.nomeEmpresario} onChange={(e) => setFormData({...formData, nomeEmpresario: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
                <input required placeholder="CNPJ" value={formData.identifier} onChange={(e) => setFormData({...formData, identifier: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold" />
              </div>
              <div className="p-6 bg-blue-50 rounded-3xl border border-blue-100 space-y-4">
                <input required type="email" placeholder="E-mail Login" value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})} className="w-full p-4 border border-blue-200 rounded-2xl bg-white font-bold" />
                <div className="p-4 bg-white border border-blue-200 rounded-2xl font-black text-blue-700 text-center uppercase tracking-widest">{formData.initialPassword}</div>
              </div>
              <button type="submit" disabled={isProcessing} className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl">Confirmar Registro</button>
            </form>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase border-b">
            <tr>
              <th className="px-8 py-5">Empresa / Responsável</th>
              <th className="px-8 py-5">CNPJ Vinculado</th>
              <th className="px-8 py-5">Login</th>
              <th className="px-8 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {clients.map(client => (
              <tr key={client.id} className="hover:bg-slate-50/50 transition-all group">
                <td className="px-8 py-6">
                  <p className="font-black text-slate-800 text-sm">{client.nomeFantasia}</p>
                  <p className="text-[10px] text-slate-400 font-bold uppercase">{client.nomeEmpresario}</p>
                </td>
                <td className="px-8 py-6">
                  <span className="text-xs font-black text-slate-600 font-mono bg-slate-100 px-3 py-1 rounded-lg">{client.identifier}</span>
                </td>
                <td className="px-8 py-6"><p className="text-xs font-bold text-slate-500">{client.email}</p></td>
                <td className="px-8 py-6 text-right">
                  <div className="flex justify-end items-center space-x-2">
                    <button onClick={() => handleAccessClient(client)} className="px-5 py-2.5 bg-blue-50 text-blue-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all shadow-sm">
                      Acessar
                    </button>
                    {isMasterAdmin && (
                      <button onClick={() => handleDeleteRequest(client)} className="px-5 py-2.5 bg-red-50 text-red-600 rounded-xl text-[10px] font-black uppercase hover:bg-red-600 hover:text-white transition-all">
                        Excluir
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default ClientManagement;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import IntelligentTaxManager from './components/IntelligentTaxManager';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import AdminUserManager from './components/AdminUserManager';
import SimplesCalculator from './components/SimplesCalculator';
import Settings from './components/Settings';
import Login from './components/Login';
import { View, UserRole, User, Client, UserAccount, Revenue, Tax, Employee, Document, TaxRules } from './types';

const STORAGE_KEYS = {
  CLIENTS: 'axis_clients_v2',
  USERS: 'axis_users_v2',
  REVENUES: 'axis_revenues_v2',
  TAXES: 'axis_taxes_v2',
  EMPLOYEES: 'axis_employees_v2',
  DOCUMENTS: 'axis_docs_v2',
  TAX_RULES: 'axis_tax_rules_v2'
};

const ADMIN_EMAIL_AUTH = 'adm@ad.com';
const DEFAULT_ADMIN_PASS = 'admin';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);

  const [taxRules, setTaxRules] = useState<TaxRules>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAX_RULES);
    return saved ? JSON.parse(saved) : { monofasicoHasPisCofins: false, isentoHasPisCofins: false };
  });

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    return saved ? JSON.parse(saved) : [];
  });

  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.USERS);
    const parsed = saved ? JSON.parse(saved) : [];
    if (!parsed.some((u: UserAccount) => u.email.toLowerCase() === ADMIN_EMAIL_AUTH)) {
      const initialAdmin: UserAccount = {
        id: 'USR_MASTER',
        name: 'Administrador Axis',
        email: ADMIN_EMAIL_AUTH,
        phone: '11999999999',
        role: UserRole.ADMIN,
        createdAt: new Date().toISOString(),
        lastLogin: 'Nunca',
        status: 'active',
        passwordHash: btoa(DEFAULT_ADMIN_PASS)
      };
      return [initialAdmin, ...parsed];
    }
    return parsed;
  });

  const [revenues, setRevenues] = useState<Revenue[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.REVENUES);
    return saved ? JSON.parse(saved) : [];
  });

  const [taxes, setTaxes] = useState<Tax[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAXES);
    return saved ? JSON.parse(saved) : [];
  });

  const [documents, setDocuments] = useState<Document[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(userAccounts)); }, [userAccounts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.REVENUES, JSON.stringify(revenues)); }, [revenues]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAXES, JSON.stringify(taxes)); }, [taxes]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(documents)); }, [documents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAX_RULES, JSON.stringify(taxRules)); }, [taxRules]);

  const handleLogin = (email: string, pass: string) => {
    const normalizedEmailInput = email.trim().toLowerCase();
    const hashedInput = btoa(pass.trim());
    const account = userAccounts.find(u => u.email.trim().toLowerCase() === normalizedEmailInput && u.passwordHash === hashedInput);

    if (account) {
      if (account.status !== 'active' && account.email !== ADMIN_EMAIL_AUTH) { 
        alert("Acesso Bloqueado."); return; 
      }
      const user: User = { id: account.id, name: account.name, email: account.email, role: account.role, cnpjVinculado: account.cnpjVinculado };
      setCurrentUser(user);
      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
      }
      setCurrentView(View.DASHBOARD);
    } else {
      alert("Usuário ou senha incorretos.");
    }
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const commonProps = { focusedClient, revenues, setRevenues, taxes, setTaxes, documents, setDocuments, selectedMonthIdx, setSelectedMonthIdx, currentUser, clients, users: userAccounts, setUsers: setUserAccounts, taxRules, setTaxRules, onViewChange: setCurrentView };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} onAddClient={(c) => setClients(p => [c, ...p])} onDeleteClient={(id) => setClients(p => p.filter(x => x.id !== id))} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} userRole={currentUser.role} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.INTELLIGENT_TAX: return <IntelligentTaxManager {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      case View.SIMPLES_CALCULATOR: return <SimplesCalculator {...commonProps} onSaveCalculation={() => {}} history={[]} />;
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={() => { setCurrentUser(null); setFocusedClient(null); setCurrentView(View.DASHBOARD); }} 
        hasActiveFocus={!!focusedClient}
        onClearFocus={() => setFocusedClient(null)} // Novo: Permite Admin sair do foco do cliente
      />
      <main className={`flex-1 transition-all duration-300 w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Revenue, Client, User, UserRole, ProductCategory } from '../types';

interface RevenueScheduleProps {
  focusedClient?: Client | null;
  revenues: Revenue[];
  setRevenues: React.Dispatch<React.SetStateAction<Revenue[]>>;
  selectedMonthIdx: number;
  setSelectedMonthIdx: (idx: number) => void;
  currentUser: User | null;
}

const months = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

export const RevenueSchedule: React.FC<RevenueScheduleProps> = ({ focusedClient, revenues, setRevenues, selectedMonthIdx, setSelectedMonthIdx, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const isAdmin = currentUser?.role === UserRole.ADMIN;
  const isClient = currentUser?.role === UserRole.CLIENT;

  const [formData, setFormData] = useState({
    client: '', 
    amount: '', 
    date: new Date().toISOString().split('T')[0],
    status: 'received' as 'received' | 'expected',
    entryType: 'inflow' as 'inflow' | 'outflow',
    activityType: 'service' as 'service' | 'commerce',
    productCategory: 'normal' as ProductCategory,
    isPisCofinsExempt: false,
    description: ''
  });

  const filteredByClient = useMemo(() => {
    return focusedClient ? revenues.filter(r => r.clientId === focusedClient.id) : [];
  }, [revenues, focusedClient]);

  const filteredRevenues = useMemo(() => {
    return filteredByClient.filter(rev => {
      const m = parseInt(rev.date.split('-')[1]) - 1;
      return m === selectedMonthIdx && 
             (rev.client.toLowerCase().includes(searchTerm.toLowerCase()) || 
              rev.description?.toLowerCase().includes(searchTerm.toLowerCase()));
    }).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [filteredByClient, selectedMonthIdx, searchTerm]);

  const handleEdit = (rev: Revenue) => {
    if (!isAdmin) return; // Clientes não editam itens existentes
    setEditingId(rev.id);
    setFormData({
      client: rev.client,
      amount: rev.amount.toString(),
      date: rev.date,
      status: rev.status,
      entryType: rev.entryType,
      activityType: rev.activityType,
      productCategory: rev.productCategory,
      isPisCofinsExempt: rev.isPisCofinsExempt,
      description: rev.description || ''
    });
    setShowModal(true);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    if (!focusedClient) { alert("Erro: Selecione uma empresa."); return; }

    const revenueData: Revenue = {
      id: editingId || `REV_${Date.now()}`,
      client: formData.client,
      amount: parseFloat(formData.amount),
      date: formData.date,
      status: formData.status,
      entryType: formData.entryType,
      activityType: formData.activityType,
      productCategory: formData.productCategory,
      isPisCofinsExempt: isAdmin ? formData.isPisCofinsExempt : false,
      description: formData.description,
      source: 'manual',
      clientId: focusedClient.id,
      createdBy: currentUser?.id
    };

    if (editingId) {
      setRevenues(prev => prev.map(r => r.id === editingId ? revenueData : r));
    } else {
      setRevenues(prev => [revenueData, ...prev]);
    }
    setShowModal(false);
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-6">
      <header className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
          <div className="flex items-center space-x-2">
            <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Memória Financeira</p>
            {isAdmin && <span className="px-2 py-0.5 bg-slate-900 text-white text-[8px] font-black rounded-full uppercase tracking-tighter">Admin View</span>}
            {isClient && <span className="px-2 py-0.5 bg-blue-100 text-blue-600 text-[8px] font-black rounded-full uppercase tracking-tighter">Somente Leitura de Histórico</span>}
          </div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Extrato do Cliente</h2>
        </div>
        <button 
          onClick={() => { setEditingId(null); setShowModal(true); setFormData({...formData, client: '', amount: '', description: ''}); }}
          className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl"
        >
          Novo Lançamento
        </button>
      </header>

      <div className="grid grid-cols-4 md:grid-cols-12 gap-2">
        {months.map((m, idx) => (
          <button
            key={m}
            onClick={() => setSelectedMonthIdx(idx)}
            className={`py-3 rounded-xl text-[10px] font-black uppercase transition-all ${
              selectedMonthIdx === idx ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100'
            }`}
          >
            {m.substring(0, 3)}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b">
            <tr>
              <th className="px-8 py-5">Data</th>
              <th className="px-8 py-5">Atividade</th>
              <th className="px-8 py-5">Natureza Fiscal</th>
              <th className="px-8 py-5 text-right">Valor</th>
              <th className="px-8 py-5 text-right">Ações</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredRevenues.map(rev => (
              <tr key={rev.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-8 py-5 font-black text-slate-600 text-xs">{rev.date.split('-').reverse().join('/')}</td>
                <td className="px-8 py-5">
                   <span className={`px-2 py-1 rounded text-[9px] font-black uppercase ${rev.activityType === 'commerce' ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'}`}>
                    {rev.activityType === 'commerce' ? 'Comércio' : 'Serviço'}
                   </span>
                </td>
                <td className="px-8 py-5">
                   <div className="flex flex-col space-y-1">
                      <span className={`w-fit px-2 py-1 rounded text-[9px] font-black uppercase ${
                        rev.productCategory === 'monofasico' ? 'bg-amber-100 text-amber-700' : 
                        rev.productCategory === 'isento' ? 'bg-purple-100 text-purple-700' : 
                        'bg-slate-100 text-slate-700'
                      }`}>
                        {rev.productCategory === 'monofasico' ? 'Monofásico' : 
                         rev.productCategory === 'isento' ? 'Isento' : 'Normal'}
                      </span>
                   </div>
                </td>
                <td className={`px-8 py-5 text-right font-black ${rev.entryType === 'inflow' ? 'text-emerald-600' : 'text-red-600'}`}>
                  {rev.entryType === 'inflow' ? '+' : '-'} {fmt(rev.amount)}
                </td>
                <td className="px-8 py-5 text-right">
                  {isAdmin ? (
                    <div className="flex justify-end space-x-2">
                      <button onClick={() => handleEdit(rev)} className="text-blue-500 hover:text-blue-700 text-[10px] font-black uppercase">Editar</button>
                      <button onClick={() => setRevenues(prev => prev.filter(r => r.id !== rev.id))} className="text-red-400 hover:text-red-600 text-[10px] font-black uppercase">Excluir</button>
                    </div>
                  ) : (
                    <span className="text-[8px] font-black text-slate-300 uppercase italic">Confirmado</span>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] p-10 shadow-2xl space-y-6">
            <header className="flex justify-between items-center">
              <h3 className="text-xl font-black text-slate-900 uppercase">Lançamento Financeiro</h3>
              {isAdmin && <span className="px-3 py-1 bg-amber-500 text-white text-[9px] font-black rounded-full uppercase">Admin Control</span>}
            </header>

            <form onSubmit={handleSave} className="space-y-4">
               <div className="grid grid-cols-2 gap-4">
                 <input required placeholder="Descrição" value={formData.client} onChange={e => setFormData({...formData, client: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
                 <input required type="number" placeholder="Valor" value={formData.amount} onChange={e => setFormData({...formData, amount: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <select value={formData.activityType} onChange={e => setFormData({...formData, activityType: e.target.value as any})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none">
                    <option value="service">Serviços</option>
                    <option value="commerce">Comércio</option>
                 </select>
                 <select value={formData.productCategory} onChange={e => setFormData({...formData, productCategory: e.target.value as ProductCategory})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none">
                    <option value="normal">Produto Normal</option>
                    <option value="monofasico">Produto Monofásico</option>
                    <option value="isento">Produto Isento</option>
                 </select>
               </div>

               <div className="space-y-1">
                 <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Data Competência</label>
                 <input required type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full p-4 border rounded-2xl bg-slate-50 font-bold outline-none" />
               </div>

               {isAdmin && (
                 <div className="p-6 bg-slate-900 rounded-3xl border border-white/10 space-y-4">
                    <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest text-center">Controle Fiscal Administrativo</p>
                    <div className="flex items-center justify-between p-4 bg-white/5 rounded-2xl cursor-pointer" onClick={() => setFormData({...formData, isPisCofinsExempt: !formData.isPisCofinsExempt})}>
                       <span className="text-xs font-bold text-white">Suspender PIS/COFINS Manualmente</span>
                       <div className={`w-10 h-5 rounded-full relative transition-colors ${formData.isPisCofinsExempt ? 'bg-blue-600' : 'bg-slate-700'}`}>
                          <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${formData.isPisCofinsExempt ? 'left-6' : 'left-1'}`}></div>
                       </div>
                    </div>
                 </div>
               )}

               <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl">{editingId ? 'Salvar Edição' : 'Concluir Lançamento'}</button>
               <button type="button" onClick={() => setShowModal(false)} className="w-full text-slate-400 font-black uppercase text-xs">Cancelar</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

