}

const PeopleManagement: React.FC<PeopleManagementProps> = ({ focusedClient, currentUser, adminVisualizationMode = false }) => {
  const [employees, setEmployees] = useState<Employee[]>([
    { id: '1', name: 'Ana Silva', role: 'Gerente Financeira', salary: 7500, admissionDate: '2022-05-10', status: 'active', department: 'Administração', clientId: focusedClient?.id || '', lastVacationDate: '2023-06-01' },
    { id: '2', name: 'Bruno Costa', role: 'Analista Fiscal', salary: 4200, admissionDate: '2023-01-15', status: 'active', department: 'Fiscal', clientId: focusedClient?.id || '' },
    { id: '3', name: 'Carla Souza', role: 'Recepcionista', salary: 2100, admissionDate: '2021-11-20', status: 'vacation', department: 'Atendimento', clientId: focusedClient?.id || '', lastVacationDate: '2024-03-01' },
  ]);

  const [showModal, setShowModal] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [simulationType, setSimulationType] = useState<'resignation' | 'vacation' | null>(null);

  const isAdmin = currentUser?.role === UserRole.ADMIN;
  const isReadOnly = (isAdmin && adminVisualizationMode) || currentUser?.role === UserRole.CLIENT;

  const filteredEmployees = useMemo(() => {
    return focusedClient ? employees.filter(e => e.clientId === focusedClient.id) : employees;
  }, [employees, focusedClient]);

  const stats = useMemo(() => {
    const active = filteredEmployees.filter(e => e.status !== 'resigned').length;
    const totalPayroll = filteredEmployees.filter(e => e.status !== 'resigned').reduce((acc, e) => acc + e.salary, 0);
    return { active, totalPayroll, avgSalary: active > 0 ? totalPayroll / active : 0 };
  }, [filteredEmployees]);

  const calculateResignation = (emp: Employee) => {
    // Simulação simplificada de rescisão (CLT)
    const saldoSalario = emp.salary / 2; // Ex: 15 dias
    const decimoTerceiro = emp.salary * 0.5; // Ex: 6/12
    const feriasProp = (emp.salary * 1.33) * 0.4; // Estimativa proporcional
    const avisoPrevio = emp.salary;
    const multaFgts = (emp.salary * 12 * 0.08) * 0.4; // Estimativa 1 ano
    const total = saldoSalario + decimoTerceiro + feriasProp + avisoPrevio + multaFgts;

    return { saldoSalario, decimoTerceiro, feriasProp, avisoPrevio, multaFgts, total };
  };

  const calculateVacation = (emp: Employee) => {
    const valorBase = emp.salary;
    const tercoConstitucional = valorBase / 3;
    const totalBruto = valorBase + tercoConstitucional;
    const inss = totalBruto * 0.11; // Simplificado
    const totalLiquido = totalBruto - inss;
    return { valorBase, tercoConstitucional, totalBruto, inss, totalLiquido };
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Inteligência em RH</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Gestão de Pessoas</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Controle de Colaboradores e Obrigações</p>
        </div>
        {!isReadOnly && (
          <button onClick={() => setShowModal(true)} className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all active:scale-95">
            Cadastrar Colaborador +
          </button>
        )}
      </header>

      {/* KPI GRID */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Colaboradores Ativos</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">{stats.active}</p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Folha Mensal (Base)</p>
          <p className="text-3xl font-black text-blue-600 tracking-tighter">{fmt(stats.totalPayroll)}</p>
        </div>
        <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Salário Médio</p>
          <p className="text-3xl font-black text-white tracking-tighter">{fmt(stats.avgSalary)}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* LISTA DE COLABORADORES */}
        <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
          <table className="w-full text-left">
