import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import IntelligentTaxManager from './components/IntelligentTaxManager';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import AdminUserManager from './components/AdminUserManager';
import SimplesCalculator from './components/SimplesCalculator';
import PeopleManagement from './components/PeopleManagement';
import Settings from './components/Settings';
import Login from './components/Login';
import { View, UserRole, User, Client, UserAccount, Revenue, Tax, Employee, Document, TaxRules } from './types';

const STORAGE_KEYS = {
  CLIENTS: 'axis_clients_v2',
  USERS: 'axis_users_v2',
  REVENUES: 'axis_revenues_v2',
  TAXES: 'axis_taxes_v2',
  EMPLOYEES: 'axis_employees_v2',
  DOCUMENTS: 'axis_docs_v2',
  TAX_RULES: 'axis_tax_rules_v2'
};

const ADMIN_EMAIL_AUTH = 'adm@ad.com';
const DEFAULT_ADMIN_PASS = 'admin';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);
  const [adminVisualizationMode, setAdminVisualizationMode] = useState(false);

  const [taxRules, setTaxRules] = useState<TaxRules>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAX_RULES);
    return saved ? JSON.parse(saved) : { monofasicoHasPisCofins: false, isentoHasPisCofins: false };
  });

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    return saved ? JSON.parse(saved) : [];
  });

  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.USERS);
    let parsed = saved ? JSON.parse(saved) : [];

    // Busca o admin mestre ou cria um novo
    const adminIdx = parsed.findIndex((u: UserAccount) => u.email.toLowerCase() === ADMIN_EMAIL_AUTH);

    if (adminIdx === -1) {
      const initialAdmin: UserAccount = {
        id: 'USR_MASTER',
        name: 'Administrador Axis',
        email: ADMIN_EMAIL_AUTH,
        phone: '11999999999',
        role: UserRole.ADMIN,
        createdAt: new Date().toISOString(),
        lastLogin: 'Nunca',
        status: 'active',
        passwordHash: btoa(DEFAULT_ADMIN_PASS)
      };
      return [initialAdmin, ...parsed];
    }

    return parsed;
  });

  const [revenues, setRevenues] = useState<Revenue[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.REVENUES);
    return saved ? JSON.parse(saved) : [];
  });

  const [taxes, setTaxes] = useState<Tax[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAXES);
    return saved ? JSON.parse(saved) : [];
  });

  const [documents, setDocuments] = useState<Document[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(userAccounts)); }, [userAccounts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.REVENUES, JSON.stringify(revenues)); }, [revenues]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAXES, JSON.stringify(taxes)); }, [taxes]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(documents)); }, [documents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAX_RULES, JSON.stringify(taxRules)); }, [taxRules]);

  const handleLogin = (email: string, pass: string) => {
    const normalizedEmailInput = email.trim().toLowerCase();
    const cleanPass = pass.trim();
    const hashedInput = btoa(cleanPass);

    // Busca o usuário
    let account = userAccounts.find(u => u.email.trim().toLowerCase() === normalizedEmailInput && u.passwordHash === hashedInput);

    // Fallback de Emergência para o Administrador Mestre se o localStorage estiver corrompido
    if (!account && normalizedEmailInput === ADMIN_EMAIL_AUTH && cleanPass === DEFAULT_ADMIN_PASS) {
      const masterAdmin = userAccounts.find(u => u.email.toLowerCase() === ADMIN_EMAIL_AUTH);
      if (masterAdmin) {
        // Corrige a senha no estado para futuros logins
        setUserAccounts(prev => prev.map(u => u.email.toLowerCase() === ADMIN_EMAIL_AUTH ? { ...u, passwordHash: btoa(DEFAULT_ADMIN_PASS) } : u));
        account = { ...masterAdmin, passwordHash: btoa(DEFAULT_ADMIN_PASS) };
      }
    }

    if (account) {
      if (account.status !== 'active' && account.email !== ADMIN_EMAIL_AUTH) { 
        alert("Acesso Bloqueado."); return; 
      }
      const user: User = { id: account.id, name: account.name, email: account.email, role: account.role, cnpjVinculado: account.cnpjVinculado };
      setCurrentUser(user);
      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
        setAdminVisualizationMode(false);
      }
      setCurrentView(View.DASHBOARD);
    } else {
      alert("Usuário ou senha incorretos.");
    }
  };

  const handleAccessClient = (client: Client) => {
    setFocusedClient(client);
    setAdminVisualizationMode(true);
    setCurrentView(View.DASHBOARD);
  };

  const handleClearFocus = () => {
    setFocusedClient(null);
    setAdminVisualizationMode(false);
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const commonProps = { 
      focusedClient, 
      revenues, 
      setRevenues, 
      taxes, 
      setTaxes, 
      documents, 
      setDocuments, 
      selectedMonthIdx, 
      setSelectedMonthIdx, 
      currentUser, 
      clients, 
      users: userAccounts, 
      setUsers: setUserAccounts, 
      taxRules, 
      setTaxRules, 
      onViewChange: setCurrentView,
      adminVisualizationMode
    };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} onSelectClient={handleAccessClient} onAddClient={(c) => setClients(p => [c, ...p])} onDeleteClient={(id) => setClients(p => p.filter(x => x.id !== id))} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} userRole={currentUser.role} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.INTELLIGENT_TAX: return <IntelligentTaxManager {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      case View.SIMPLES_CALCULATOR: return <SimplesCalculator {...commonProps} onSaveCalculation={() => {}} history={[]} />;
      case View.PEOPLE_MANAGEMENT: return <PeopleManagement {...commonProps} />;
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role}
        isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={() => { setCurrentUser(null); setFocusedClient(null); setAdminVisualizationMode(false); setCurrentView(View.DASHBOARD); }} 
        hasActiveFocus={!!focusedClient}
        onClearFocus={handleClearFocus}
        adminVisualizationMode={adminVisualizationMode}
      />
      <main className={`flex-1 transition-all duration-300 w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

