import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import IntelligentTaxManager from './components/IntelligentTaxManager';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import AdminUserManager from './components/AdminUserManager';
import SimplesCalculator from './components/SimplesCalculator';
import PeopleManagement from './components/PeopleManagement';
import Settings from './components/Settings';
import Login from './components/Login';
import { View, UserRole, User, Client, UserAccount, Revenue, Tax, Employee, Document, TaxRules } from './types';

const STORAGE_KEYS = {
  CLIENTS: 'axis_clients_v2',
  USERS: 'axis_users_v2',
  REVENUES: 'axis_revenues_v2',
  TAXES: 'axis_taxes_v2',
  EMPLOYEES: 'axis_employees_v2',
  DOCUMENTS: 'axis_docs_v2',
  TAX_RULES: 'axis_tax_rules_v2'
};

const ADMIN_EMAIL_AUTH = 'adm@ad.com';
const DEFAULT_ADMIN_PASS = '12345'; 

// Dados de Demonstração Iniciais
const SEED_CLIENT: Client = {
  id: 'CLI_DEMO_01',
  name: 'Nexus Tech Soluções LTDA',
  nomeFantasia: 'Nexus Tech',
  nomeEmpresario: 'Carlos Eduardo',
  identifier: '12.345.678/0001-90',
  email: 'nexus@demo.com',
  status: 'active',
  type: 'PJ',
  createdAt: '2024-01-01',
  taxAnexo: 'III',
  annualRevenue: 450000
};

const SEED_REVENUES: Revenue[] = [
  { id: 'R1', client: 'Venda de Software', amount: 15000, date: new Date().toISOString().split('T')[0], status: 'received', source: 'manual', entryType: 'inflow', activityType: 'service', productCategory: 'normal', isPisCofinsExempt: false, clientId: 'CLI_DEMO_01' },
  { id: 'R2', client: 'Consultoria Mensal', amount: 8000, date: new Date().toISOString().split('T')[0], status: 'received', source: 'manual', entryType: 'inflow', activityType: 'service', productCategory: 'normal', isPisCofinsExempt: false, clientId: 'CLI_DEMO_01' }
];

const SEED_EMPLOYEES: Employee[] = [
  { id: '1', name: 'Ana Silva', role: 'Gerente Financeira', salary: 7500, admissionDate: '2022-05-10', birthDate: '1990-08-22', workload: 176, status: 'active', department: 'Administração', clientId: 'CLI_DEMO_01', journeyLogs: [] },
  { id: '2', name: 'Bruno Costa', role: 'Analista Fiscal', salary: 4200, admissionDate: '2023-01-15', birthDate: '1995-03-12', workload: 176, status: 'active', department: 'Fiscal', clientId: 'CLI_DEMO_01', journeyLogs: [] }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);
  const [adminVisualizationMode, setAdminVisualizationMode] = useState(false);

  const [taxRules, setTaxRules] = useState<TaxRules>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAX_RULES);
    return saved ? JSON.parse(saved) : { monofasicoHasPisCofins: false, isentoHasPisCofins: false };
  });

  const [clients, setClients] = useState<Client[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    return saved ? JSON.parse(saved) : [SEED_CLIENT];
  });

  const [userAccounts, setUserAccounts] = useState<UserAccount[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.USERS);
    let parsed = saved ? JSON.parse(saved) : [];
    const adminIdx = parsed.findIndex((u: UserAccount) => u.email.toLowerCase() === ADMIN_EMAIL_AUTH);
    const targetHash = btoa(DEFAULT_ADMIN_PASS);

    if (adminIdx === -1) {
      const initialAdmin: UserAccount = {
        id: 'USR_MASTER', name: 'Administrador Axis', email: ADMIN_EMAIL_AUTH, phone: '11999999999', role: UserRole.ADMIN, createdAt: new Date().toISOString(), lastLogin: 'Agora', status: 'active', passwordHash: targetHash
      };
      return [initialAdmin, ...parsed];
    } else {
      parsed[adminIdx].passwordHash = targetHash;
      parsed[adminIdx].status = 'active';
      return [...parsed];
    }
  });

  const [revenues, setRevenues] = useState<Revenue[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.REVENUES);
    return saved ? JSON.parse(saved) : SEED_REVENUES;
  });

  const [taxes, setTaxes] = useState<Tax[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.TAXES);
    return saved ? JSON.parse(saved) : [
      { id: 'T1', name: 'DAS Simples Nacional', amount: 1450.50, dueDate: '2024-05-20', status: 'pending', clientId: 'CLI_DEMO_01' }
    ];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.EMPLOYEES);
    return saved ? JSON.parse(saved) : SEED_EMPLOYEES;
  });

  const [documents, setDocuments] = useState<Document[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEYS.DOCUMENTS);
    return saved ? JSON.parse(saved) : [
      { id: 'D1', name: 'Contrato Social - Nexus.pdf', type: 'PDF', uploadDate: '2024-01-10', size: '1.2 MB', category: 'contract', ownerId: 'CLI_DEMO_01' }
    ];
  });

  useEffect(() => { localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(clients)); }, [clients]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(userAccounts)); }, [userAccounts]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.REVENUES, JSON.stringify(revenues)); }, [revenues]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAXES, JSON.stringify(taxes)); }, [taxes]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.EMPLOYEES, JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.DOCUMENTS, JSON.stringify(documents)); }, [documents]);
  useEffect(() => { localStorage.setItem(STORAGE_KEYS.TAX_RULES, JSON.stringify(taxRules)); }, [taxRules]);

  const handleLogin = (email: string, pass: string) => {
    const normalizedEmailInput = email.trim().toLowerCase();
    const cleanPass = pass.trim();
    const hashedInput = btoa(cleanPass);
    const account = userAccounts.find(u => u.email.trim().toLowerCase() === normalizedEmailInput && u.passwordHash === hashedInput);

    if (account) {
      if (account.status !== 'active' && account.email !== ADMIN_EMAIL_AUTH) { 
        alert("Acesso Bloqueado."); return; 
      }
      const user: User = { id: account.id, name: account.name, email: account.email, role: account.role, cnpjVinculado: account.cnpjVinculado };
      setCurrentUser(user);
      if (user.role === UserRole.CLIENT && user.cnpjVinculado) {
        const client = clients.find(c => c.identifier === user.cnpjVinculado);
        if (client) setFocusedClient(client);
        setAdminVisualizationMode(false);
      }
      setCurrentView(View.DASHBOARD);
    } else {
      alert("Usuário ou senha incorretos.");
    }
  };

  const handleAccessClient = (client: Client) => {
    setFocusedClient(client);
    setAdminVisualizationMode(true);
    setCurrentView(View.DASHBOARD);
  };

  const handleClearFocus = () => {
    setFocusedClient(null);
    setAdminVisualizationMode(false);
  };

  const renderContent = () => {
    if (!currentUser) return null;
    const commonProps = { 
      focusedClient, revenues, setRevenues, taxes, setTaxes, documents, setDocuments, 
      employees, setEmployees, selectedMonthIdx, setSelectedMonthIdx, currentUser, clients, 
      users: userAccounts, setUsers: setUserAccounts, taxRules, setTaxRules, onViewChange: setCurrentView, adminVisualizationMode
    };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} onSelectClient={handleAccessClient} onAddClient={(c) => setClients(p => [c, ...p])} onDeleteClient={(id) => setClients(p => p.filter(x => x.id !== id))} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} userRole={currentUser.role} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.INTELLIGENT_TAX: return <IntelligentTaxManager {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      case View.SIMPLES_CALCULATOR: return <SimplesCalculator {...commonProps} onSaveCalculation={() => {}} history={[]} />;
      case View.PEOPLE_MANAGEMENT: return <PeopleManagement {...commonProps} />;
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex bg-[#F8FAFC] font-sans">
      <Sidebar 
        currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role} isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
        onLogout={() => { setCurrentUser(null); setFocusedClient(null); setAdminVisualizationMode(false); setCurrentView(View.DASHBOARD); }} 
        hasActiveFocus={!!focusedClient} onClearFocus={handleClearFocus} adminVisualizationMode={adminVisualizationMode}
      />
      <main className={`flex-1 transition-all duration-300 w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
        <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Employee, Client, User, UserRole, JourneyLog } from '../types';

interface PeopleManagementProps {
  focusedClient?: Client | null;
  currentUser?: User | null;
  employees: Employee[];
  setEmployees: React.Dispatch<React.SetStateAction<Employee[]>>;
  adminVisualizationMode?: boolean;
}

const PeopleManagement: React.FC<PeopleManagementProps> = ({ 
  focusedClient, 
  currentUser, 
  employees, 
  setEmployees, 
  adminVisualizationMode = false 
}) => {
  const [showAddEmployeeModal, setShowAddEmployeeModal] = useState(false);
  const [selectedEmployeeId, setSelectedEmployeeId] = useState<string | null>(null);
  const [logFormData, setLogFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'overtime' as 'overtime' | 'deduction' | 'absence',
    hours: '',
    notes: ''
  });

  const isAdmin = currentUser?.role === UserRole.ADMIN;
  const isReadOnly = (isAdmin && adminVisualizationMode) || currentUser?.role === UserRole.CLIENT;

  const filteredEmployees = useMemo(() => {
    return focusedClient ? employees.filter(e => e.clientId === focusedClient.id) : [];
  }, [employees, focusedClient]);

  const selectedEmployee = useMemo(() => {
    return employees.find(e => e.id === selectedEmployeeId);
  }, [employees, selectedEmployeeId]);

  const stats = useMemo(() => {
    const active = filteredEmployees.filter(e => e.status !== 'resigned').length;
    const totalPayroll = filteredEmployees.filter(e => e.status !== 'resigned').reduce((acc, e) => acc + e.salary, 0);
    return { active, totalPayroll, avgSalary: active > 0 ? totalPayroll / active : 0 };
  }, [filteredEmployees]);

  const handleAddJourneyLog = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployeeId || isReadOnly) return;

    const newLog: JourneyLog = {
      id: `LOG_${Date.now()}`,
      date: logFormData.date,
      type: logFormData.type,
      hours: parseFloat(logFormData.hours) || 0,
      notes: logFormData.notes.trim()
    };

    setEmployees(prev => prev.map(emp => {
      if (emp.id === selectedEmployeeId) {
        return {
          ...emp,
          journeyLogs: [newLog, ...(emp.journeyLogs || [])]
        };
      }
      return emp;
    }));

    setLogFormData({ ...logFormData, hours: '', notes: '' });
  };

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 pb-12">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm">
        <div className="space-y-1">
          <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em]">Inteligência em RH</p>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Gestão de Pessoas</h2>
          <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Controle de Colaboradores e Obrigações</p>
        </div>
        {!isReadOnly && focusedClient && (
          <button onClick={() => setShowAddEmployeeModal(true)} className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all active:scale-95">
            Cadastrar Colaborador +
          </button>
        )}
      </header>

      {/* KPI GRID */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Colaboradores Ativos</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">{stats.active}</p>
        </div>
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Folha Mensal (Base)</p>
          <p className="text-3xl font-black text-blue-600 tracking-tighter">{fmt(stats.totalPayroll)}</p>
        </div>
        <div className="bg-slate-900 p-8 rounded-[2rem] text-white shadow-xl">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Salário Médio</p>
          <p className="text-3xl font-black text-white tracking-tighter">{fmt(stats.avgSalary)}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* LISTA DE COLABORADORES */}
        <div className="lg:col-span-12 xl:col-span-4 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden h-fit">
          <div className="p-6 border-b border-slate-50 bg-slate-50/30">
             <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Quadro de Funcionários</h3>
          </div>
          <div className="divide-y divide-slate-50">
            {filteredEmployees.length > 0 ? filteredEmployees.map(emp => (
              <button 
                key={emp.id} 
                onClick={() => setSelectedEmployeeId(emp.id)}
                className={`w-full p-6 text-left hover:bg-slate-50/50 transition-all flex items-center space-x-4 border-l-4 ${
