import { Client, UserAccount, Revenue, Tax, Employee, Document, TaxRules } from '../types';

/**
 * AXIS CENTRAL API SERVICE
 * "Os dados pertencem ao usuário, não ao dispositivo."
 * 
 * Este serviço gerencia a persistência em nuvem centralizada da AXIS.
 * NÃO possui qualquer integração com Banco Central (BACEN), Open Finance ou Bancos.
 * Todo o controle é baseado em dados fornecidos manualmente pelo usuário.
 */

export const centralApi = {
  /**
   * Busca todo o conjunto de dados vinculado a um usuário/empresa na Nuvem Axis
   */
  async fetchUserData(email: string) {
    console.log(`[CLOUD AXIS] Sincronizando dados para: ${email}`);

    // Simula latência de rede para garantir feedback visual de nuvem
    await new Promise(resolve => setTimeout(resolve, 800));

    // Recupera do Repositório Central (Persistência por Identidade)
    const cloudSnapshot = localStorage.getItem(`axis_cloud_db_${email.toLowerCase()}`);

    if (cloudSnapshot) {
      return JSON.parse(cloudSnapshot);
    }
    return null;
  },

  /**
   * Salva o estado atual no Repositório Central da Nuvem
   */
  async syncToCloud(email: string, data: any) {
    return new Promise((resolve) => {
      setTimeout(() => {
        localStorage.setItem(`axis_cloud_db_${email.toLowerCase()}`, JSON.stringify(data));
        console.log(`[CLOUD AXIS] ✅ Sincronização Concluída. "Seu sistema te acompanha onde você estiver."`);
        resolve(true);
      }, 300);
    });
  }
};

