import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import DocumentManager from './components/DocumentManager';
import TaxTracker from './components/TaxTracker';
import RevenueSchedule from './components/RevenueSchedule';
import AIChat from './components/AIChat';
import ClientManagement from './components/ClientManagement';
import IntelligentTaxManager from './components/IntelligentTaxManager';
import PayrollManager from './components/PayrollManager';
import PricingCalculator from './components/PricingCalculator';
import AdminUserManager from './components/AdminUserManager';
import SimplesCalculator from './components/SimplesCalculator';
import PeopleManagement from './components/PeopleManagement';
import Settings from './components/Settings';
import Login from './components/Login';
import { centralApi } from './services/apiService';
import { View, UserRole, User, Client, UserAccount, Revenue, Tax, Employee, Document, TaxRules } from './types';

const ADMIN_EMAIL_AUTH = 'adm@ad.com';
const DEFAULT_ADMIN_PASS = '12345';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(window.innerWidth < 768);
  const [selectedMonthIdx, setSelectedMonthIdx] = useState<number>(new Date().getMonth());
  const [focusedClient, setFocusedClient] = useState<Client | null>(null);
  const [adminVisualizationMode, setAdminVisualizationMode] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isInitialLoading, setIsInitialLoading] = useState(false);

  // ESTADOS GLOBAIS (Sincronizados com Nuvem Axis)
  const [taxRules, setTaxRules] = useState<TaxRules>({ monofasicoHasPisCofins: false, isentoHasPisCofins: false });
  const [clients, setClients] = useState<Client[]>([]);
  const [userAccounts, setUserAccounts] = useState<UserAccount[]>([]);
  const [revenues, setRevenues] = useState<Revenue[]>([]);
  const [taxes, setTaxes] = useState<Tax[]>([]);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);

  /**
   * CARREGAMENTO CENTRALIZADO (REGRA DE OURO)
   */
  const loadCentralData = useCallback(async (userEmail: string) => {
    setIsInitialLoading(true);
    const data = await centralApi.fetchUserData(userEmail);

    if (data) {
      setTaxRules(data.taxRules || { monofasicoHasPisCofins: false, isentoHasPisCofins: false });
      setClients(data.clients || []);
      setUserAccounts(data.userAccounts || []);
      setRevenues(data.revenues || []);
      setTaxes(data.taxes || []);
      setEmployees(data.employees || []);
      setDocuments(data.documents || []);
    }
    setIsInitialLoading(false);
  }, []);

  /**
   * SINCRONIZAÇÃO IMEDIATA COM A NUVEM AXIS
   */
  useEffect(() => {
    if (currentUser && !isInitialLoading) {
      const sync = async () => {
        setIsSyncing(true);
        await centralApi.syncToCloud(currentUser.email, {
          taxRules, clients, userAccounts, revenues, taxes, employees, documents
        });
        setIsSyncing(false);
      };

      const timer = setTimeout(sync, 500); 
      return () => clearTimeout(timer);
    }
  }, [currentUser, taxRules, clients, userAccounts, revenues, taxes, employees, documents, isInitialLoading]);

  const handleLogin = async (email: string, pass: string) => {
    const normalizedEmail = email.trim().toLowerCase();
    const cleanPass = pass.trim();

    if (normalizedEmail === ADMIN_EMAIL_AUTH && cleanPass === DEFAULT_ADMIN_PASS) {
      const admin: User = { id: 'USR_MASTER', name: 'Administrador Axis', email: normalizedEmail, role: UserRole.ADMIN };
      setCurrentUser(admin);
      await loadCentralData(normalizedEmail);
      setCurrentView(View.DASHBOARD);
    } else {
      const data = await centralApi.fetchUserData(normalizedEmail);
      if (data && data.userAccounts) {
        const acc = data.userAccounts.find((u: any) => u.email.toLowerCase() === normalizedEmail && u.passwordHash === btoa(cleanPass));
        if (acc) {
          setCurrentUser({ id: acc.id, name: acc.name, email: acc.email, role: acc.role, cnpjVinculado: acc.cnpjVinculado });
          await loadCentralData(normalizedEmail);
          if (acc.cnpjVinculado) {
             const client = data.clients?.find((c: any) => c.identifier === acc.cnpjVinculado);
             if (client) setFocusedClient(client);
          }
          setCurrentView(View.DASHBOARD);
          return;
        }
      }
      alert("Credenciais inválidas ou usuário não encontrado no repositório central.");
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setFocusedClient(null);
    setAdminVisualizationMode(false);
    setClients([]);
    setRevenues([]);
    setEmployees([]);
  };

  const renderContent = () => {
    if (isInitialLoading) return (
      <div className="h-96 flex flex-col items-center justify-center space-y-4">
        <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Sincronizando Nuvem Axis...</p>
      </div>
    );

    const commonProps = { 
      focusedClient, revenues, setRevenues, taxes, setTaxes, documents, setDocuments, 
      employees, setEmployees, selectedMonthIdx, setSelectedMonthIdx, currentUser, clients, 
      users: userAccounts, setUsers: setUserAccounts, taxRules, setTaxRules, onViewChange: setCurrentView, adminVisualizationMode
    };

    switch (currentView) {
      case View.DASHBOARD: return <Dashboard {...commonProps} />;
      case View.CLIENTS: return <ClientManagement {...commonProps} onSelectClient={(c) => { setFocusedClient(c); setAdminVisualizationMode(true); setCurrentView(View.DASHBOARD); }} onAddClient={(c) => setClients(p => [c, ...p])} onDeleteClient={(id) => setClients(p => p.filter(x => x.id !== id))} />;
      case View.DOCUMENTS: return <DocumentManager {...commonProps} />;
      case View.TAXES: return <TaxTracker {...commonProps} userRole={currentUser?.role} />;
      case View.REVENUE: return <RevenueSchedule {...commonProps} />;
      case View.INTELLIGENT_TAX: return <IntelligentTaxManager {...commonProps} />;
      case View.AI_CHAT: return <AIChat {...commonProps} />;
      case View.ADMIN_USERS: return <AdminUserManager {...commonProps} />;
      case View.SETTINGS: return <Settings {...commonProps} />;
      case View.PAYROLL: return <PayrollManager {...commonProps} />;
      case View.PRICING_CALCULATOR: return <PricingCalculator {...commonProps} />;
      case View.SIMPLES_CALCULATOR: return <SimplesCalculator {...commonProps} onSaveCalculation={() => {}} history={[]} />;
      case View.PEOPLE_MANAGEMENT: return <PeopleManagement {...commonProps} />;
      default: return <Dashboard {...commonProps} />;
    }
  };

  if (!currentUser) return <Login onLogin={handleLogin} />;

  return (
    <div className="min-h-[100dvh] flex flex-col bg-[#F8FAFC] font-sans">
      <div className="flex flex-1">
        <Sidebar 
          currentView={currentView} onViewChange={setCurrentView} userRole={currentUser.role} isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed}
          onLogout={handleLogout} hasActiveFocus={!!focusedClient} onClearFocus={() => { setFocusedClient(null); setAdminVisualizationMode(false); }} adminVisualizationMode={adminVisualizationMode}
        />
        <main className={`flex-1 transition-all duration-300 w-full ${isSidebarCollapsed ? 'md:ml-[68px]' : 'md:ml-64'}`}>
          {/* INDICADOR DE SINCRONISMO (NÃO BANCÁRIO) */}
          <div className="fixed top-4 right-8 z-[60] flex items-center space-x-2 bg-white/80 backdrop-blur px-3 py-1.5 rounded-full border border-slate-100 shadow-sm transition-all hover:shadow-md">
             <div className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`}></div>
             <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">
               {isSyncing ? 'Sincronizando Nuvem...' : 'Nuvem Axis: Conectada'}
             </span>
          </div>

          <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-screen">
            {renderContent()}
          </div>

          {/* RODAPÉ DE SEGURANÇA */}
          <footer className="p-8 border-t border-slate-100 text-center">
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">
              “Seu sistema te acompanha onde você estiver.”
            </p>
          </footer>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar, Cell } from 'recharts';
import { FinancialMetric, Client, UserRole, Revenue, Employee } from '../types';

interface DashboardProps {
  focusedClient?: Client | null;
  userRole?: UserRole;
  revenues?: Revenue[];
  employees?: Employee[];
}

type Period = 'daily' | 'weekly' | 'monthly' | 'annual';

const Dashboard: React.FC<DashboardProps> = ({ focusedClient, userRole, revenues = [], employees = [] }) => {
  const [period, setPeriod] = useState<Period>('monthly');

  // Filtro de Datas Reativo
  const filterByPeriod = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();

    switch (period) {
      case 'daily':
        return date.toDateString() === now.toDateString();
      case 'weekly':
        const oneWeekAgo = new Date();
        oneWeekAgo.setDate(now.getDate() - 7);
        return date >= oneWeekAgo && date <= now;
      case 'monthly':
        return date.getMonth() === now.getMonth() && date.getFullYear() === now.getFullYear();
      case 'annual':
        return date.getFullYear() === now.getFullYear();
      default:
        return true;
    }
  };

  // Cálculos Consolidados
  const summary = useMemo(() => {
    const relevantRevenues = focusedClient 
      ? revenues.filter(r => r.clientId === focusedClient.id) 
      : revenues;

    const relevantEmployees = focusedClient
      ? employees.filter(e => e.clientId === focusedClient.id)
      : employees;

    const filteredRevenues = relevantRevenues.filter(r => filterByPeriod(r.date));

    const inflow = filteredRevenues.filter(r => r.entryType === 'inflow').reduce((acc, r) => acc + r.amount, 0);
    const outflow = filteredRevenues.filter(r => r.entryType === 'outflow').reduce((acc, r) => acc + r.amount, 0);

    // Custo de Pessoal (Proporcional ao período)
    const monthlyPayroll = relevantEmployees.reduce((acc, e) => acc + e.salary, 0);
    let periodPayroll = 0;
    if (period === 'daily') periodPayroll = monthlyPayroll / 30;
    else if (period === 'weekly') periodPayroll = (monthlyPayroll / 30) * 7;
    else if (period === 'monthly') periodPayroll = monthlyPayroll;
    else if (period === 'annual') periodPayroll = monthlyPayroll * 12;

    const totalExpenses = outflow + periodPayroll;
    const profit = inflow - totalExpenses;
    const margin = inflow > 0 ? (profit / inflow) * 100 : 0;

    // Score de Saúde (0-100)
    let healthScore = 50;
    if (inflow > 0) {
      healthScore += (margin / 2); // Margem impacta 50%
      const debtRatio = totalExpenses / inflow;
      healthScore -= (debtRatio * 20); // Endividamento subtrai até 20 pontos
    }
    healthScore = Math.min(100, Math.max(0, healthScore));

    // Ponto de Equilíbrio (Simplificado: Custos Totais / 0.7 - estimando margem de 30%)
    const breakEven = totalExpenses / 0.7;

    // Métricas de Pessoas
    const totalExtraHours = relevantEmployees.reduce((acc, emp) => {
      const logs = emp.journeyLogs?.filter(l => filterByPeriod(l.date)) || [];
      return acc + logs.filter(l => l.type === 'overtime').reduce((sum, l) => sum + l.hours, 0);
    }, 0);

    const totalAbsences = relevantEmployees.reduce((acc, emp) => {
      const logs = emp.journeyLogs?.filter(l => filterByPeriod(l.date)) || [];
      return acc + logs.filter(l => l.type === 'absence').reduce((sum, l) => sum + l.hours, 0);
    }, 0);

    return {
      inflow,
      outflow: totalExpenses,
      profit,
      margin,
      healthScore,
      breakEven,
      people: {
        count: relevantEmployees.length,
        payroll: periodPayroll,
        extraHours: totalExtraHours,
        absences: totalAbsences
      },
      chartData: filteredRevenues.map(r => ({
        name: new Date(r.date).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }),
        value: r.amount,
        type: r.entryType
      }))
    };
  }, [revenues, employees, focusedClient, period]);

  const fmt = (v: number) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* SELETOR DE PERÍODO CENTRALIZADO */}
      <header className="flex flex-col md:flex-row justify-between items-center gap-6 bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
        <div className="flex items-center space-x-4">
           <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center text-2xl shadow-xl">📊</div>
           <div>
              <h2 className="text-xl font-black text-slate-800 tracking-tight uppercase">Painel de Controle Axis</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Monitoramento Operacional em Tempo Real</p>
           </div>
        </div>

        <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
          {(['daily', 'weekly', 'monthly', 'annual'] as Period[]).map((p) => (
            <button
              key={p}
              onClick={() => setPeriod(p)}
              className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                period === p ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-800'
              }`}
            >
              {p === 'daily' ? 'Hoje' : p === 'weekly' ? 'Semana' : p === 'monthly' ? 'Mês' : 'Ano'}
            </button>
          ))}
        </div>
      </header>

      {/* GRID DE KPIs FINANCEIROS */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500/5 rounded-full -translate-y-8 translate-x-8"></div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Faturamento (Entradas)</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">{fmt(summary.inflow)}</p>
          <div className="mt-4 flex items-center text-[10px] font-bold text-emerald-500 uppercase">
             <span className="mr-1">▲</span> 100% Lançamento Manual
          </div>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Despesas Totais</p>
          <p className="text-3xl font-black text-slate-900 tracking-tighter">{fmt(summary.outflow)}</p>
          <p className="text-[9px] text-slate-400 mt-2 font-black uppercase">Inclui Gastos + Folha</p>
        </div>

        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Lucro Estimado</p>
          <p className={`text-3xl font-black tracking-tighter ${summary.profit >= 0 ? 'text-blue-600' : 'text-red-600'}`}>
            {fmt(summary.profit)}
          </p>
          <div className="mt-2 h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
